  insert into public.t3a_d1_branch_rule(dimension_id, rule_code, rule_condition, rule_effect, rule_order) values ('D8','BR-D8-05','Q-D8-05 returns A1','Q-D8-05b served. Which commitments exists only once some, but not all, of the listed commitments were named; where every one was named no selection is needed',5);
  insert into public.t3a_d1_branch_rule(dimension_id, rule_code, rule_condition, rule_effect, rule_order) values ('D8','BR-D8-06','Q-D8-06 returns A1, A2','Q-D8-06b served. Which work exists once work was named as continuing, whether or not a point was stated',6);
  insert into public.t3a_d1_branch_rule(dimension_id, rule_code, rule_condition, rule_effect, rule_order) values ('D8','BR-D8-07','Q-D8-07 returns A1','Q-D8-07b served. Which measures exists only once a listed measure was stated',7);
  insert into public.t3a_content_object(identifier, family, title, dimension_id, current_operational_state) values ('T3A-D8-EXEC-001-CONSTRUCT', 'construct'::public.t3a_content_family, 'D8 construct', 'D8', 'not_applicable'::public.t3a_operational_state);
  insert into public.t3a_d1_content_version(content_object_id, version_no, approval_status, operational_state, body) select content_object_id, 'v2.1', 'drafting', 'not_applicable'::public.t3a_operational_state, '{"situation_classes": {"SC-D8-1": {"situation": "An error by the participant has become known beyond the participant", "pattern_family": "IPF-D8-01"}, "SC-D8-2": {"situation": "Sustained work has been ended, rejected or withdrawn by a decision the source places outside the participant''s control", "pattern_family": "IPF-D8-02"}, "SC-D8-3": {"situation": "A failure, violation or defect has been formally recorded against work the participant holds", "pattern_family": "IPF-D8-03"}, "SC-D8-4": {"situation": "A condition that has disrupted the work before has produced the same disruption again", "pattern_family": "IPF-D8-04"}, "SC-D8-5": {"situation": "An expected advancement, selection or recognition has not come", "pattern_family": "IPF-D8-05"}, "SC-D8-6": {"situation": "The work must continue while the people, tools or resources that supported it have been reduced or removed", "pattern_family": "IPF-D8-06"}, "SC-D8-7": {"situation": "An attribution about the participant has been made in front of others or is circulating", "pattern_family": "IPF-D8-07"}}, "conduct_elements": {"CE-D8-01": {"name": "Containment action stated", "supports": "Which of the containment actions the source makes available the participant stated. The actions are listed by the source, so the selection is bounded and never judged", "does_not_support": "Any claim about presence of mind, speed or calm, or that an act was performed. An action stated late is recorded as a statement, not as a delay"}, "CE-D8-02": {"name": "Facts about the setback named", "supports": "Which of the facts the source designates the participant named as established or to be established", "does_not_support": "Any claim about thoroughness, and any claim about the order in which facts and actions came"}, "CE-D8-03": {"name": "Action on the condition stated", "supports": "Which of the actions the source makes available on the condition that produced the setback the participant stated", "does_not_support": "Any claim that the action was adequate, and never any statement about who is answerable, which is D2''s"}, "CE-D8-04": {"name": "Support stated as one to go to", "supports": "Which of the supports the source makes available the participant stated as one to go to. Supports are resources, authority, information or people, never emotional support, which is not observed", "does_not_support": "Any claim about self-reliance or its absence, and any inference from stating none"}, "CE-D8-05": {"name": "Commitments named as still to be met", "supports": "Which of the commitments in force the participant named as still to be met. The commitments are established by the source before observation", "does_not_support": "Any claim about priorities as a disposition, or that the right commitment was named"}, "CE-D8-06": {"name": "Continuation stated", "supports": "What work the participant named as continuing, and whether a point of resumption was stated. A stated resumption is an act of the participant and needs no reading of their state", "does_not_support": "Any claim that the participant recovered, resumed readily or was unaffected. A stated resumption is a statement, not a state"}, "CE-D8-07": {"name": "Measure against recurrence stated", "supports": "What the participant stated about the condition behind the setback arising again, against the measures the source lists. The condition need not have produced the setback before: a measure stated now is a statement about the condition, whatever its history", "does_not_support": "Any prediction that the measure works, or any judgment that it was sufficient"}, "CE-D8-08": {"name": "Record stated", "supports": "Whether the participant stated that the setback and what followed is to be recorded, and where", "does_not_support": "Any claim about accountability, which is D2''s, or about diligence"}, "CE-D8-09": {"name": "Statement when an earlier statement was put back", "supports": "What the participant stated when the source''s account test put an earlier statement back to them, against what the situation records", "does_not_support": "Any claim about consistency, defensiveness or self-awareness"}}, "coverage": {"CE-D8-01": ["Carried", "Carried", "Carried", "Carried"], "CE-D8-02": ["Carried", "Carried", "Carried", "Carried"], "CE-D8-03": ["Carried", "Carried", "Carried", "Carried"], "CE-D8-04": ["Carried", "Carried", "Carried", "Carried"], "CE-D8-05": ["Carried", "Carried", "Carried", "Carried"], "CE-D8-06": ["Carried", "Carried", "Carried", "Carried"], "CE-D8-07": ["Carried", "Carried", "Carried", "Carried"], "CE-D8-08": ["Carried", "Carried", "Carried", "Carried"], "CE-D8-09": ["Carried", "Carried", "NOT IN LAUNCH DESIGN", "Carried"]}, "source_fields": {"permitted_administration_variance": {"type": "text", "stages": "1, 2, 3, 4", "holds": "The administration variance the source permits, recorded wherever it occurs"}, "unsupported_inferences": {"type": "text", "stages": "1, 2, 3, 4", "holds": "The inferences the source must never support"}, "compatibility_class": {"type": "text", "stages": "1, 2, 3, 4", "holds": "The delivery form class of the source, derived from its Stage"}, "setback_established": {"type": "text", "stages": "1, 2, 3, 4", "holds": "Where the participant meets the setback the source establishes. The setback is always a work event, never a personal or health circumstance"}, "containment_actions": {"type": "list: CA", "stages": "1, 2, 3, 4", "holds": "The actions the source makes available to stop the setback spreading; consumed by Q-D8-01b. Each is an act on the work, never an act on oneself"}, "corrective_actions": {"type": "list: CR", "stages": "1, 2, 3, 4", "holds": "The actions the source makes available on the condition that produced the setback; consumed by Q-D8-03b. An action may appear here and in containment_actions, and each control records it separately"}, "designated_facts": {"type": "list: DF", "stages": "1, 2, 3, 4", "holds": "The facts about the setback the participant could name as established or to be established; consumed by Q-D8-02b"}, "available_supports": {"type": "list: SU", "stages": "1, 2, 3, 4", "holds": "The supports the source makes available: resources, authority, information or people, never emotional support; consumed by Q-D8-04b"}, "standing_commitments": {"type": "list: CM, mapped", "stages": "1, 2, 3, 4", "holds": "The commitments in force at the moment of the setback, each quoted in the material map; consumed by Q-D8-05b"}, "work_in_progress": {"type": "list: WP", "stages": "1, 2, 3, 4", "holds": "The work under way at the moment of the setback; consumed by Q-D8-06b"}, "recurrence_measures": {"type": "list: RM", "stages": "1, 2, 3, 4", "holds": "The measures the source makes available against the condition behind the setback arising again; consumed by Q-D8-07b. Every D8 source lists them, whether or not the condition has produced the setback before"}, "recurring_condition": {"type": "text", "stages": "1, 2, 3, 4", "holds": "The condition the source establishes as having produced the same setback before, or None. It is situation context only: Q-D8-07 is served wherever recurrence_measures is not empty, whatever this field says"}, "formal_record_state": {"type": "text", "stages": "1, 2, 3, 4", "holds": "What the source establishes about any formal record already made of the setback, or None"}, "record_place": {"type": "text", "stages": "1, 2, 3, 4", "holds": "The place a record could be made, or None"}, "who_knows": {"type": "text", "stages": "1, 2, 3, 4", "holds": "The parties the source establishes as already aware of the setback. Retained for source truth; never rendered, never on the mentor reference card, never the subject of any entry"}, "decision_origin": {"type": "text", "stages": "1, 2, 3, 4", "holds": "Where the source places the decision that produced the setback, or None. Retained for source truth; never rendered, never on the mentor reference card, never the subject of any entry"}, "account_test_point": {"type": "point: Account test", "stages": "1, 2, 4", "holds": "The reveal or beat at which an earlier statement is put back to the participant, or None"}, "account_test_record": {"type": "text", "stages": "1, 2, 4", "holds": "What the situation records on the point the account test puts back, which is the reference for entries ST-D8-041 and ST-D8-042, or None"}, "list_note": {"type": "text", "stages": "1, 2, 3, 4", "holds": "Why a list is empty, and any item withheld from a list as not offered, or None"}, "source_note": {"type": "text", "stages": "1, 2, 3, 4", "holds": "A shared Stage 3 submission, a re-framing or other situation context the source carries, or None"}, "situation_class_label": {"type": "text", "stages": "1, 2, 3, 4", "holds": "One approved generic phrase naming the kind of situation; never the source title or scenario detail"}, "observation_mode_label": {"type": "enum: written_response, structured_live_session, work_sample, group_session", "stages": "1, 2, 3, 4", "holds": "The observation mode of the Stage at which the source is served"}}, "source": "T3A-D8-EXEC-001 v2.1"}'::jsonb from public.t3a_content_object where identifier = 'T3A-D8-EXEC-001-CONSTRUCT' and family = 'construct'::public.t3a_content_family;
  insert into public.t3a_content_object(identifier, family, title, dimension_id, current_operational_state) values ('T3A-D8-EXEC-001-DETERMINATION', 'determination_question_set'::public.t3a_content_family, 'D8 determination set', 'D8', 'not_applicable'::public.t3a_operational_state);
  insert into public.t3a_d1_content_version(content_object_id, version_no, approval_status, operational_state, body) select content_object_id, 'v2.1', 'drafting', 'not_applicable'::public.t3a_operational_state, '{"questions": {"Q-D8-01": {"element": "CE-D8-01", "capture_set": "C1", "answer_type": "Single select, fixed", "source_bound_to": "—", "served_when": "Always where the element is in play"}, "Q-D8-01b": {"element": "CE-D8-01", "capture_set": "C1b", "answer_type": "Bound selection, one or more", "source_bound_to": "containment_actions", "served_when": "C1 records a containment action the source makes available"}, "Q-D8-02": {"element": "CE-D8-02", "capture_set": "C2", "answer_type": "Single select, fixed", "source_bound_to": "—", "served_when": "Always where the element is in play"}, "Q-D8-02b": {"element": "CE-D8-02", "capture_set": "C2b", "answer_type": "Bound selection, one or more", "source_bound_to": "designated_facts", "served_when": "C2 records a designated fact named"}, "Q-D8-03": {"element": "CE-D8-03", "capture_set": "C3", "answer_type": "Single select, fixed", "source_bound_to": "—", "served_when": "Always where the element is in play"}, "Q-D8-03b": {"element": "CE-D8-03", "capture_set": "C3b", "answer_type": "Bound selection, one or more", "source_bound_to": "corrective_actions", "served_when": "C3 records an action on the condition the source makes available"}, "Q-D8-04": {"element": "CE-D8-04", "capture_set": "C4", "answer_type": "Single select, fixed", "source_bound_to": "—", "served_when": "Always where the element is in play"}, "Q-D8-04b": {"element": "CE-D8-04", "capture_set": "C4b", "answer_type": "Bound selection, one or more", "source_bound_to": "available_supports", "served_when": "C4 records a support the source makes available"}, "Q-D8-05": {"element": "CE-D8-05", "capture_set": "C5", "answer_type": "Single select, fixed", "source_bound_to": "—", "served_when": "Always where the element is in play"}, "Q-D8-05b": {"element": "CE-D8-05", "capture_set": "C5b", "answer_type": "Bound selection, one or more", "source_bound_to": "standing_commitments", "served_when": "C5 records some of the listed commitments named"}, "Q-D8-06": {"element": "CE-D8-06", "capture_set": "C6", "answer_type": "Single select, fixed", "source_bound_to": "—", "served_when": "Always where the element is in play"}, "Q-D8-06b": {"element": "CE-D8-06", "capture_set": "C6b", "answer_type": "Bound selection, one or more", "source_bound_to": "work_in_progress", "served_when": "C6 records work named as continuing"}, "Q-D8-07": {"element": "CE-D8-07", "capture_set": "C7", "answer_type": "Single select, fixed", "source_bound_to": "—", "served_when": "Source lists recurrence measures"}, "Q-D8-07b": {"element": "CE-D8-07", "capture_set": "C7b", "answer_type": "Bound selection, one or more", "source_bound_to": "recurrence_measures", "served_when": "C7 records a measure the source makes available"}, "Q-D8-08": {"element": "CE-D8-08", "capture_set": "C8", "answer_type": "Single select, fixed", "source_bound_to": "—", "served_when": "Always where the element is in play"}, "Q-D8-09": {"element": "CE-D8-09", "capture_set": "C9", "answer_type": "Single select, fixed", "source_bound_to": "—", "served_when": "Source carries account_test_point"}}, "capture_sets": {"C1": {"title": "Which containment action the participant stated", "lines": ["Stated a containment action from those the source makes available.", "Stated a containment action the source does not make available.", "Stated no containment action during the observation."], "bound": null, "type": "content", "whole_session": "Stated no containment action during the observation."}, "C1b": {"title": "Which listed containment actions were stated", "lines": ["LISTED Selected each listed containment action stated.", "LISTED + STATED_UNLISTED_ACTION Selected the listed containment actions stated and a containment action outside the list."], "bound": {"field": "containment_actions", "selection": "one or more"}, "type": "content", "whole_session": "—"}, "C2": {"title": "Which facts about the setback the participant named", "lines": ["Named one or more of the facts about the setback the source designates.", "Named a fact about the setback the source does not designate.", "Named no fact about the setback during the observation."], "bound": null, "type": "content", "whole_session": "Named no fact about the setback during the observation."}, "C2b": {"title": "Which designated facts were named", "lines": ["LISTED Selected each designated fact named.", "LISTED + NAMED_UNLISTED_FACT Selected the designated facts named and a fact outside the list."], "bound": {"field": "designated_facts", "selection": "one or more"}, "type": "content", "whole_session": "—"}, "C3": {"title": "What the participant stated about the condition behind the setback", "lines": ["Stated an action on the condition behind the setback from those the source makes available.", "Stated an action on the condition behind the setback the source does not make available.", "Stated no action on the condition behind the setback during the observation."], "bound": null, "type": "content", "whole_session": "Stated no action on the condition behind the setback during the observation."}, "C3b": {"title": "Which listed actions on the condition were stated", "lines": ["LISTED Selected each listed action on the condition stated.", "LISTED + STATED_UNLISTED_CORRECTION Selected the listed actions on the condition stated and an action on the condition outside the list."], "bound": {"field": "corrective_actions", "selection": "one or more"}, "type": "content", "whole_session": "—"}, "C4": {"title": "Which support or resource the participant stated as one to go to", "lines": ["Stated a support to go to from those the source makes available.", "Stated a support to go to that the source does not make available.", "Stated no support to go to during the observation."], "bound": null, "type": "content", "whole_session": "Stated no support to go to during the observation."}, "C4b": {"title": "Which listed supports were stated", "lines": ["LISTED Selected each listed support stated.", "LISTED + STATED_UNLISTED_SUPPORT Selected the listed supports stated and a support outside the list."], "bound": {"field": "available_supports", "selection": "one or more"}, "type": "content", "whole_session": "—"}, "C5": {"title": "Which commitments in force the participant named as still to be met", "lines": ["Named some, but not all, of the commitments the source lists as still to be met.", "Named every commitment the source lists as still to be met.", "Named no commitment as still to be met during the observation."], "bound": null, "type": "content", "whole_session": "Named no commitment as still to be met during the observation."}, "C5b": {"title": "Which listed commitments were named", "lines": ["LISTED Selected each listed commitment named as still to be met.", "LISTED + NAMED_UNLISTED_COMMITMENT Selected the listed commitments named as still to be met and a commitment outside the list."], "bound": {"field": "standing_commitments", "selection": "one or more"}, "type": "content", "whole_session": "—"}, "C6": {"title": "What work the participant stated is to continue, and from when", "lines": ["Named work that is to continue and stated when it resumes.", "Named work that is to continue and stated no point at which it resumes.", "Stated that work is to continue and named none.", "Stated nothing about work continuing during the observation."], "bound": null, "type": "content", "whole_session": "Stated nothing about work continuing during the observation."}, "C6b": {"title": "Which items of work under way were named", "lines": ["LISTED Selected each item of work under way named as continuing.", "LISTED + NAMED_UNLISTED_WORK Selected the items of work under way named as continuing and an item of work outside the list."], "bound": {"field": "work_in_progress", "selection": "one or more"}, "type": "content", "whole_session": "—"}, "C7": {"title": "What the participant stated about the condition arising again", "lines": ["Stated a measure against the condition arising again from those the source makes available.", "Stated a measure against the condition arising again that the source does not make available.", "Stated that the condition can arise again and named no measure.", "Stated nothing about the condition arising again during the observation."], "bound": null, "type": "content", "whole_session": "Stated nothing about the condition arising again during the observation."}, "C7b": {"title": "Which listed measures were stated", "lines": ["LISTED Selected each listed measure stated.", "LISTED + STATED_UNLISTED_MEASURE Selected the listed measures stated and a measure outside the list."], "bound": {"field": "recurrence_measures", "selection": "one or more"}, "type": "content", "whole_session": "—"}, "C8": {"title": "Whether a record was stated, and where", "lines": ["Stated that a record is to be made and named where.", "Stated that a record is to be made and named no place for it.", "Stated no record during the observation."], "bound": null, "type": "content", "whole_session": "Stated no record during the observation."}, "C9": {"title": "What was stated when an earlier statement was put back to the participant", "lines": ["Stated content that corresponds to what the source records.", "Stated content that differs from what the source records.", "Stated that what was put back was not what they had said.", "Stated nothing about what was put back during the observation."], "bound": null, "type": "content", "whole_session": "Stated nothing about what was put back during the observation."}}, "branch_rules": {"BR-D8-01": {"child": "Q-D8-01b", "parent": "Q-D8-01", "serving_answers": ["A1"], "note": "Which containment actions exists only once a listed containment action was stated"}, "BR-D8-02": {"child": "Q-D8-02b", "parent": "Q-D8-02", "serving_answers": ["A1"], "note": "Which facts exists only once a designated fact was named"}, "BR-D8-03": {"child": "Q-D8-03b", "parent": "Q-D8-03", "serving_answers": ["A1"], "note": "Which actions on the condition exists only once a listed action on the condition was stated"}, "BR-D8-04": {"child": "Q-D8-04b", "parent": "Q-D8-04", "serving_answers": ["A1"], "note": "Which supports exists only once a listed support was stated"}, "BR-D8-05": {"child": "Q-D8-05b", "parent": "Q-D8-05", "serving_answers": ["A1"], "note": "Which commitments exists only once some, but not all, of the listed commitments were named; where every one was named no selection is needed"}, "BR-D8-06": {"child": "Q-D8-06b", "parent": "Q-D8-06", "serving_answers": ["A1", "A2"], "note": "Which work exists once work was named as continuing, whether or not a point was stated"}, "BR-D8-07": {"child": "Q-D8-07b", "parent": "Q-D8-07", "serving_answers": ["A1"], "note": "Which measures exists only once a listed measure was stated"}}, "source": "T3A-D8-EXEC-001 v2.1"}'::jsonb from public.t3a_content_object where identifier = 'T3A-D8-EXEC-001-DETERMINATION' and family = 'determination_question_set'::public.t3a_content_family;
  insert into public.t3a_content_object(identifier, family, title, dimension_id, current_operational_state) values ('T3A-D8-EXEC-001-STATEMENT-LIBRARY', 'statement_library'::public.t3a_content_family, 'D8 statement library', 'D8', 'not_applicable'::public.t3a_operational_state);
  insert into public.t3a_d1_content_version(content_object_id, version_no, approval_status, operational_state, body) select content_object_id, 'v2.1', 'drafting', 'not_applicable'::public.t3a_operational_state, '{"comparison_operators": {"ST-D8-041": {"operator": "Correspondence", "domain": "account_test_record"}, "ST-D8-042": {"operator": "Correspondence", "domain": "account_test_record"}}, "placeholder_grammar": {"stated_containment_count": {"kind": "count", "bound_to": "Q-D8-01b LISTED", "grammar": "whole number from 1 to the number of items in containment_actions"}, "named_fact_count": {"kind": "count", "bound_to": "Q-D8-02b LISTED", "grammar": "whole number from 1 to the number of items in designated_facts"}, "stated_correction_count": {"kind": "count", "bound_to": "Q-D8-03b LISTED", "grammar": "whole number from 1 to the number of items in corrective_actions"}, "stated_support_count": {"kind": "count", "bound_to": "Q-D8-04b LISTED", "grammar": "whole number from 1 to the number of items in available_supports"}, "named_commitment_count": {"kind": "count", "bound_to": "Q-D8-05b LISTED", "grammar": "whole number from 1 to the number of items in standing_commitments"}, "named_work_count": {"kind": "count", "bound_to": "Q-D8-06b LISTED", "grammar": "whole number from 1 to the number of items in work_in_progress"}, "stated_measure_count": {"kind": "count", "bound_to": "Q-D8-07b LISTED", "grammar": "whole number from 1 to the number of items in recurrence_measures"}}, "recurrence_keys": {"REK-D8-001": {"element": "CE-D8-01", "proposition": "A containment action was or was not stated", "material_variable": "Whether a containment action was stated", "contextual_variable": "Which action; the setback"}, "REK-D8-002": {"element": "CE-D8-02", "proposition": "Facts about the setback were or were not named", "material_variable": "Whether a designated fact was named", "contextual_variable": "Which facts"}, "REK-D8-003": {"element": "CE-D8-03", "proposition": "An action on the condition behind the setback was or was not stated", "material_variable": "Whether an action on the condition was stated", "contextual_variable": "Which action"}, "REK-D8-004": {"element": "CE-D8-04", "proposition": "A support to go to was or was not stated", "material_variable": "Whether a support was stated", "contextual_variable": "Which support"}, "REK-D8-005": {"element": "CE-D8-05", "proposition": "Commitments in force were or were not named as still to be met", "material_variable": "Whether some, all or none were named", "contextual_variable": "Which commitments"}, "REK-D8-006": {"element": "CE-D8-06", "proposition": "Work continuing was or was not named, with or without a point at which it resumes", "material_variable": "Whether both were stated", "contextual_variable": "Which work; from when"}, "REK-D8-007": {"element": "CE-D8-07", "proposition": "A measure against the condition arising again was or was not stated", "material_variable": "Whether a measure was stated", "contextual_variable": "Which measure"}, "REK-D8-008": {"element": "CE-D8-08", "proposition": "A record was or was not stated, with or without a place", "material_variable": "Whether both were stated", "contextual_variable": "Where"}, "REK-D8-009": {"element": "CE-D8-09", "proposition": "When an earlier statement was put back, what was stated did or did not correspond to what the situation records", "material_variable": "Whether it corresponded", "contextual_variable": "How far it differed"}}, "resolution_rules": {"RR-D8-01": {"pattern": "Q-D8-01=A1 + Q-D8-01b=UNANSWERED", "outcome": "REFUSE", "reason": "The parent records a listed containment action stated and the child identifies none"}, "RR-D8-02": {"pattern": "Q-D8-02=A1 + Q-D8-02b=UNANSWERED", "outcome": "REFUSE", "reason": "The parent records a designated fact named and the child identifies none"}, "RR-D8-03": {"pattern": "Q-D8-03=A1 + Q-D8-03b=UNANSWERED", "outcome": "REFUSE", "reason": "The parent records a listed action on the condit