  insert into public.t3a_content_object(identifier, family, title, dimension_id, current_operational_state) values ('SRC-D8-S1-001', 'source'::public.t3a_content_family, 'THE POST ON THE WRONG ACCOUNT', 'D8', 'not_loaded'::public.t3a_operational_state);
  insert into public.t3a_d1_content_version(content_object_id, version_no, approval_status, operational_state, body) select content_object_id, 'v2.1', 'drafting', 'not_loaded'::public.t3a_operational_state, '{"stage": 1, "title": "THE POST ON THE WRONG ACCOUNT", "source_digest": "9ef8a2a70f945a6f935a92096dd5d34e7d3db831e3e80f2c77ec316c2966121b", "situation": "You are a social media coordinator at a digital agency, managing accounts for four clients. Last night at 11:00 PM you scheduled a promotional post for one client and published it to a different client''s account. A twenty percent discount promotion for a casual dining chain went live on the account of a luxury skincare brand. It stayed up for six hours before anyone noticed.\n\nWhat the record shows: the post reached about 4,200 accounts and drew 38 comments before it was taken down at 5:15 AM by the overnight monitor; the skincare brand''s contract states that no content is published to their account without their written approval; the scheduling tool has a single client selector with no confirmation step; you have published to that tool about 400 times without this occurring; and the skincare brand''s account manager has a standing weekly call with you at 10:00 AM today.", "reveals": [{"code": "R1", "text": "What is the first thing you do, and to what?", "role": "Opening"}, {"code": "R2", "text": "What do you establish about what happened before you do anything further?", "role": "Information"}, {"code": "R3", "text": "What do you do about the thing that allowed it to happen?", "role": "Information"}, {"code": "R4", "text": "Whose help or what resource do you go to, if any?", "role": "Information"}, {"code": "R5", "text": "What still gets delivered today, and what work of yours resumes and from when?", "role": "Information"}, {"code": "R6", "text": "What do you do about it happening again, and what gets written down and where?", "role": "Information"}, {"code": "R7", "text": "At noon your manager writes: \"You told me this morning the post was down within the hour. Was it?\" What do you say?", "role": "Account test"}], "question_applicability": [{"question": "Q-D8-01", "state": "DIRECT", "basis": "The situation lists three containment actions"}, {"question": "Q-D8-01b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D8-02", "state": "DIRECT", "basis": "The situation designates four facts about the setback"}, {"question": "Q-D8-02b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D8-03", "state": "DIRECT", "basis": "The situation lists two actions on the condition behind the setback"}, {"question": "Q-D8-03b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D8-04", "state": "DIRECT", "basis": "The situation lists three supports"}, {"question": "Q-D8-04b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D8-05", "state": "DIRECT", "basis": "The situation lists three commitments in force"}, {"question": "Q-D8-05b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D8-06", "state": "DIRECT", "basis": "The situation lists two items of work under way"}, {"question": "Q-D8-06b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D8-07", "state": "DIRECT", "basis": "The situation lists three measures against the condition arising again"}, {"question": "Q-D8-07b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D8-08", "state": "DIRECT", "basis": "The situation names a place a record could be made"}, {"question": "Q-D8-09", "state": "DIRECT", "basis": "The account test puts an earlier statement back"}], "material_map": [{"Item": "CM1", "Item text": "the 10:00 AM weekly call with the skincare brand''s account manager", "Where the participant meets it": "The situation", "Quoted text": "has a standing weekly call with you at 10:00 AM today"}, {"Item": "CM2", "Item text": "the four client accounts the participant manages", "Where the participant meets it": "The situation", "Quoted text": "managing accounts for four clients"}, {"Item": "CM3", "Item text": "the dining chain''s promotion, which has still not been published", "Where the participant meets it": "The situation", "Quoted text": "discount promotion for a casual dining chain went live"}], "source_sheet": {"d8_situation_class": "SC-D8-1", "workplace_demand": "Continuing the day''s client work after a scheduled post was published to the wrong client''s account overnight.", "relevant_conduct": "Which containment action was stated; which facts about the setback were named; what action on the condition behind the setback was stated; which support was stated as one to go to; which commitments in force were named as still to be met; what work was named as continuing, and from when; what was stated about the condition arising again; whether a record was stated, and where; what was stated when an earlier statement was put back.", "irrelevant_conduct": "Who is answerable for the error, which is a D2 matter; the tool vendor; the client''s likely reaction.", "stated_standard": null, "stated_standard_source_quote_or_location": null, "cross_context_map": null, "serving_eligible": false, "recurrence_eligible": true, "replacement_required": false, "name_clearance_status": "CLEARED", "name_clearance_basis": "Controlled role and entity labels only; no real person or organization is named.", "sensitivity_flag": null, "permitted_administration_variance": "Pronunciation only; accommodations affecting turn order or response window are recorded and set timing_not_comparable.", "unsupported_inferences": "That the participant was careless, which is a judgment about the person; that acting quickly indicates anything; any observation of how the participant bore the error, including that they seemed unaffected.", "compatibility_class": "S1-WRITTEN-SEQUENTIAL", "setback_established": "In the situation: \"you published it to a different client''s account... it stayed up for six hours.\"", "containment_actions": [{"id": "CA1", "text": "confirm the post is down and capture what was published"}, {"id": "CA2", "text": "contact the skincare brand''s account manager before the 10:00 AM call"}, {"id": "CA3", "text": "pull the remaining scheduled posts for all four accounts pending a check"}], "corrective_actions": [{"id": "CR1", "text": "pull the remaining scheduled posts for all four accounts pending a check"}, {"id": "CR2", "text": "add a client-confirmation step to the scheduling routine"}], "designated_facts": [{"id": "DF1", "text": "what was published and to which account"}, {"id": "DF2", "text": "how long it was live and what reach it had"}, {"id": "DF3", "text": "whether any other scheduled post carries the same fault"}, {"id": "DF4", "text": "what the skincare brand''s contract requires about approval"}], "available_supports": [{"id": "SU1", "text": "the overnight monitor who took the post down"}, {"id": "SU2", "text": "the account lead for the skincare brand"}, {"id": "SU3", "text": "the agency''s client-communications template for published errors"}], "standing_commitments": [{"id": "CM1", "text": "the 10:00 AM weekly call with the skincare brand''s account manager"}, {"id": "CM2", "text": "the four client accounts the participant manages"}, {"id": "CM3", "text": "the dining chain''s promotion, which has still not been published"}], "work_in_progress": [{"id": "WP1", "text": "the four accounts'' scheduled content for today"}, {"id": "WP2", "text": "the dining chain''s promotional campaign"}], "recurrence_measures": [{"id": "RM1", "text": "a client-confirmation step before any scheduled publication"}, {"id": "RM2", "text": "a second-person check on any post scheduled outside working hours"}, {"id": "RM3", "text": "separate tool profiles per client account"}], "recurring_condition": null, "formal_record_state": null, "record_place": "The agency''s client incident log.", "who_knows": "The overnight monitor and the manager.", "decision_origin": null, "account_test_point": "R7", "account_test_record": "The situation records that the post stayed up for six hours before it was taken down.", "list_note": null, "source_note": null, "situation_class_label": "An error by the participant that has become known beyond them", "observation_mode_label": "written_response", "min_seconds": 360, "max_seconds": 1500}, "source_identifier": "SRC-D8-S1-001", "stage_code": "S1", "source_version_hash": "9ef8a2a70f945a6f935a92096dd5d34e7d3db831e3e80f2c77ec316c2966121b", "serving_eligible": false, "verbatim": "You are a social media coordinator at a digital agency, managing accounts for four clients. Last night at 11:00 PM you scheduled a promotional post for one client and published it to a different client''s account. A twenty percent discount promotion for a casual dining chain went live on the account of a luxury skincare brand. It stayed up for six hours before anyone noticed.\n\nWhat the record shows: the post reached about 4,200 accounts and drew 38 comments before it was taken down at 5:15 AM by the overnight monitor; the skincare brand''s contract states that no content is published to their account without their written approval; the scheduling tool has a single client selector with no confirmation step; you have published to that tool about 400 times without this occurring; and the skincare brand''s account manager has a standing weekly call with you at 10:00 AM today."}'::jsonb from public.t3a_content_object where identifier = 'SRC-D8-S1-001' and family = 'source'::public.t3a_content_family;
  insert into public.t3a_content_object(identifier, family, title, dimension_id, current_operational_state) values ('SRC-D8-S1-002', 'source'::public.t3a_content_family, 'THREE MONTHS, AND THE COMMITTEE CHOSE ANOTHER', 'D8', 'not_loaded'::public.t3a_operational_state);
  insert into public.t3a_d1_content_version(content_object_id, version_no, approval_status, operational_state, body) select content_object_id, 'v2.1', 'drafting', 'not_loaded'::public.t3a_operational_state, '{"stage": 1, "title": "THREE MONTHS, AND THE COMMITTEE CHOSE ANOTHER", "source_digest": "9b2643848048dfdd1018a35ee5b3096f9acaae71e306724641fbd8fab00512d9", "situation": "You are a junior architect. You spent three months developing a design proposal for a community library — your first solo lead on a public project. Yesterday the selection committee announced its decision. Your firm was not selected.\n\nWhat the record shows: the committee''s written feedback cites the operating cost of the natural ventilation system and the absence of a phased construction option; the design work itself is not criticized in the letter; your firm has two further public proposals due in the next eight weeks, one of which you are staffed on; the drawings and the ventilation modeling are complete and are the firm''s property; and your principal has asked for a short note on what the firm should carry forward, by Friday.", "reveals": [{"code": "R1", "text": "What is the first thing you do?", "role": "Opening"}, {"code": "R2", "text": "What do you establish about the decision before you do anything further?", "role": "Information"}, {"code": "R3", "text": "What do you do about the two things the letter names?", "role": "Information"}, {"code": "R4", "text": "Whose help or what resource do you go to, if any?", "role": "Information"}, {"code": "R5", "text": "What work of yours continues, and from when?", "role": "Information"}, {"code": "R6", "text": "What do you do about the same two points arising on the next proposal, and what gets written down and where?", "role": "Information"}, {"code": "R7", "text": "Your principal writes: \"You said the committee criticized the design. Did they?\" What do you say?", "role": "Account test"}], "question_applicability": [{"question": "Q-D8-01", "state": "DIRECT", "basis": "The situation lists two containment actions"}, {"question": "Q-D8-01b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D8-02", "state": "DIRECT", "basis": "The situation designates four facts about the setback"}, {"question": "Q-D8-02b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D8-03", "state": "DIRECT", "basis": "The situation lists two actions on the condition behind the setback"}, {"question": "Q-D8-03b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D8-04", "state": "DIRECT", "basis": "The situation lists three supports"}, {"question": "Q-D8-04b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D8-05", "state": "DIRECT", "basis": "The situation lists two commitments in force"}, {"question": "Q-D8-05b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D8-06", "state": "DIRECT", "basis": "The situation lists two items of work under way"}, {"question": "Q-D8-06b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D8-07", "state": "DIRECT", "basis": "The situation lists three measures against the condition arising again"}, {"question": "Q-D8-07b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D8-08", "state": "DIRECT", "basis": "The situation names a place a record could be made"}, {"question": "Q-D8-09", "state": "DIRECT", "basis": "The account test puts an earlier statement back"}], "material_map": [{"Item": "CM1", "Item text": "the note to the principal by Friday", "Where the participant meets it": "The situation", "Quoted text": "asked for a short note on what the firm should carry forward, by Friday"}, {"Item": "CM2", "Item text": "the proposal the participant is staffed on, due within eight weeks", "Where the participant meets it": "The situation", "Quoted text": "proposals due in the next eight weeks, one of which you are staffed"}], "source_sheet": {"d8_situation_class": "SC-D8-2", "workplace_demand": "Carrying work forward after a three-month public design proposal was not selected by the committee.", "relevant_conduct": "Which containment action was stated; which facts about the setback were named; what action on the condition behind the setback was stated; which support was stated as one to go to; which commitments in force were named as still to be met; what work was named as continuing, and from when; what was stated about the condition arising again; whether a record was stated, and where; what was stated when an earlier statement was put back.", "irrelevant_conduct": "The committee''s reasoning or fairness; whether the design was good; the firm''s win rate.", "stated_standard": null, "stated_standard_source_quote_or_location": null, "cross_context_map": null, "serving_eligible": false, "recurrence_eligible": true, "replacement_required": false, "name_clearance_status": "CLEARED", "name_clearance_basis": "Controlled role and entity labels only; no real person or organization is named.", "sensitivity_flag": null, "permitted_administration_variance": "Pronunciation only; accommodations affecting turn order or response window are recorded and set timing_not_comparable.", "unsupported_inferences": "That three months were wasted; that the participant should feel any way about the outcome; any observation of disappointment or its absence.", "compatibility_class": "S1-WRITTEN-SEQUENTIAL", "setback_established": "In the situation: \"Your firm was not selected.\"", "containment_actions": [{"id": "CA1", "text": "read the written feedback against the submitted proposal point by point"}, {"id": "CA2", "text": "file the drawings and modeling where the next proposal team can reach them"}], "corrective_actions": [{"id": "CR1", "text": "cost the ventilation system against a conventional alternative"}, {"id": "CR2", "text": "prepare a phased construction option as a standing element of the firm''s proposals"}], "designated_facts": [{"id": "DF1", "text": "what the written feedback names, in its own terms"}, {"id": "DF2", "text": "what the feedback does not raise"}, {"id": "DF3", "text": "which of the two further proposals carries the same features"}, {"id": "DF4", "text": "what the firm retains of the work"}], "available_supports": [{"id": "SU1", "text": "the principal, who has asked for a note by Friday"}, {"id": "SU2", "text": "the firm''s cost consultant"}, {"id": "SU3", "text": "the two colleagues staffed on the upcoming proposals"}], "standing_commitments": [{"id": "CM1", "text": "the note to the principal by Friday"}, {"id": "CM2", "text": "the proposal the participant is staffed on, due within eight weeks"}], "work_in_progress": [{"id": "WP1", "text": "the upcoming public proposal the participant is staffed on"}, {"id": "WP2", "text": "the ventilation modeling, complete and retained"}], "recurrence_measures": [{"id": "RM1", "text": "a standing phased-construction option in every public proposal"}, {"id": "RM2", "text": "operating-cost figures carried in the proposal rather than on request"}, {"id": "RM3", "text": "a pre-submission read against the last three feedback letters"}], "recurring_condition": null, "formal_record_state": "The committee''s written feedback letter, held by the firm.", "record_place": "The firm''s proposal review file.", "who_knows": "The principal and the two proposal teams.", "decision_origin": "The selection committee, external to the firm.", "account_test_point": "R7", "account_test_record": "The situation records that the design work itself is not criticized in the committee''s letter.", "list_note": null, "source_note": null, "situation_class_label": "Sustained work ended or withdrawn by a decision outside the participant''s control", "observation_mode_label": "written_response", "min_seconds": 360, "max_seconds": 1500}, "source_identifier": "SRC-D8-S1-002", "stage_code": "S1", "source_version_hash": "9b2643848048dfdd1018a35ee5b3096f9acaae71e306724641fbd8fab00512d9", "serving_eligible": false, "verbatim": "You are a junior architect. You spent three months developing a design proposal for a community library — your first solo lead on a public project. Yesterday the selection committee announced its decision. Your firm was not selected.\n\nWhat the record shows: the committee''s written feedback cites the operating cost of the natural ventilation system and the absence of a phased construction option; the design work itself is not criticized in the letter; your firm has two further public proposals due in the next eight weeks, one of which you are staffed on; the drawings and the ventilation modeling are complete and are the firm''s property; and your principal has asked for a short note on what the firm should carry forward, by Friday."}'::jsonb from public.t3a_content_object where identifier = 'SRC-D8-S1-002' and family = 'source'::public.t3a_content_family;
  insert into public.t3a_content_object(identifier, family, title, dimension_id, current_operational_state) values ('SRC-D8-S1-003', 'source'::public.t3a_content_family, 'SIX DESIGNERS DOWN TO THREE', 'D8', 'not_loaded'::public.t3a_operational_state);
  insert into public.t3a_d1_content_version(content_object_id, version_no, approval_status, operational_state, body) select content_object_id, 'v2.1', 'drafting', 'not_loaded'::public.t3a_operational_state, '{"stage": 1, "title": "SIX DESIGNERS DOWN TO THREE", "source_digest": "2a578c052ab9b9c3255e9e624f018217ac2278c0f4d25cff83b6f8c9424ace57", "situation": "You are a product designer at a technology company. On Friday the company reduced staff by thirty percent. You were not among those affected. Your design team has gone from six people to three, and you now report to the vice-president of product directly rather than to a team lead.\n\nWhat the record shows: the three design workstreams your team held are unchanged and all three have live commitments; the design system your former team lead maintained has no named owner; the next release is in five weeks and its design review is scheduled for Thursday; the vice-president has thirty minutes on Monday and has asked what the team can hold; and no work has been formally descoped.", "reveals": [{"code": "R1", "text": "What is the first thing you do, and about what?", "role": "Opening"}, {"code": "R2", "text": "What do you establish about the three workstreams before Monday?", "role": "Information"}, {"code": "R3", "text": "What do you do about the design system having no owner?", "role": "Information"}, {"code": "R4", "text": "Whose help or what resource do you go to, if any?", "role": "Information"}, {"code": "R5", "text": "What does the team hold, and what work of yours resumes and from when?", "role": "Information"}, {"code": "R6", "text": "What do you do about the same gap arising at the next release, and what gets written down and where?", "role": "Information"}, {"code": "R7", "text": "On Tuesday the vice-president writes: \"You told me Monday that some of the work had been formally descoped. Had it?\" What do you say?", "role": "Account test"}], "question_applicability": [{"question": "Q-D8-01", "state": "DIRECT", "basis": "The situation lists three containment actions"}, {"question": "Q-D8-01b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D8-02", "state": "DIRECT", "basis": "The situation designates four facts about the setback"}, {"question": "Q-D8-02b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D8-03", "state": "DIRECT", "basis": "The situation lists three actions on the condition behind the setback"}, {"question": "Q-D8-03b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D8-04", "state": "DIRECT", "basis": "The situation lists three supports"}, {"question": "Q-D8-04b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D8-05", "state": "DIRECT", "basis": "The situation lists three commitments in force"}, {"question": "Q-D8-05b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D8-06", "state": "DIRECT", "basis": "The situation lists two items of work under way"}, {"question": "Q-D8-06b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D8-07", "state": "DIRECT", "basis": "The situation lists three measures against the condition arising again"}, {"question": "Q-D8-07b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D8-08", "state": "DIRECT", "basis": "The situation names a place a record could be made"}, {"question": "Q-D8-09", "state": "DIRECT", "basis": "The account test puts an earlier statement back"}], "material_map": [{"Item": "CM1", "Item text": "Thursday''s design review", "Where the participant meets it": "The situation", "Quoted text": "its design review is scheduled for Thursday"}, {"Item": "CM2", "Item text": "the release in five weeks", "Where the participant meets it": "The situation", "Quoted text": "release is in five weeks"}, {"Item": "CM3", "Item text": "the three workstreams'' live commitments", "Where the participant meets it": "The situation", "Quoted text": "all three have live commitments"}], "source_sheet": {"d8_situation_class": "SC-D8-6", "workplace_demand": "Holding three design workstreams with live commitments after the team was reduced from six people to three.", "relevant_conduct": "Which containment action was stated; which facts about the setback were named; what action on the condition behind the setback was stated; which support was stated as one to go to; which commitments in force were named as still to be met; what work was named as continuing, and from when; what was stated about the condition arising again; whether a record was stated, and where; what was stated when an earlier statement was put back.", "irrelevant_conduct": "The reduction decision; the departed team lead; morale.", "stated_standard": null, "stated_standard_source_quote_or_location": null, "cross_context_map": null, "serving_eligible": false, "recurrence_eligible": true, "replacement_required": false, "name_clearance_status": "CLEARED", "name_clearance_basis": "Controlled role and entity labels only; no real person or organization is named.", "sensitivity_flag": null, "permitted_administration_variance": "Pronunciation only; accommodations affecting turn order or response window are recorded and set timing_not_comparable.", "unsupported_inferences": "Anything about the departed colleagues or the participant''s relationship to them; that surviving a reduction indicates anything; any observation of how the participant is affected by the loss of colleagues.", "compatibility_class": "S1-WRITTEN-SEQUENTIAL", "setback_established": "In the situation: \"your design team has gone from six people to three.\"", "containment_actions": [{"id": "CA1", "text": "list the three workstreams against the three remaining people"}, {"id": "CA2", "text": "name an interim owner for the design system"}, {"id": "CA3", "text": "propose which workstream is descoped before Thursday''s review"}], "corrective_actions": [{"id": "CR1", "text": "name an interim owner for the design system"}, {"id": "CR2", "text": "propose which workstream is descoped before Thursday''s review"}, {"id": "CR3", "text": "freeze the design system so it needs no owner until after the release"}], "designated_facts": [{"id": "DF1", "text": "what each of the three workstreams has committed and by when"}, {"id": "DF2", "text": "what the design system requires of an owner between now and the release"}, {"id": "DF3", "text": "what Thursday''s design review needs to receive"}, {"id": "DF4", "text": "what the three remaining people are already carrying"}], "available_supports": [{"id": "SU1", "text": "the vice-president''s thirty minutes on Monday"}, {"id": "SU2", "text": "the two remaining designers"}, {"id": "SU3", "text": "the engineering leads who consume the design system"}], "standing_commitments": [{"id": "CM1", "text": "Thursday''s design review"}, {"id": "CM2", "text": "the release in five weeks"}, {"id": "CM3", "text": "the three workstreams'' live commitments"}], "work_in_progress": [{"id": "WP1", "text": "the three design workstreams"}, {"id": "WP2", "text": "the design system"}], "recurrence_measures": [{"id": "RM1", "text": "a named second owner for the design system"}, {"id": "RM2", "text": "workstream commitments recorded against named people rather than the team"}, {"id": "RM3", "text": "a descoping route agreed before the next release begins"}], "recurring_condition": null, "formal_record_state": null, "record_place": "The team''s workstream register.", "who_knows": "The vice-president and the two remaining designers.", "decision_origin": "The company''s staff reduction, above the participant.", "account_test_point": "R7", "account_test_record": "The situation records that no work has been formally descoped.", "list_note": null, "source_note": null, "situation_class_label": "Work that must continue with its people, tools or resources reduced", "observation_mode_label": "written_response", "min_seconds": 360, "max_seconds": 1500}, "source_identifier": "SRC-D8-S1-003", "stage_code": "S1", "source_version_hash": "2a578c052ab9b9c3255e9e624f018217ac2278c0f4d25cff83b6f8c9424ace57", "serving_eligible": false, "verbatim": "You are a product designer at a technology company. On Friday the company reduced staff by thirty percent. You were not among those affected. Your design team has gone from six people to three, and you now report to the vice-president of product directly rather than to a team lead.\n\nWhat the record shows: the three design workstreams your team held are unchanged and all three have live commitments; the design system your former team lead maintained has no named owner; the next release is in five weeks and its design review is scheduled for Thursday; the vice-president has thirty minutes on Monday and has asked what the team can hold; and no work has been formally descoped."}'::jsonb from public.t3a_content_object where identifier = 'SRC-D8-S1-003' and family = 'source'::public.t3a_content_family;
  insert into public.t3a_content_object(identifier, family, title, dimension_id, current_operational_state) values ('SRC-D8-S1-004', 'source'::public.t3a_content_family, 'THREE CRITICAL VIOLATIONS ON THE REPORT', 'D8', 'not_loaded'::public.t3a_operational_state);
  insert into public.t3a_d1_content_version(content_object_id, version_no, approval_status, operational_state, body) select content_object_id, 'v2.1', 'drafting', 'not_loaded'::public.t3a_operational_state, '{"stage": 1, "title": "THREE CRITICAL VIOLATIONS ON THE REPORT", "source_digest": "c8f4f824bb83ccbcb256113d14faaaf300786c38a0aedc2becee1d295d7dee27", "situation": "You are a quality assurance supervisor at a food processing plant producing packaged salads. The plant processes about 15,000 units a day. Yesterday a provincial health inspector conducted a surprise audit. This morning the inspection report arrived citing three critical violations: inadequate temperature logging in cold storage unit 2, an expired sanitizer solution on the wash line, and incomplete allergen cross-contact records.\n\nWhat the record shows: the report requires a written corrective action plan within ten business days; the temperature logging in unit 2 has been manual since a sensor failed eleven weeks ago and a replacement was requisitioned twice; the sanitizer solution''s expiry was three days past; the allergen records are complete for four of the six lines; today''s production run is scheduled to start at 2:00 PM; and the plant manager has asked to see you at 11:00 AM.", "reveals": [{"code": "R1", "text": "What is the first thing you do, and about what?", "role": "Opening"}, {"code": "R2", "text": "What do you establish about the three violations before 11:00 AM?", "role": "Information"}, {"code": "R3", "text": "What do you do about the conditions behind them?", "role": "Information"}, {"code": "R4", "text": "Whose help or what resource do you go to, if any?", "role": "Information"}, {"code": "R5", "text": "What still gets met, and what production resumes and from when?", "role": "Information"}, {"code": "R6", "text": "What do you do about these arising at the next audit, and what gets written down and where?", "role": "Information"}, {"code": "R7", "text": "The plant manager writes: \"You told me the sensor replacement had been ordered once. Was it?\" What do you say?", "role": "Account test"}], "question_applicability": [{"question": "Q-D8-01", "state": "DIRECT", "basis": "The situation lists three containment actions"}, {"question": "Q-D8-01b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D8-02", "state": "DIRECT", "basis": "The situation designates four facts about the setback"}, {"question": "Q-D8-02b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D8-03", "state": "DIRECT", "basis": "The situation lists three actions on the condition behind the setback"}, {"question": "Q-D8-03b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D8-04", "state": "DIRECT", "basis": "The situation lists three supports"}, {"question": "Q-D8-04b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D8-05", "state": "DIRECT", "basis": "The situation lists three commitments in force"}, {"question": "Q-D8-05b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D8-06", "state": "DIRECT", "basis": "The situation lists two items of work under way"}, {"question": "Q-D8-06b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D8-07", "state": "DIRECT", "basis": "The situation lists three measures against the condition arising again"}, {"question": "Q-D8-07b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D8-08", "state": "DIRECT", "basis": "The situation names a place a record could be made"}, {"question": "Q-D8-09", "state": "DIRECT", "basis": "The account test puts an earlier statement back"}], "material_map": [{"Item": "CM1", "Item text": "the corrective action plan within ten business days", "Where the participant meets it": "The situation", "Quoted text": "requires a written corrective action plan within ten business days"}, {"Item": "CM2", "Item text": "the 2:00 PM production run", "Where the participant meets it": "The situation", "Quoted text": "production run is scheduled to start at 2:00 PM"}, {"Item": "CM3", "Item text": "the daily 15,000-unit output", "Where the participant meets it": "The situation", "Quoted text": "processes about 15,000 units a day"}], "source_sheet": {"d8_situation_class": "SC-D8-3", "workplace_demand": "Keeping production running after an inspection report cited three critical violations against the work the participant holds.", "relevant_conduct": "Which containment action was stated; which facts about the setback were named; what action on the condition behind the setback was stated; which support was stated as one to go to; which commitments in force were named as still to be met; what work was named as continuing, and from when; what was stated about the condition arising again; whether a record was stated, and where; what was stated when an earlier statement was put back.", "irrelevant_conduct": "The inspector''s conduct; whether the violations are fair; who is answerable.", "stated_standard": null, "stated_standard_source_quote_or_location": null, "cross_context_map": null, "serving_eligible": false, "recurrence_eligible": true, "replacement_required": false, "name_clearance_status": "CLEARED", "name_clearance_basis": "Controlled role and entity labels only; no real person or organization is named.", "sensitivity_flag": null, "permitted_administration_variance": "Pronunciation only; accommodations affecting turn order or response window are recorded and set timing_not_comparable.", "unsupported_inferences": "That the participant allowed the conditions to persist, which is a D2 matter; that the violations reflect on the participant; any observation of how the report was taken.", "compatibility_class": "S1-WRITTEN-SEQUENTIAL", "setback_established": "In the situation: \"three critical violations cited.\"", "containment_actions": [{"id": "CA1", "text": "verify the sanitizer solution across every line and replace where expired"}, {"id": "CA2", "text": "hold the 2:00 PM run until the three items are addressed"}, {"id": "CA3", "text": "escalate the unit 2 sensor requisition to the plant manager at 11:00 AM"}], "corrective_actions": [{"id": "CR1", "text": "verify the sanitizer solution across every line and replace where expired"}, {"id": "CR2", "text": "escalate the unit 2 sensor requisition to the plant manager at 11:00 AM"}, {"id": "CR3", "text": "complete the allergen records for the two outstanding lines"}], "designated_facts": [{"id": "DF1", "text": "what each of the three violations states in the report''s own terms"}, {"id": "DF2", "text": "how long the unit 2 sensor has been out and what was requisitioned when"}, {"id": "DF3", "text": "which lines the allergen records cover and which they do not"}, {"id": "DF4", "text": "what the ten-business-day corrective action plan must contain"}], "available_supports": [{"id": "SU1", "text": "the plant manager at 11:00 AM"}, {"id": "SU2", "text": "the maintenance lead who holds the requisition"}, {"id": "SU3", "text": "the line supervisors on the two lines with incomplete records"}], "standing_commitments": [{"id": "CM1", "text": "the corrective action plan within ten business days"}, {"id": "CM2", "text": "the 2:00 PM production run"}, {"id": "CM3", "text": "the daily 15,000-unit output"}], "work_in_progress": [{"id": "WP1", "text": "today''s production run"}, {"id": "WP2", "text": "the allergen record set across the six lines"}], "recurrence_measures": [{"id": "RM1", "text": "an automatic hold on any line whose sanitizer is within seven days of expiry"}, {"id": "RM2", "text": "an escalation trigger on any requisition open beyond four weeks"}, {"id": "RM3", "text": "a weekly allergen record check across all six lines"}], "recurring_condition": "The unit 2 temperature logging has been manual for eleven weeks with two requisitions unfilled.", "formal_record_state": "The provincial inspection report, already issued.", "record_place": "The plant''s corrective action register.", "who_knows": "The inspector, the plant manager and the maintenance lead.", "decision_origin": null, "account_test_point": "R7", "account_test_record": "The situation records that the sensor replacement was requisitioned twice.", "list_note": null, "source_note": null, "situation_class_label": "A failure or violation formally recorded against work the participant holds", "observation_mode_label": "written_response", "min_seconds": 360, "max_seconds": 1500}, "source_identifier": "SRC-D8-S1-004", "stage_code": "S1", "source_version_hash": "c8f4f824bb83ccbcb256113d14faaaf300786c38a0aedc2becee1d295d7dee27", "serving_eligible": false, "verbatim": "You are a quality assurance supervisor at a food processing plant producing packaged salads. The plant processes about 15,000 units a day. Yesterday a provincial health inspector conducted a surprise audit. This morning the inspection report arrived citing three critical violations: inadequate temperature logging in cold storage unit 2, an expired sanitizer solution on the wash line, and incomplete allergen cross-contact records.\n\nWhat the record shows: the report requires a written corrective action plan within ten business days; the temperature logging in unit 2 has been manual since a sensor failed eleven weeks ago and a replacement was requisitioned twice; the sanitizer solution''s expiry was three days past; the allergen records are complete for four of the six lines; today''s production run is scheduled to start at 2:00 PM; and the plant manager has asked to see you at 11:00 AM."}'::jsonb from public.t3a_content_object where identifier = 'SRC-D8-S1-004' and family = 'source'::public.t3a_content_family;
  insert into public.t3a_content_object(identifier, family, title, dimension_id, current_operational_state) values ('SRC-D8-S1-005', 'source'::public.t3a_content_family, 'THE CALL THAT COULD NOT BE ANSWERED FROM THE RECORD', 'D8', 'not_loaded'::public.t3a_operational_state);
  insert into public.t3a_d1_content_version(content_object_id, version_no, approval_status, operational_state, body) select content_object_id, 'v2.1', 'drafting', 'not_loaded'::public.t3a_operational_state, '{"stage": 1, "title": "THE CALL THAT COULD NOT BE ANSWERED FROM THE RECORD", "source_digest": "596638f062bedb89650fff43d67731461341c2a4db230b710e6f0ca988c4bd04", "situation": "You are a customer service representative at an insurance company. A caller''s policy record shows a premium adjustment they say they did not authorize. You cannot resolve it from the record in front of you: the adjustment shows a system timestamp but no originating user and no linked authorization.\n\nWhat the record shows: this is the fourth call today with the same missing-authorization pattern; the fault has been reported to the systems team twice in the past three weeks and both tickets are open; your call handling target is an average of six minutes and you are currently at nine; you can raise a manual authorization trace which takes about twenty minutes per case and requires a supervisor code; and your shift ends in two hours with eleven calls in the queue.", "reveals": [{"code": "R1", "text": "What is the first thing you do, and about what?", "role": "Opening"}, {"code": "R2", "text": "What do you establish about this call and the pattern before you go further?", "role": "Information"}, {"code": "R3", "text": "What do you do about the fault itself?", "role": "Information"}, {"code": "R4", "text": "Whose help or what resource do you go to, if any?", "role": "Information"}, {"code": "R5", "text": "What still gets met on this shift, and what work resumes and from when?", "role": "Information"}, {"code": "R6", "text": "What do you do about a fifth call arriving with the same pattern, and what gets written down and where?", "role": "Information"}, {"code": "R7", "text": "Your team leader writes: \"You said this was the first call today with that pattern. Was it?\" What do you say?", "role": "Account test"}], "question_applicability": [{"question": "Q-D8-01", "state": "DIRECT", "basis": "The situation lists four containment actions"}, {"question": "Q-D8-01b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D8-02", "state": "DIRECT", "basis": "The situation designates four facts about the setback"}, {"question": "Q-D8-02b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D8-03", "state": "DIRECT", "basis": "The situation lists two actions on the condition behind the setback"}, {"question": "Q-D8-03b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D8-04", "state": "DIRECT", "basis": "The situation lists three supports"}, {"question": "Q-D8-04b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D8-05", "state": "DIRECT", "basis": "The situation lists three commitments in force"}, {"question": "Q-D8-05b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D8-06", "state": "DIRECT", "basis": "The situation lists three items of work under way"}, {"question": "Q-D8-06b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D8-07", "state": "DIRECT", "basis": "The situation lists three measures against the condition arising again"}, {"question": "Q-D8-07b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D8-08", "state": "DIRECT", "basis": "The situation names a place a record could be made"}, {"question": "Q-D8-09", "state": "DIRECT", "basis": "The account test puts an earlier statement back"}], "material_map": [{"Item": "CM1", "Item text": "the six-minute average call handling target", "Where the participant meets it": "The situation", "Quoted text": "your call handling target is an average of six minutes"}, {"Item": "CM2", "Item text": "the eleven calls in the queue before shift end", "Where the participant meets it": "The situation", "Quoted text": "your shift ends in two hours with eleven calls in the queue"}, {"Item": "CM3", "Item text": "the caller''s unresolved adjustment", "Where the participant meets it": "The situation", "Quoted text": "policy record shows a premium adjustment"}], "source_sheet": {"d8_situation_class": "SC-D8-4", "workplace_demand": "Handling a call that cannot be resolved from the record, on a system fault that has recurred and been reported twice.", "relevant_conduct": "Which containment action was stated; which facts about the setback were named; what action on the condition behind the setback was stated; which support was stated as one to go to; which commitments in force were named as still to be met; what work was named as continuing, and from when; what was stated about the condition arising again; whether a record was stated, and where; what was stated when an earlier statement was put back.", "irrelevant_conduct": "The caller; the systems team''s responsiveness; whether the target is reasonable.", "stated_standard": null, "stated_standard_source_quote_or_location": null, "cross_context_map": null, "serving_eligible": false, "recurrence_eligible": true, "replacement_required": false, "name_clearance_status": "CLEARED", "name_clearance_basis": "Controlled role and entity labels only; no real person or organization is named.", "sensitivity_flag": null, "permitted_administration_variance": "Pronunciation only; accommodations affecting turn order or response window are recorded and set timing_not_comparable.", "unsupported_inferences": "That being over the handling target indicates anything; any observation of fatigue, patience or its absence; anything about the caller''s manner or the participant''s response to it — the re-framing removed the hostility and no question may recover it.", "compatibility_class": "S1-WRITTEN-SEQUENTIAL", "setback_established": "In the situation: \"You cannot resolve it from the record in front of you.\"", "containment_actions": [{"id": "CA1", "text": "raise a manual authorization trace for this case"}, {"id": "CA2", "text": "attach the four cases to the open systems tickets"}, {"id": "CA3", "text": "escalate the two open tickets through the supervisor"}, {"id": "CA4", "text": "log the pattern against the shift record so the next shift sees it"}], "corrective_actions": [{"id": "CR1", "text": "attach the four cases to the open systems tickets"}, {"id": "CR2", "text": "escalate the two open tickets through the supervisor"}], "designated_facts": [{"id": "DF1", "text": "what the policy record shows and does not show about the adjustment"}, {"id": "DF2", "text": "how many calls today carry the same pattern"}, {"id": "DF3", "text": "what the two open tickets say and when they were raised"}, {"id": "DF4", "text": "what a manual authorization trace requires and how long it takes"}], "available_supports": [{"id": "SU1", "text": "the supervisor, who holds the code for a manual trace"}, {"id": "SU2", "text": "the systems team, who hold the two open tickets"}, {"id": "SU3", "text": "the shift record, where a pattern can be logged for the next shift"}], "standing_commitments": [{"id": "CM1", "text": "the six-minute average call handling target"}, {"id": "CM2", "text": "the eleven calls in the queue before shift end"}, {"id": "CM3", "text": "the caller''s unresolved adjustment"}], "work_in_progress": [{"id": "WP1", "text": "the current call"}, {"id": "WP2", "text": "the eleven queued calls"}, {"id": "WP3", "text": "the four cases carrying the same pattern"}], "recurrence_measures": [{"id": "RM1", "text": "a standing manual-trace authorization for this fault pattern"}, {"id": "RM2", "text": "the four cases attached to the open tickets as evidence of frequency"}, {"id": "RM3", "text": "a shift-record entry so the next shift recognises the pattern"}], "recurring_condition": "The same missing-authorization pattern, fourth today, two tickets open three weeks.", "formal_record_state": "Two open systems tickets.", "record_place": "The shift record and the open tickets.", "who_knows": "The systems team and the supervisor.", "decision_origin": null, "account_test_point": "R7", "account_test_record": "The situation records that this is the fourth call today with the same pattern.", "list_note": null, "source_note": "Re-framed from the library scenario: The library scenario has a hostile caller and turns on the participant absorbing the hostility. The hostility is removed entirely and no question observes the caller''s manner or the participant''s absorption of it. What remains is an account that cannot be resolved from the record available, for the fourth time today, on a fault already reported twice.", "situation_class_label": "A condition that has disrupted the work before, producing the same disruption again", "observation_mode_label": "written_response", "min_seconds": 360, "max_seconds": 1500}, "source_identifier": "SRC-D8-S1-005", "stage_code": "S1", "source_version_hash": "596638f062bedb89650fff43d67731461341c2a4db230b710e6f0ca988c4bd04", "serving_eligible": false, "verbatim": "You are a customer service representative at an insurance company. A caller''s policy record shows a premium adjustment they say they did not authorize. You cannot resolve it from the record in front of you: the adjustment shows a system timestamp but no originating user and no linked authorization.\n\nWhat the record shows: this is the fourth call today with the same missing-authorization pattern; the fault has been reported to the systems team twice in the past three weeks and both tickets are open; your call handling target is an average of six minutes and you are currently at nine; you can raise a manual authorization trace which takes about twenty minutes per case and requires a supervisor code; and your shift ends in two hours with eleven calls in the queue."}'::jsonb from public.t3a_content_object where identifier = 'SRC-D8-S1-005' and family = 'source'::public.t3a_content_family;
  insert into public.t3a_content_object(identifier, family, title, dimension_id, current_operational_state) values ('SRC-D8-S1-006', 'source'::public.t3a_content_family, 'THE ROLE THAT WAS RESTRUCTURED', 'D8', 'not_loaded'::public.t3a_operational_state);
  insert into public.t3a_d1_content_version(content_object_id, version_no, approval_status, operational_state, body) select content_object_id, 'v2.1', 'drafting', 'not_loaded'::public.t3a_operational_state, '{"stage": 1, "title": "THE ROLE THAT WAS RESTRUCTURED", "source_digest": "440fcf64db1d8e62debd0bb20a2afae29b8d64c3088bddf0ef023f451bcda763", "situation": "You are a senior financial analyst with six years at the company. You were on the shortlist for a finance manager promotion. Yesterday your vice-president told you the role has been restructured: it is being combined with the financial planning and analysis function and filled externally, from someone with planning experience the company does not hold internally.\n\nWhat the record shows: the restructured role''s posting lists four planning competencies, two of which your record does not evidence; your current responsibilities are unchanged; the quarterly close begins in nine days and you lead it; the company funds one professional qualification per analyst per year and yours is unclaimed; and your vice-president has offered a follow-up conversation this week.", "reveals": [{"code": "R1", "text": "What is the first thing you do?", "role": "Opening"}, {"code": "R2", "text": "What do you establish about the restructured role before the follow-up conversation?", "role": "Information"}, {"code": "R3", "text": "What do you do about the two competencies your record does not evidence?", "role": "Information"}, {"code": "R4", "text": "Whose help or what resource do you go to, if any?", "role": "Information"}, {"code": "R5", "text": "What work of yours continues, and from when?", "role": "Information"}, {"code": "R6", "text": "What do you do about the same gap at the next opportunity, and what gets written down and where?", "role": "Information"}, {"code": "R7", "text": "Your vice-president writes: \"You said the posting named six competencies. Did it?\" What do you say?", "role": "Account test"}], "question_applicability": [{"question": "Q-D8-01", "state": "DIRECT", "basis": "The situation lists three containment actions"}, {"question": "Q-D8-01b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D8-02", "state": "DIRECT", "basis": "The situation designates four facts about the setback"}, {"question": "Q-D8-02b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D8-03", "state": "DIRECT", "basis": "The situation lists two actions on the condition behind the setback"}, {"question": "Q-D8-03b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D8-04", "state": "DIRECT", "basis": "The situation lists three supports"}, {"question": "Q-D8-04b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D8-05", "state": "DIRECT", "basis": "The situation lists two commitments in force"}, {"question": "Q-D8-05b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D8-06", "state": "DIRECT", "basis": "The situation lists two items of work under way"}, {"question": "Q-D8-06b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D8-07", "state": "DIRECT", "basis": "The situation lists three measures against the condition arising again"}, {"question": "Q-D8-07b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D8-08", "state": "DIRECT", "basis": "The situation names a place a record could be made"}, {"question": "Q-D8-09", "state": "DIRECT", "basis": "The account test puts an earlier statement back"}], "material_map": [{"Item": "CM1", "Item text": "the quarterly close beginning in nine days", "Where the participant meets it": "The situation", "Quoted text": "quarterly close begins in nine days"}, {"Item": "CM2", "Item text": "the participant''s unchanged current responsibilities", "Where the participant meets it": "The situation", "Quoted text": "current responsibilities are unchanged"}], "source_sheet": {"d8_situation_class": "SC-D8-5", "workplace_demand": "Continuing current responsibilities after a promotion the participant was shortlisted for was restructured and filled externally.", "relevant_conduct": "Which containment action was stated; which facts about the setback were named; what action on the condition behind the setback was stated; which support was stated as one to go to; which commitments in force were named as still to be met; what work was named as continuing, and from when; what was stated about the condition arising again; whether a record was stated, and where; what was stated when an earlier statement was put back.", "irrelevant_conduct": "The external candidate; the restructuring decision; whether the participant should look elsewhere.", "stated_standard": null, "stated_standard_source_quote_or_location": null, "cross_context_map": null, "serving_eligible": false, "recurrence_eligible": true, "replacement_required": false, "name_clearance_status": "CLEARED", "name_clearance_basis": "Controlled role and entity labels only; no real person or organization is named.", "sensitivity_flag": null, "permitted_administration_variance": "Pronunciation only; accommodations affecting turn order or response window are recorded and set timing_not_comparable.", "unsupported_inferences": "That the participant was passed over unfairly; that six years entitles anything; any observation of disappointment, acceptance or its absence.", "compatibility_class": "S1-WRITTEN-SEQUENTIAL", "setback_established": "In the situation: \"the role has been restructured... and filled externally.\"", "containment_actions": [{"id": "CA1", "text": "read the restructured posting against your own record item by item"}, {"id": "CA2", "text": "ask for planning work to be routed through you during the next two quarters"}, {"id": "CA3", "text": "confirm what the quarterly close needs from you in nine days"}], "corrective_actions": [{"id": "CR1", "text": "claim the funded qualification against one of the two competencies"}, {"id": "CR2", "text": "ask for planning work to be routed through you during the next two quarters"}], "designated_facts": [{"id": "DF1", "text": "what the four planning competencies are, in the posting''s terms"}, {"id": "DF2", "text": "which two the participant''s record does not evidence"}, {"id": "DF3", "text": "what the funded qualification covers and when it must be claimed"}, {"id": "DF4", "text": "what the quarterly close requires and when it begins"}], "available_supports": [{"id": "SU1", "text": "the vice-president''s offered follow-up conversation"}, {"id": "SU2", "text": "the funded professional qualification, unclaimed"}, {"id": "SU3", "text": "the planning function, whose work the new role absorbs"}], "standing_commitments": [{"id": "CM1", "text": "the quarterly close beginning in nine days"}, {"id": "CM2", "text": "the participant''s unchanged current responsibilities"}], "work_in_progress": [{"id": "WP1", "text": "the quarterly close"}, {"id": "WP2", "text": "the participant''s current analyst workload"}], "recurrence_measures": [{"id": "RM1", "text": "the funded qualification claimed against a named competency each year"}, {"id": "RM2", "text": "planning work sought and recorded before the next posting"}, {"id": "RM3", "text": "a standing record of competencies evidenced against the internal framework"}], "recurring_condition": null, "formal_record_state": "The restructured role posting.", "record_place": "The participant''s development record.", "who_knows": "The vice-president.", "decision_origin": "The company''s restructuring decision, above the participant.", "account_test_point": "R7", "account_test_record": "The situation records that the posting lists four planning competencies.", "list_note": null, "source_note": null, "situation_class_label": "An expected advancement or selection that has not come", "observation_mode_label": "written_response", "min_seconds": 360, "max_seconds": 1500}, "source_identifier": "SRC-D8-S1-006", "stage_code": "S1", "source_version_hash": "440fcf64db1d8e62debd0bb20a2afae29b8d64c3088bddf0ef023f451bcda763", "serving_eligible": false, "verbatim": "You are a senior financial analyst with six years at the company. You were on the shortlist for a finance manager promotion. Yesterday your vice-president told you the role has been restructured: it is being combined with the financial planning and analysis function and filled externally, from someone with planning experience the company does not hold internally.\n\nWhat the record shows: the restructured role''s posting lists four planning competencies, two of which your record does not evidence; your current responsibilities are unchanged; the quarterly close begins in nine days and you lead it; the company funds one professional qualification per analyst per year and yours is unclaimed; and your vice-president has offered a follow-up conversation this week."}'::jsonb from public.t3a_content_object where identifier = 'SRC-D8-S1-006' and family = 'source'::public.t3a_content_family;
  insert into public.t3a_content_object(identifier, family, title, dimension_id, current_operational_state) values ('SRC-D8-S1-007', 'source'::public.t3a_content_family, 'THE SYSTEM THAT WENT DOWN AGAIN', 'D8', 'not_loaded'::public.t3a_operational_state);
  insert into public.t3a_d1_content_version(content_object_id, version_no, approval_status, operational_state, body) select content_object_id, 'v2.1', 'drafting', 'not_loaded'::public.t3a_operational_state, '{"stage": 1, "title": "THE SYSTEM THAT WENT DOWN AGAIN", "source_digest": "387632973007604a20122e235d931188e6ce8d52ee61ec175da69a655359c732", "situation": "You are a tier-2 information technology support specialist at a company of 400 employees. The legacy client records system crashes about once every two weeks. Each crash takes two to four hours to restore from backup, during which a sales team of thirty cannot reach client records, pending deals or contact histories. It has crashed again this morning.\n\nWhat the record shows: you have submitted three formal migration requests over the past year and all three are open; the restore procedure is documented and you hold the access to run it; the sales team''s month-end is in six days; your queue holds nine escalated tickets; and the technology director has a standing budget review on Thursday.", "reveals": [{"code": "R1", "text": "What is the first thing you do, and about what?", "role": "Opening"}, {"code": "R2", "text": "What do you establish about this crash and the pattern before you go further?", "role": "Information"}, {"code": "R3", "text": "What do you do about the condition producing the crashes?", "role": "Information"}, {"code": "R4", "text": "Whose help or what resource do you go to, if any?", "role": "Information"}, {"code": "R5", "text": "What still gets met, and what work of yours resumes and from when?", "role": "Information"}, {"code": "R6", "text": "What do you do about the next crash, and what gets written down and where?", "role": "Information"}, {"code": "R7", "text": "The technology director writes: \"You said you''d raised the migration request twice. Is that right?\" What do you say?", "role": "Account test"}], "question_applicability": [{"question": "Q-D8-01", "state": "DIRECT", "basis": "The situation lists three containment actions"}, {"question": "Q-D8-01b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D8-02", "state": "DIRECT", "basis": "The situation designates four facts about the setback"}, {"question": "Q-D8-02b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D8-03", "state": "DIRECT", "basis": "The situation lists two actions on the condition behind the setback"}, {"question": "Q-D8-03b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D8-04", "state": "DIRECT", "basis": "The situation lists three supports"}, {"question": "Q-D8-04b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D8-05", "state": "DIRECT", "basis": "The situation lists three commitments in force"}, {"question": "Q-D8-05b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D8-06", "state": "DIRECT", "basis": "The situation lists two items of work under way"}, {"question": "Q-D8-06b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D8-07", "state": "DIRECT", "basis": "The situation lists three measures against the condition arising again"}, {"question": "Q-D8-07b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D8-08", "state": "DIRECT", "basis": "The situation names a place a record could be made"}, {"question": "Q-D8-09", "state": "DIRECT", "basis": "The account test puts an earlier statement back"}], "material_map": [{"Item": "CM1", "Item text": "the nine escalated tickets in the queue", "Where the participant meets it": "The situation", "Quoted text": "queue holds nine escalated tickets"}, {"Item": "CM2", "Item text": "the sales team''s month-end in six days", "Where the participant meets it": "The situation", "Quoted text": "sales team''s month-end is in six days"}, {"Item": "CM3", "Item text": "the restore itself, within the documented two-to-four hours", "Where the participant meets it": "The situation", "Quoted text": "takes two to four hours to restore from backup"}], "source_sheet": {"d8_situation_class": "SC-D8-4", "workplace_demand": "Restoring service after a legacy system failed again, with three migration requests open.", "relevant_conduct": "Which containment action was stated; which facts about the setback were named; what action on the condition behind the setback was stated; which support was stated as one to go to; which commitments in force were named as still to be met; what work was named as continuing, and from when; what was stated about the condition arising again; whether a record was stated, and where; what was stated when an earlier statement was put back.", "irrelevant_conduct": "The director''s inaction; the vendor; whether migration is justified.", "stated_standard": null, "stated_standard_source_quote_or_location": null, "cross_context_map": null, "serving_eligible": false, "recurrence_eligible": true, "replacement_required": false, "name_clearance_status": "CLEARED", "name_clearance_basis": "Controlled role and entity labels only; no real person or organization is named.", "sensitivity_flag": null, "permitted_administration_variance": "Pronunciation only; accommodations affecting turn order or response window are recorded and set timing_not_comparable.", "unsupported_inferences": "That the participant should have escalated harder; that repeated crashes reflect on them; any observation of frustration, resignation or its absence.", "compatibility_class": "S1-WRITTEN-SEQUENTIAL", "setback_established": "In the situation: \"It has crashed again this morning.\"", "containment_actions": [{"id": "CA1", "text": "run the documented restore procedure"}, {"id": "CA2", "text": "compile the crash frequency and restore hours across the year"}, {"id": "CA3", "text": "tell the sales team what is unavailable and for how long"}], "corrective_actions": [{"id": "CR1", "text": "compile the crash frequency and restore hours across the year"}, {"id": "CR2", "text": "put the compiled figures to the technology director before Thursday''s budget review"}], "designated_facts": [{"id": "DF1", "text": "what this crash has taken down and what remains reachable"}, {"id": "DF2", "text": "how often the system has crashed and how many hours have been lost"}, {"id": "DF3", "text": "what the three open migration requests say and when each was raised"}, {"id": "DF4", "text": "what the sales team needs before month-end in six days"}], "available_supports": [{"id": "SU1", "text": "the technology director and Thursday''s budget review"}, {"id": "SU2", "text": "the documented restore procedure and the access to run it"}, {"id": "SU3", "text": "the sales team lead, who can say what is time-critical"}], "standing_commitments": [{"id": "CM1", "text": "the nine escalated tickets in the queue"}, {"id": "CM2", "text": "the sales team''s month-end in six days"}, {"id": "CM3", "text": "the restore itself, within the documented two-to-four hours"}], "work_in_progress": [{"id": "WP1", "text": "the nine escalated tickets"}, {"id": "WP2", "text": "the restore"}], "recurrence_measures": [{"id": "RM1", "text": "the compiled frequency and hours attached to the migration request"}, {"id": "RM2", "text": "a standing notification to the sales team at first crash detection"}, {"id": "RM3", "text": "a migration decision sought at Thursday''s budget review"}], "recurring_condition": "A crash about every two weeks across a year with three migration requests open.", "formal_record_state": "Three open migration requests.", "record_place": "The incident log and the open migration requests.", "who_knows": "The sales team and the technology director.", "decision_origin": null, "account_test_point": "R7", "account_test_record": "The situation records three formal migration requests submitted over the past year.", "list_note": null, "source_note": null, "situation_class_label": "A condition that has disrupted the work before, producing the same disruption again", "observation_mode_label": "written_response", "min_seconds": 360, "max_seconds": 1500}, "source_identifier": "SRC-D8-S1-007", "stage_code": "S1", "source_version_hash": "387632973007604a20122e235d931188e6ce8d52ee61ec175da69a655359c732", "serving_eligible": false, "verbatim": "You are a tier-2 information technology support specialist at a company of 400 employees. The legacy client records system crashes about once every two weeks. Each crash takes two to four hours to restore from backup, during which a sales team of thirty cannot reach client records, pending deals or contact histories. It has crashed again this morning.\n\nWhat the record shows: you have submitted three formal migration requests over the past year and all three are open; the restore procedure is documented and you hold the access to run it; the sales team''s month-end is in six days; your queue holds nine escalated tickets; and the technology director has a standing budget review on Thursday."}'::jsonb from public.t3a_content_object where identifier = 'SRC-D8-S1-007' and family = 'source'::public.t3a_content_family;
  insert into public.t3a_content_object(identifier, family, title, dimension_id, current_operational_state) values ('SRC-D8-S1-008', 'source'::public.t3a_content_family, 'THE REVIEW THAT CAME IN AT THE MIDDLE TIER', 'D8', 'not_loaded'::public.t3a_operational_state);
  insert into public.t3a_d1_content_version(content_object_id, version_no, approval_status, operational_state, body) select content_object_id, 'v2.1', 'drafting', 'not_loaded'::public.t3a_operational_state, '{"stage": 1, "title": "THE REVIEW THAT CAME IN AT THE MIDDLE TIER", "source_digest": "925ddc60c6a44198030448f6263d82ed5942bdfaa4fc2ab14b478ca291ee2411", "situation": "You are a deputy store manager at a national home improvement chain, eighteen months in the role. Your store has met sales targets for three consecutive quarters. This morning your district manager delivered your annual performance review at ''meets expectations'', the middle tier of five.\n\nWhat the record shows: the written comments cite two items — inventory shrinkage above the regional average in two of four quarters, and three overdue staff certifications; the sales performance is recorded separately and is not criticized; the rating affects eligibility for the store manager development program, whose next intake closes in seven weeks; a shrinkage improvement plan template exists and has not been used at this store; and your district manager has offered a mid-year check-in.", "reveals": [{"code": "R1", "text": "What is the first thing you do?", "role": "Opening"}, {"code": "R2", "text": "What do you establish about the two items before you go further?", "role": "Information"}, {"code": "R3", "text": "What do you do about the conditions behind them?", "role": "Information"}, {"code": "R4", "text": "Whose help or what resource do you go to, if any?", "role": "Information"}, {"code": "R5", "text": "What work of yours continues, and from when?", "role": "Information"}, {"code": "R6", "text": "What do you do about the same two items at the next review, and what gets written down and where?", "role": "Information"}, {"code": "R7", "text": "Your district manager writes: \"You told me the shrinkage was above average in one quarter. Was it?\" What do you say?", "role": "Account test"}], "question_applicability": [{"question": "Q-D8-01", "state": "DIRECT", "basis": "The situation lists three containment actions"}, {"question": "Q-D8-01b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D8-02", "state": "DIRECT", "basis": "The situation designates four facts about the setback"}, {"question": "Q-D8-02b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D8-03", "state": "DIRECT", "basis": "The situation lists two actions on the condition behind the setback"}, {"question": "Q-D8-03b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D8-04", "state": "DIRECT", "basis": "The situation lists three supports"}, {"question": "Q-D8-04b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D8-05", "state": "DIRECT", "basis": "The situation lists three commitments in force"}, {"question": "Q-D8-05b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D8-06", "state": "DIRECT", "basis": "The situation lists two items of work under way"}, {"question": "Q-D8-06b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D8-07", "state": "DIRECT", "basis": "The situation lists three measures against the condition arising again"}, {"question": "Q-D8-07b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D8-08", "state": "DIRECT", "basis": "The situation names a place a record could be made"}, {"question": "Q-D8-09", "state": "DIRECT", "basis": "The account test puts an earlier statement back"}], "material_map": [{"Item": "CM1", "Item text": "the store''s sales targets", "Where the participant meets it": "The situation", "Quoted text": "store has met sales targets"}, {"Item": "CM2", "Item text": "the three overdue certifications", "Where the participant meets it": "The situation", "Quoted text": "three overdue staff certifications"}, {"Item": "CM3", "Item text": "the development program intake in seven weeks", "Where the participant meets it": "The situation", "Quoted text": "development program, whose next intake closes in seven weeks"}], "source_sheet": {"d8_situation_class": "SC-D8-5", "workplace_demand": "Continuing the store''s work after an annual review came in at the middle tier, citing two items.", "relevant_conduct": "Which containment action was stated; which facts about the setback were named; what action on the condition behind the setback was stated; which support was stated as one to go to; which commitments in force were named as still to be met; what work was named as continuing, and from when; what was stated about the condition arising again; whether a record was stated, and where; what was stated when an earlier statement was put back.", "irrelevant_conduct": "The district manager''s judgment; the rating scale; the participant''s self-assessment.", "stated_standard": null, "stated_standard_source_quote_or_location": null, "cross_context_map": null, "serving_eligible": false, "recurrence_eligible": true, "replacement_required": false, "name_clearance_status": "CLEARED", "name_clearance_basis": "Controlled role and entity labels only; no real person or organization is named.", "sensitivity_flag": null, "permitted_administration_variance": "Pronunciation only; accommodations affecting turn order or response window are recorded and set timing_not_comparable.", "unsupported_inferences": "That the rating was unfair; that three quarters of sales targets entitle a higher tier; any observation of how the review was received.", "compatibility_class": "S1-WRITTEN-SEQUENTIAL", "setback_established": "In the situation: \"you received ''meets expectations'', the middle tier of five.\"", "containment_actions": [{"id": "CA1", "text": "read the two cited items against the store''s own figures"}, {"id": "CA2", "text": "schedule the three overdue certifications"}, {"id": "CA3", "text": "confirm what the development program intake requires and by when"}], "corrective_actions": [{"id": "CR1", "text": "open the shrinkage improvement plan template for this store"}, {"id": "CR2", "text": "schedule the three overdue certifications"}], "designated_facts": [{"id": "DF1", "text": "what the two cited items say in the review''s own terms"}, {"id": "DF2", "text": "which quarters the shrinkage exceeded the regional average"}, {"id": "DF3", "text": "which three certifications are overdue and by how long"}, {"id": "DF4", "text": "what the development program intake requires and when it closes"}], "available_supports": [{"id": "SU1", "text": "the district manager''s offered mid-year check-in"}, {"id": "SU2", "text": "the shrinkage improvement plan template"}, {"id": "SU3", "text": "the regional training coordinator who schedules certifications"}], "standing_commitments": [{"id": "CM1", "text": "the store''s sales targets"}, {"id": "CM2", "text": "the three overdue certifications"}, {"id": "CM3", "text": "the development program intake in seven weeks"}], "work_in_progress": [{"id": "WP1", "text": "the store''s quarterly operation"}, {"id": "WP2", "text": "the certification schedule"}], "recurrence_measures": [{"id": "RM1", "text": "the shrinkage improvement plan run as a standing quarterly item"}, {"id": "RM2", "text": "a certification due-date tracker reviewed monthly"}, {"id": "RM3", "text": "a mid-year read of both items against the review criteria"}], "recurring_condition": "Shrinkage above the regional average in two of four quarters.", "formal_record_state": "The annual performance review, already issued.", "record_place": "The store''s operating plan and the participant''s development record.", "who_knows": "The district manager.", "decision_origin": "The district manager''s rating decision.", "account_test_point": "R7", "account_test_record": "The situation records shrinkage above the regional average in two of four quarters.", "list_note": null, "source_note": null, "situation_class_label": "An expected advancement or selection that has not come", "observation_mode_label": "written_response", "min_seconds": 360, "max_seconds": 1500}, "source_identifier": "SRC-D8-S1-008", "stage_code": "S1", "source_version_hash": "925ddc60c6a44198030448f6263d82ed5942bdfaa4fc2ab14b478ca291ee2411", "serving_eligible": false, "verbatim": "You are a deputy store manager at a national home improvement chain, eighteen months in the role. Your store has met sales targets for three consecutive quarters. This morning your district manager delivered your annual performance review at ''meets expectations'', the middle tier of five.\n\nWhat the record shows: the written comments cite two items — inventory shrinkage above the regional average in two of four quarters, and three overdue staff certifications; the sales performance is recorded separately and is not criticized; the rating affects eligibility for the store manager development program, whose next intake closes in seven weeks; a shrinkage improvement plan template exists and has not been used at this store; and your district manager has offered a mid-year check-in."}'::jsonb from public.t3a_content_object where identifier = 'SRC-D8-S1-008' and family = 'source'::public.t3a_content_family;
  insert into public.t3a_content_object(identifier, family, title, dimension_id, current_operational_state) values ('SRC-D8-S1-009', 'source'::public.t3a_content_family, 'EIGHT MONTHS AND THE FUNDING MOVED', 'D8', 'not_loaded'::public.t3a_operational_state);
  insert into public.t3a_d1_content_version(content_object_id, version_no, approval_status, operational_state, body) select content_object_id, 'v2.1', 'drafting', 'not_loaded'::public.t3a_operational_state, '{"stage": 1, "title": "EIGHT MONTHS AND THE FUNDING MOVED", "source_digest": "d221d2c4a7e47e14a1fad68dcfca5aa9c64979f24a8a7188dbac2c0971ec22e0", "situation": "You are a civil engineer. For eight months you have led the design phase of a $3.2 million pedestrian bridge for a municipal client — your first lead assignment. You assembled the team, managed the consultants and delivered ninety percent of the design package. This morning your director told you the council voted to redirect the bridge funding to a road-widening project and the contract is being terminated.\n\nWhat the record shows: the design package is ninety percent complete and the firm retains it under the contract''s termination clause; three external consultants are mid-engagement with notice periods of two to four weeks; your team of four has no next assignment named; the road-widening project is going to tender in five weeks and your firm intends to bid; and your director has asked what the firm should do with the work, by end of week.", "reveals": [{"code": "R1", "text": "What is the first thing you do, and about what?", "role": "Opening"}, {"code": "R2", "text": "What do you establish about the termination before you go further?", "role": "Information"}, {"code": "R3", "text": "What do you do about the three consultants and the team?", "role": "Information"}, {"code": "R4", "text": "Whose help or what resource do you go to, if any?", "role": "Information"}, {"code": "R5", "text": "What work continues, and from when?", "role": "Information"}, {"code": "R6", "text": "What do you do about a termination arising on the next engagement, and what gets written down and where?", "role": "Information"}, {"code": "R7", "text": "Your director writes: \"You said the design package was complete. Is it?\" What do you say?", "role": "Account test"}], "question_applicability": [{"question": "Q-D8-01", "state": "DIRECT", "basis": "The situation lists three containment actions"}, {"question": "Q-D8-01b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D8-02", "state": "DIRECT", "basis": "The situation designates four facts about the setback"}, {"question": "Q-D8-02b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D8-03", "state": "DIRECT", "basis": "The situation lists three actions on the condition behind the setback"}, {"question": "Q-D8-03b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D8-04", "state": "DIRECT", "basis": "The situation lists three supports"}, {"question": "Q-D8-04b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D8-05", "state": "DIRECT", "basis": "The situation lists three commitments in force"}, {"question": "Q-D8-05b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D8-06", "state": "DIRECT", "basis": "The situation lists three items of work under way"}, {"question": "Q-D8-06b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D8-07", "state": "DIRECT", "basis": "The situation lists three measures against the condition arising again"}, {"question": "Q-D8-07b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D8-08", "state": "DIRECT", "basis": "The situation names a place a record could be made"}, {"question": "Q-D8-09", "state": "DIRECT", "basis": "The account test puts an earlier statement back"}], "material_map": [{"Item": "CM1", "Item text": "the three consultants'' notice periods", "Where the participant meets it": "The situation", "Quoted text": "three external consultants are mid-engagement with notice periods"}, {"Item": "CM2", "Item text": "the position to the director by end of week", "Where the participant meets it": "The situation", "Quoted text": "asked what the firm should do with the work, by end of week"}, {"Item": "CM3", "Item text": "the team of four''s assignment", "Where the participant meets it": "The situation", "Quoted text": "your team of four has no next assignment named"}], "source_sheet": {"d8_situation_class": "SC-D8-2", "workplace_demand": "Deciding what happens to a nearly complete design package after the client redirected the project''s funding.", "relevant_conduct": "Which containment action was stated; which facts about the setback were named; what action on the condition behind the setback was stated; which support was stated as one to go to; which commitments in force were named as still to be met; what work was named as continuing, and from when; what was stated about the condition arising again; whether a record was stated, and where; what was stated when an earlier statement was put back.", "irrelevant_conduct": "The council''s decision; the road-widening project''s merits; the director''s handling.", "stated_standard": null, "stated_standard_source_quote_or_location": null, "cross_context_map": null, "serving_eligible": false, "recurrence_eligible": true, "replacement_required": false, "name_clearance_status": "CLEARED", "name_clearance_basis": "Controlled role and entity labels only; no real person or organization is named.", "sensitivity_flag": null, "permitted_administration_variance": "Pronunciation only; accommodations affecting turn order or response window are recorded and set timing_not_comparable.", "unsupported_inferences": "That eight months were wasted; that a first lead assignment ending this way indicates anything; any observation of how the termination was taken.", "compatibility_class": "S1-WRITTEN-SEQUENTIAL", "setback_established": "In the situation: \"the contract is being terminated.\"", "containment_actions": [{"id": "CA1", "text": "read the termination clause and confirm what the firm retains"}, {"id": "CA2", "text": "issue notice to the three consultants within their notice periods"}, {"id": "CA3", "text": "confirm what the team of four moves to and when"}], "corrective_actions": [{"id": "CR1", "text": "issue notice to the three consultants within their notice periods"}, {"id": "CR2", "text": "package the retained design work against the road-widening tender"}, {"id": "CR3", "text": "confirm what the team of four moves to and when"}], "designated_facts": [{"id": "DF1", "text": "what the termination clause provides about the retained work"}, {"id": "DF2", "text": "what each consultant''s notice period requires and by when"}, {"id": "DF3", "text": "what the road-widening tender opens and closes"}, {"id": "DF4", "text": "what remains outstanding in the ten percent not delivered"}], "available_supports": [{"id": "SU1", "text": "the director, who has asked for a position by end of week"}, {"id": "SU2", "text": "the firm''s contracts administrator"}, {"id": "SU3", "text": "the bid team preparing for the road-widening tender"}], "standing_commitments": [{"id": "CM1", "text": "the three consultants'' notice periods"}, {"id": "CM2", "text": "the position to the director by end of week"}, {"id": "CM3", "text": "the team of four''s assignment"}], "work_in_progress": [{"id": "WP1", "text": "the ninety percent design package"}, {"id": "WP2", "text": "the three consultant engagements"}, {"id": "WP3", "text": "the road-widening tender preparation"}], "recurrence_measures": [{"id": "RM1", "text": "consultant engagements written with termination-aligned notice periods"}, {"id": "RM2", "text": "a standing retained-work package at each design milestone"}, {"id": "RM3", "text": "a next-assignment review for the team at every phase gate"}], "recurring_condition": null, "formal_record_state": "The council''s vote and the contract termination notice.", "record_place": "The firm''s project closeout file.", "who_knows": "The director, the consultants and the team.", "decision_origin": "The municipal council''s vote, external to the firm.", "account_test_point": "R7", "account_test_record": "The situation records that the design package is ninety percent complete.", "list_note": null, "source_note": null, "situation_class_label": "Sustained work ended or withdrawn by a decision outside the participant''s control", "observation_mode_label": "written_response", "min_seconds": 360, "max_seconds": 1500}, "source_identifier": "SRC-D8-S1-009", "stage_code": "S1", "source_version_hash": "d221d2c4a7e47e14a1fad68dcfca5aa9c64979f24a8a7188dbac2c0971ec22e0", "serving_eligible": false, "verbatim": "You are a civil engineer. For eight months you have led the design phase of a $3.2 million pedestrian bridge for a municipal client — your first lead assignment. You assembled the team, managed the consultants and delivered ninety percent of the design package. This morning your director told you the council voted to redirect the bridge funding to a road-widening project and the contract is being terminated.\n\nWhat the record shows: the design package is ninety percent complete and the firm retains it under the contract''s termination clause; three external consultants are mid-engagement with notice periods of two to four weeks; your team of four has no next assignment named; the road-widening project is going to tender in five weeks and your firm intends to bid; and your director has asked what the firm should do with the work, by end of week."}'::jsonb from public.t3a_content_object where identifier = 'SRC-D8-S1-009' and family = 'source'::public.t3a_content_family;
  insert into public.t3a_content_object(identifier, family, title, dimension_id, current_operational_state) values ('SRC-D8-S2-001', 'source'::public.t3a_content_family, 'THE MEETING THAT ENDED AFTER NINE MINUTES', 'D8', 'not_loaded'::public.t3a_operational_state);
  insert into public.t3a_d1_content_version(content_object_id, version_no, approval_status, operational_state, body) select content_object_id, 'v2.1', 'drafting', 'not_loaded'::public.t3a_operational_state, '{"stage": 2, "title": "THE MEETING THAT ENDED AFTER NINE MINUTES", "source_digest": "9bcf21dd892ff7794b0ee57906d3ff28a257d684f195fb6a4231fc82ccbcccfa", "mentor_brief": "The mentor reads the scripted lines of the brokerage principal. The mentor forms no view of how the participant is taking it and records nothing about it. No escalation, no repetition, no expressive reaction. The mentor reads the scripted lines verbatim, reacts to nothing, and does not press, repeat or escalate, whatever the participant says or does not say. Nothing observed about the person is recordable: only what the participant states about the work.", "participant_pre_brief": "You are a commercial leasing agent. You have worked a prospective tenant for three months and prepared a proposal covering three properties with walkthrough videos and a financial comparison. Nine minutes into today''s presentation the prospect''s representative stood, said the requirement had changed, and left. What the record shows: the requirement change is not specified; the three properties remain available and two have competing interest; your brokerage''s pipeline review is Thursday and this prospect is your largest entry; the proposal materials are reusable; and the prospect''s representative has not responded to a message sent twenty minutes after they left.", "script": [{"beat": "B1", "type": "SAY", "spoken": "I heard the meeting ended early. I would like to know where things stand. I will let you start.", "direction": null, "capture": []}, {"beat": "B2", "type": "PAUSE", "spoken": null, "direction": "Say nothing for ten to fifteen seconds. Do not prompt or fill the silence.", "capture": [{"set": "C1", "state": "open"}, {"set": "C1b", "state": "open"}, {"set": "C2", "state": "open"}, {"set": "C2b", "state": "open"}, {"set": "C3", "state": "open"}, {"set": "C3b", "state": "open"}, {"set": "C4", "state": "open"}, {"set": "C4b", "state": "open"}, {"set": "C5", "state": "open"}, {"set": "C5b", "state": "open"}, {"set": "C6", "state": "open"}, {"set": "C6b", "state": "open"}, {"set": "C7", "state": "open"}, {"set": "C7b", "state": "open"}, {"set": "C8", "state": "open"}]}, {"beat": "B3", "type": "ASK", "spoken": "What have you done since they left, and what do you know?", "direction": "Read once, verbatim.", "capture": [{"set": "C1", "state": "update"}, {"set": "C1b", "state": "update"}, {"set": "C2", "state": "update"}, {"set": "C2b", "state": "update"}]}, {"beat": "B4", "type": "ASK", "spoken": "What are you doing about the position itself, and who are you going to?", "direction": "Read once, verbatim.", "capture": [{"set": "C3", "state": "update"}, {"set": "C3b", "state": "update"}, {"set": "C4", "state": "update"}, {"set": "C4b", "state": "update"}]}, {"beat": "B5", "type": "ASK", "spoken": "What still gets met, what picks up again and when, and what goes on the record?", "direction": "Read once, verbatim.", "capture": [{"set": "C5", "state": "update"}, {"set": "C5b", "state": "update"}, {"set": "C6", "state": "update"}, {"set": "C6b", "state": "update"}, {"set": "C7", "state": "update"}, {"set": "C7b", "state": "update"}, {"set": "C8", "state": "update"}]}, {"beat": "B6", "type": "ASK", "spoken": "Just so I have it right — you said two of the three properties are still open. Is that so?", "direction": "Read once, verbatim.", "capture": [{"set": "C9", "state": "open"}]}, {"beat": "B7", "type": "SAY", "spoken": "Thank you. That is the end of the session.", "direction": "End the session.", "capture": [{"set": "C1", "state": "final"}, {"set": "C2", "state": "final"}, {"set": "C3", "state": "final"}, {"set": "C4", "state": "final"}, {"set": "C5", "state": "final"}, {"set": "C6", "state": "final"}, {"set": "C7", "state": "final"}, {"set": "C8", "state": "final"}, {"set": "C9", "state": "final"}]}], "question_applicability": [{"question": "Q-D8-01", "state": "DIRECT", "basis": "The situation lists three containment actions"}, {"question": "Q-D8-01b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D8-02", "state": "DIRECT", "basis": "The situation designates four facts about the setback"}, {"question": "Q-D8-02b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D8-03", "state": "DIRECT", "basis": "The situation lists two actions on the condition behind the setback"}, {"question": "Q-D8-03b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D8-04", "state": "DIRECT", "basis": "The situation lists three supports"}, {"question": "Q-D8-04b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D8-05", "state": "DIRECT", "basis": "The situation lists two commitments in force"}, {"question": "Q-D8-05b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D8-06", "state": "DIRECT", "basis": "The situation lists two items of work under way"}, {"question": "Q-D8-06b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D8-07", "state": "DIRECT", "basis": "The situation lists two measures against the condition arising again"}, {"question": "Q-D8-07b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D8-08", "state": "DIRECT", "basis": "The situation names a place a record could be made"}, {"question": "Q-D8-09", "state": "DIRECT", "basis": "The account test puts an earlier statement back"}], "material_map": [{"Item": "CM1", "Item text": "Thursday''s pipeline review", "Where the participant meets it": "The pre-brief", "Quoted text": "pipeline review is Thursday"}, {"Item": "CM2", "Item text": "the three property listings the participant carries", "Where the participant meets it": "The pre-brief", "Quoted text": "the three properties remain available"}], "source_sheet": {"d8_situation_class": "SC-D8-2", "workplace_demand": "Speaking with the brokerage principal after a three-month prospect left a presentation nine minutes in.", "relevant_conduct": "Which containment action was stated; which facts about the setback were named; what action on the condition behind the setback was stated; which support was stated as one to go to; which commitments in force were named as still to be met; what work was named as continuing, and from when; what was stated about the condition arising again; whether a record was stated, and where; what was stated when an earlier statement was put back.", "irrelevant_conduct": "The prospect''s conduct; whether the walkout was reasonable.", "stated_standard": null, "stated_standard_source_quote_or_location": null, "cross_context_map": null, "serving_eligible": false, "recurrence_eligible": true, "replacement_required": false, "name_clearance_status": "CLEARED", "name_clearance_basis": "Controlled role and entity labels only; no real person or organization is named.", "sensitivity_flag": null, "permitted_administration_variance": "Pronunciation only; accommodations affecting turn order or response window are recorded and set timing_not_comparable.", "unsupported_inferences": "That three months were wasted; that the participant should have seen it coming; any observation of how the walkout was taken, including that it seemed not to register.", "compatibility_class": "S2-SEVEN-BEAT", "setback_established": "In the pre-brief: \"the prospect''s representative stood, said the requirement had changed, and left.\"", "containment_actions": [{"id": "CA1", "text": "write to the prospect asking what the changed requirement is"}, {"id": "CA2", "text": "confirm the standing of the three properties against the competing interest"}, {"id": "CA3", "text": "update the pipeline entry before Thursday''s review"}], "corrective_actions": [{"id": "CR1", "text": "confirm the standing of the three properties against the competing interest"}, {"id": "CR2", "text": "re-cut the proposal materials against a changed requirement"}], "designated_facts": [{"id": "DF1", "text": "what was said at the point the meeting ended, in its own terms"}, {"id": "DF2", "text": "which of the three properties carry competing interest"}, {"id": "DF3", "text": "whether the prospect has responded to the message already sent"}, {"id": "DF4", "text": "what Thursday''s pipeline review requires of this entry"}], "available_supports": [{"id": "SU1", "text": "the brokerage principal, in this session"}, {"id": "SU2", "text": "the property owners holding the three listings"}, {"id": "SU3", "text": "the proposal materials, reusable as they stand"}], "standing_commitments": [{"id": "CM1", "text": "Thursday''s pipeline review"}, {"id": "CM2", "text": "the three property listings the participant carries"}], "work_in_progress": [{"id": "WP1", "text": "the prospect engagement"}, {"id": "WP2", "text": "the three listings"}], "recurrence_measures": [{"id": "RM1", "text": "a requirement re-confirmation at the halfway point of any engagement"}, {"id": "RM2", "text": "pipeline entries carrying a confirmed-requirement date"}], "recurring_condition": null, "formal_record_state": null, "record_place": "The brokerage pipeline record.", "who_knows": "The principal.", "decision_origin": "The prospect''s decision, external.", "account_test_point": "B6", "account_test_record": "The situation records that the three properties remain available.", "list_note": null, "source_note": null, "situation_class_label": "Sustained work ended or withdrawn by a decision outside the participant''s control", "observation_mode_label": "structured_live_session", "min_seconds": 480, "max_seconds": 900}, "source_identifier": "SRC-D8-S2-001", "stage_code": "S2", "source_version_hash": "9bcf21dd892ff7794b0ee57906d3ff28a257d684f195fb6a4231fc82ccbcccfa", "serving_eligible": false, "verbatim": ""}'::jsonb from public.t3a_content_object where identifier = 'SRC-D8-S2-001' and family = 'source'::public.t3a_content_family;
  insert into public.t3a_content_object(identifier, family, title, dimension_id, current_operational_state) values ('SRC-D8-S2-002', 'source'::public.t3a_content_family, 'THE EXCEPTION REPORT SHOWN TO THE STAND-UP', 'D8', 'not_loaded'::public.t3a_operational_state);
  insert into public.t3a_d1_content_version(content_object_id, version_no, approval_status, operational_state, body) select content_object_id, 'v2.1', 'drafting', 'not_loaded'::public.t3a_operational_state, '{"stage": 2, "title": "THE EXCEPTION REPORT SHOWN TO THE STAND-UP", "source_digest": "6d6d7de295607a61ab200d39d7664558c3ad43b318a09944c071b504984bc6af", "mentor_brief": "The mentor reads the scripted lines of the supervisor. The mentor states nothing beyond the script, does not defend or withdraw the attribution, and forms no view of the participant''s response to being named in front of colleagues. The mentor reads the scripted lines verbatim, reacts to nothing, and does not press, repeat or escalate, whatever the participant says or does not say. Nothing observed about the person is recordable: only what the participant states about the work.", "participant_pre_brief": "You are a logistics coordinator. In this morning''s stand-up with twelve colleagues, your supervisor shared a screen showing a warehouse system exception report flagging a $14,000 inventory discrepancy from last Thursday, and said the exception traces to your receiving entries. What the record shows: the exception report names a receiving batch, not a user; the batch in question was received across two shifts; your entries for that batch are timestamped and complete; the system''s user attribution field has been blank on all exceptions since a permissions change six weeks ago; a reconciliation route exists and takes about ninety minutes; and the stand-up ended without a conclusion.", "script": [{"beat": "B1", "type": "SAY", "spoken": "I want to pick up on the exception from the stand-up. I will let you start.", "direction": null, "capture": []}, {"beat": "B2", "type": "PAUSE", "spoken": null, "direction": "Say nothing for ten to fifteen seconds. Do not prompt or fill the silence.", "capture": [{"set": "C1", "state": "open"}, {"set": "C1b", "state": "open"}, {"set": "C2", "state": "open"}, {"set": "C2b", "state": "open"}, {"set": "C3", "state": "open"}, {"set": "C3b", "state": "open"}, {"set": "C4", "state": "open"}, {"set": "C4b", "state": "open"}, {"set": "C5", "state": "open"}, {"set": "C5b", "state": "open"}, {"set": "C6", "state": "open"}, {"set": "C6b", "state": "open"}, {"set": "C7", "state": "open"}, {"set": "C7b", "state": "open"}, {"set": "C8", "state": "open"}]}, {"beat": "B3", "type": "ASK", "spoken": "What have you done since the stand-up, and what do you know?", "direction": "Read once, verbatim.", "capture": [{"set": "C1", "state": "update"}, {"set": "C1b", "state": "update"}, {"set": "C2", "state": "update"}, {"set": "C2b", "state": "update"}]}, {"beat": "B4", "type": "ASK", "spoken": "What are you doing about the discrepancy itself, and who are you going to?", "direction": "Read once, verbatim.", "capture": [{"set": "C3", "state": "update"}, {"set": "C3b", "state": "update"}, {"set": "C4", "state": "update"}, {"set": "C4b", "state": "update"}]}, {"beat": "B5", "type": "ASK", "spoken": "What still gets met, what picks up again and when, and what goes on the record?", "direction": "Read once, verbatim.", "capture": [{"set": "C5", "state": "update"}, {"set": "C5b", "state": "update"}, {"set": "C6", "state": "update"}, {"set": "C6b", "state": "update"}, {"set": "C7", "state": "update"}, {"set": "C7b", "state": "update"}, {"set": "C8", "state": "update"}]}, {"beat": "B6", "type": "ASK", "spoken": "Just so I have it right — you said the report names you. Does it?", "direction": "Read once, verbatim.", "capture": [{"set": "C9", "state": "open"}]}, {"beat": "B7", "type": "SAY", "spoken": "Thank you. That is the end of the session.", "direction": "End the session.", "capture": [{"set": "C1", "state": "final"}, {"set": "C2", "state": "final"}, {"set": "C3", "state": "final"}, {"set": "C4", "state": "final"}, {"set": "C5", "state": "final"}, {"set": "C6", "state": "final"}, {"set": "C7", "state": "final"}, {"set": "C8", "state": "final"}, {"set": "C9", "state": "final"}]}], "question_applicability": [{"question": "Q-D8-01", "state": "DIRECT", "basis": "The situation lists three containment actions"}, {"question": "Q-D8-01b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D8-02", "state": "DIRECT", "basis": "The situation designates four facts about the setback"}, {"question": "Q-D8-02b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D8-03", "state": "DIRECT", "basis": "The situation lists two actions on the condition behind the setback"}, {"question": "Q-D8-03b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D8-04", "state": "DIRECT", "basis": "The situation lists three supports"}, {"question": "Q-D8-04b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D8-05", "state": "DIRECT", "basis": "The situation lists two commitments in force"}, {"question": "Q-D8-05b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D8-06", "state": "DIRECT", "basis": "The situation lists two items of work under way"}, {"question": "Q-D8-06b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D8-07", "state": "DIRECT", "basis": "The situation lists three measures against the condition arising again"}, {"question": "Q-D8-07b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D8-08", "state": "DIRECT", "basis": "The situation names a place a record could be made"}, {"question": "Q-D8-09", "state": "DIRECT", "basis": "The account test puts an earlier statement back"}], "material_map": [{"Item": "CM1", "Item text": "the receiving entries the role carries", "Where the participant meets it": "The pre-brief", "Quoted text": "the exception traces to your receiving entries"}, {"Item": "CM2", "Item text": "the warehouse system''s inventory record", "Where the participant meets it": "The pre-brief", "Quoted text": "a warehouse system exception report flagging"}], "source_sheet": {"d8_situation_class": "SC-D8-7", "workplace_demand": "Speaking with a supervisor after an inventory exception was attributed to the participant''s entries in front of the team.", "relevant_conduct": "Which containment action was stated; which facts about the setback were named; what action on the condition behind the setback was stated; which support was stated as one to go to; which commitments in force were named as still to be met; what work was named as continuing, and from when; what was stated about the condition arising again; whether a record was stated, and where; what was stated when an earlier statement was put back.", "irrelevant_conduct": "The supervisor; who is answerable for the discrepancy, which is a D2 matter.", "stated_standard": null, "stated_standard_source_quote_or_location": null, "cross_context_map": null, "serving_eligible": false, "recurrence_eligible": true, "replacement_required": false, "name_clearance_status": "CLEARED", "name_clearance_basis": "Controlled role and entity labels only; no real person or organization is named.", "sensitivity_flag": "SENSITIVE_CONTENT", "permitted_administration_variance": "Pronunciation only; accommodations affecting turn order or response window are recorded and set timing_not_comparable.", "unsupported_inferences": "That the participant should defend themselves; any observation of embarrassment or its absence; any view of the supervisor''s conduct or of being named in front of colleagues.", "compatibility_class": "S2-SEVEN-BEAT", "setback_established": "In the pre-brief: \"he shares his screen... and said the exception traces to your receiving entries.\"", "containment_actions": [{"id": "CA1", "text": "run the ninety-minute reconciliation on the named batch"}, {"id": "CA2", "text": "establish what the exception report names and what it does not"}, {"id": "CA3", "text": "set out the batch''s two-shift receiving record"}], "corrective_actions": [{"id": "CR1", "text": "run the ninety-minute reconciliation on the named batch"}, {"id": "CR2", "text": "raise the blank user attribution field with the systems owner"}], "designated_facts": [{"id": "DF1", "text": "what the exception report names — a batch, not a user"}, {"id": "DF2", "text": "that the batch was received across two shifts"}, {"id": "DF3", "text": "that the user attribution field has been blank since the permissions change"}, {"id": "DF4", "text": "what the reconciliation route requires and how long it takes"}], "available_supports": [{"id": "SU1", "text": "the supervisor, in this session"}, {"id": "SU2", "text": "the systems owner who holds the permissions change"}, {"id": "SU3", "text": "the second shift''s receiving lead"}], "standing_commitments": [{"id": "CM1", "text": "the receiving entries the role carries"}, {"id": "CM2", "text": "the warehouse system''s inventory record"}], "work_in_progress": [{"id": "WP1", "text": "the day''s receiving"}, {"id": "WP2", "text": "the reconciliation"}], "recurrence_measures": [{"id": "RM1", "text": "the user attribution field restored on exception reports"}, {"id": "RM2", "text": "batch receiving recorded by shift as standing practice"}, {"id": "RM3", "text": "exceptions reconciled before they reach a stand-up"}], "recurring_condition": "The blank attribution field on all exceptions for six weeks.", "formal_record_state": "The system exception report.", "record_place": "The reconciliation record and the systems change log.", "who_knows": "The supervisor and the twelve in the stand-up.", "decision_origin": null, "account_test_point": "B6", "account_test_record": "The situation records that the exception report names a receiving batch, not a user.", "list_note": null, "source_note": "Higher review standard: An attribution about the participant is made in front of twelve colleagues; the review standard is higher, and nothing about the person may be recorded.", "situation_class_label": "An attribution about the participant made in front of others", "observation_mode_label": "structured_live_session", "min_seconds": 480, "max_seconds": 900}, "source_identifier": "SRC-D8-S2-002", "stage_code": "S2", "source_version_hash": "6d6d7de295607a61ab200d39d7664558c3ad43b318a09944c071b504984bc6af", "serving_eligible": false, "verbatim": ""}'::jsonb from public.t3a_content_object where identifier = 'SRC-D8-S2-002' and family = 'source'::public.t3a_content_family;
  insert into public.t3a_content_object(identifier, family, title, dimension_id, current_operational_state) values ('SRC-D8-S2-003', 'source'::public.t3a_content_family, 'NINETY DAYS AND SIXTY-FIVE PERCENT OF THE BUDGET', 'D8', 'not_loaded'::public.t3a_operational_state);
  insert into public.t3a_d1_content_version(content_object_id, version_no, approval_status, operational_state, body) select content_object_id, 'v2.1', 'drafting', 'not_loaded'::public.t3a_operational_state, '{"stage": 2, "title": "NINETY DAYS AND SIXTY-FIVE PERCENT OF THE BUDGET", "source_digest": "bd2b2d5862210039068e9dff1762dc185714eff03e57c3faa2ce9deb64462e28", "mentor_brief": "The mentor reads the scripted lines of the board chair. The mentor asks the scripted questions once each and forms no view of how the participant is bearing the news. The mentor reads the scripted lines verbatim, reacts to nothing, and does not press, repeat or escalate, whatever the participant says or does not say. Nothing observed about the person is recordable: only what the participant states about the work.", "participant_pre_brief": "You are program director at a small non-profit providing digital literacy training. This morning your primary funder discontinued a $180,000 annual grant, sixty-five percent of the operating budget, effective in ninety days. What the record shows: the current cohort of thirty participants is midway through a twelve-week course that ends in six weeks; two further funders have open application windows closing in four and eleven weeks; three staff are on contracts expiring within the ninety days; the discontinuation letter cites a change in the funder''s priorities and names no issue with the program; and your board meets in eight days.", "script": [{"beat": "B1", "type": "SAY", "spoken": "I have seen the funder''s letter. The board meets in eight days. I will let you start.", "direction": null, "capture": []}, {"beat": "B2", "type": "PAUSE", "spoken": null, "direction": "Say nothing for ten to fifteen seconds. Do not prompt or fill the silence.", "capture": [{"set": "C1", "state": "open"}, {"set": "C1b", "state": "open"}, {"set": "C2", "state": "open"}, {"set": "C2b", "state": "open"}, {"set": "C3", "state": "open"}, {"set": "C3b", "state": "open"}, {"set": "C4", "state": "open"}, {"set": "C4b", "state": "open"}, {"set": "C5", "state": "open"}, {"set": "C5b", "state": "open"}, {"set": "C6", "state": "open"}, {"set": "C6b", "state": "open"}, {"set": "C7", "state": "open"}, {"set": "C7b", "state": "open"}, {"set": "C8", "state": "open"}]}, {"beat": "B3", "type": "ASK", "spoken": "What have you done since the letter, and what do you know?", "direction": "Read once, verbatim.", "capture": [{"set": "C1", "state": "update"}, {"set": "C1b", "state": "update"}, {"set": "C2", "state": "update"}, {"set": "C2b", "state": "update"}]}, {"beat": "B4", "type": "ASK", "spoken": "What are you doing about the funding position itself, and who are you going to?", "direction": "Read once, verbatim.", "capture": [{"set": "C3", "state": "update"}, {"set": "C3b", "state": "update"}, {"set": "C4", "state": "update"}, {"set": "C4b", "state": "update"}]}, {"beat": "B5", "type": "ASK", "spoken": "What still gets met, what continues and from when, and what goes to the board?", "direction": "Read once, verbatim.", "capture": [{"set": "C5", "state": "update"}, {"set": "C5b", "state": "update"}, {"set": "C6", "state": "update"}, {"set": "C6b", "state": "update"}, {"set": "C7", "state": "update"}, {"set": "C7b", "state": "update"}, {"set": "C8", "state": "update"}]}, {"beat": "B6", "type": "ASK", "spoken": "Just so I have it right — you said the letter raised concerns about the program. Did it?", "direction": "Read once, verbatim.", "capture": [{"set": "C9", "state": "open"}]}, {"beat": "B7", "type": "SAY", "spoken": "Thank you. That is the end of the session.", "direction": "End the session.", "capture": [{"set": "C1", "state": "final"}, {"set": "C2", "state": "final"}, {"set": "C3", "state": "final"}, {"set": "C4", "state": "final"}, {"set": "C5", "state": "final"}, {"set": "C6", "state": "final"}, {"set": "C7", "state": "final"}, {"set": "C8", "state": "final"}, {"set": "C9", "state": "final"}]}], "question_applicability": [{"question": "Q-D8-01", "state": "DIRECT", "basis": "The situation lists four containment actions"}, {"question": "Q-D8-01b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D8-02", "state": "DIRECT", "basis": "The situation designates four facts about the setback"}, {"question": "Q-D8-02b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D8-03", "state": "DIRECT", "basis": "The situation lists two actions on the condition behind the setback"}, {"question": "Q-D8-03b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D8-04", "state": "DIRECT", "basis": "The situation lists three supports"}, {"question": "Q-D8-04b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D8-05", "state": "DIRECT", "basis": "The situation lists three commitments in force"}, {"question": "Q-D8-05b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D8-06", "state": "DIRECT", "basis": "The situation lists two items of work under way"}, {"question": "Q-D8-06b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D8-07", "state": "DIRECT", "basis": "The situation lists three measures against the condition arising again"}, {"question": "Q-D8-07b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D8-08", "state": "DIRECT", "basis": "The situation names a place a record could be made"}, {"question": "Q-D8-09", "state": "DIRECT", "basis": "The account test puts an earlier statement back"}], "material_map": [{"Item": "CM1", "Item text": "the current cohort''s twelve-week course", "Where the participant meets it": "The pre-brief", "Quoted text": "a twelve-week course that ends in six weeks"}, {"Item": "CM2", "Item text": "the three staff contracts inside the ninety days", "Where the participant meets it": "The pre-brief", "Quoted text": "three staff are on contracts expiring within the ninety days"}, {"Item": "CM3", "Item text": "the board position in eight days", "Where the participant meets it": "The pre-brief", "Quoted text": "your board meets in eight days"}], "source_sheet": {"d8_situation_class": "SC-D8-2", "workplace_demand": "Speaking with the board chair after the primary funder discontinued most of the operating budget with ninety days'' notice.", "relevant_conduct": "Which containment action was stated; which facts about the setback were named; what action on the condition behind the setback was stated; which support was stated as one to go to; which commitments in force were named as still to be met; what work was named as continuing, and from when; what was stated about the condition arising again; whether a record was stated, and where; what was stated when an earlier statement was put back.", "irrelevant_conduct": "The funder''s decision; the participants'' circumstances; the staff''s prospects.", "stated_standard": null, "stated_standard_source_quote_or_location": null, "cross_context_map": null, "serving_eligible": false, "recurrence_eligible": true, "replacement_required": false, "name_clearance_status": "CLEARED", "name_clearance_basis": "Controlled role and entity labels only; no real person or organization is named.", "sensitivity_flag": null, "permitted_administration_variance": "Pronunciation only; accommodations affecting turn order or response window are recorded and set timing_not_comparable.", "unsupported_inferences": "That the discontinuation reflects on the program; that the participant should have diversified sooner; any observation of alarm, steadiness or its absence.", "compatibility_class": "S2-SEVEN-BEAT", "setback_established": "In the pre-brief: \"your primary funder discontinued a $180,000 annual grant... effective in ninety days.\"", "containment_actions": [{"id": "CA1", "text": "confirm the current cohort can be completed inside the ninety days"}, {"id": "CA2", "text": "open the two funder applications against their closing windows"}, {"id": "CA3", "text": "set out the three expiring contracts against the ninety days"}, {"id": "CA4", "text": "prepare the position for the board in eight days"}], "corrective_actions": [{"id": "CR1", "text": "open the two funder applications against their closing windows"}, {"id": "CR2", "text": "set out the three expiring contracts against the ninety days"}], "designated_facts": [{"id": "DF1", "text": "what the discontinuation letter states and what it does not"}, {"id": "DF2", "text": "when the current cohort ends against the ninety days"}, {"id": "DF3", "text": "what the two open funder windows require and when they close"}, {"id": "DF4", "text": "which three contracts expire and when"}], "available_supports": [{"id": "SU1", "text": "the board chair, in this session, and the board in eight days"}, {"id": "SU2", "text": "the two funders with open windows"}, {"id": "SU3", "text": "the program''s completion record for the current cohort"}], "standing_commitments": [{"id": "CM1", "text": "the current cohort''s twelve-week course"}, {"id": "CM2", "text": "the three staff contracts inside the ninety days"}, {"id": "CM3", "text": "the board position in eight days"}], "work_in_progress": [{"id": "WP1", "text": "the current cohort"}, {"id": "WP2", "text": "the two funder applications"}], "recurrence_measures": [{"id": "RM1", "text": "no single funder above a stated share of operating budget"}, {"id": "RM2", "text": "a standing pipeline of applications ahead of each funding year"}, {"id": "RM3", "text": "cohort scheduling aligned to funding confirmation dates"}], "recurring_condition": null, "formal_record_state": "The funder''s discontinuation letter.", "record_place": "The board papers and the funding register.", "who_knows": "The board chair.", "decision_origin": "The funder''s priority change, external.", "account_test_point": "B6", "account_test_record": "The situation records that the discontinuation letter names no issue with the program.", "list_note": null, "source_note": null, "situation_class_label": "Sustained work ended or withdrawn by a decision outside the participant''s control", "observation_mode_label": "structured_live_session", "min_seconds": 480, "max_seconds": 900}, "source_identifier": "SRC-D8-S2-003", "stage_code": "S2", "source_version_hash": "bd2b2d5862210039068e9dff1762dc185714eff03e57c3faa2ce9deb64462e28", "serving_eligible": false, "verbatim": ""}'::jsonb from public.t3a_content_object where identifier = 'SRC-D8-S2-003' and family = 'source'::public.t3a_content_family;
  insert into public.t3a_content_object(identifier, family, title, dimension_id, current_operational_state) values ('SRC-D8-S2-004', 'source'::public.t3a_content_family, 'THE PANEL INSTALL WITH NO JOURNEYMAN', 'D8', 'not_loaded'::public.t3a_operational_state);
  insert into public.t3a_d1_content_version(content_object_id, version_no, approval_status, operational_state, body) select content_object_id, 'v2.1', 'drafting', 'not_loaded'::public.t3a_operational_state, '{"stage": 2, "title": "THE PANEL INSTALL WITH NO JOURNEYMAN", "source_digest": "64ca9ed50b1d392e7365151b6e07574ee53aa4443ddbe4d1c328e10b81a42c06", "mentor_brief": "The mentor reads the scripted lines of the site supervisor. The mentor states the six-week position once and does not repeat, soften or defend it, and forms no view of the participant''s response to losing their mentor. The mentor reads the scripted lines verbatim, reacts to nothing, and does not press, repeat or escalate, whatever the participant says or does not say. Nothing observed about the person is recordable: only what the participant states about the work.", "participant_pre_brief": "You are a second-year electrical apprentice at a facilities contractor. Your journeyman mentor resigned yesterday with immediate effect. The site supervisor tells you no dedicated journeyman is available for six weeks and you will work with rotating supervisors from different trades. You have a complex panel install scheduled for tomorrow. What the record shows: apprentice regulations require a qualified supervising electrician present for panel work; the rotating supervisors named are a millwright and a pipefitter, neither qualified to supervise electrical; a second-year apprentice may perform panel work under supervision but not unsupervised; the install has a client date of tomorrow; and the contractor holds a call-off arrangement with two licensed subcontractors.", "script": [{"beat": "B1", "type": "SAY", "spoken": "You have heard there is no dedicated journeyman for six weeks. The panel install is tomorrow. I will let you start.", "direction": null, "capture": []}, {"beat": "B2", "type": "PAUSE", "spoken": null, "direction": "Say nothing for ten to fifteen seconds. Do not prompt or fill the silence.", "capture": [{"set": "C1", "state": "open"}, {"set": "C1b", "state": "open"}, {"set": "C2", "state": "open"}, {"set": "C2b", "state": "open"}, {"set": "C3", "state": "open"}, {"set": "C3b", "state": "open"}, {"set": "C4", "state": "open"}, {"set": "C4b", "state": "open"}, {"set": "C5", "state": "open"}, {"set": "C5b", "state": "open"}, {"set": "C6", "state": "open"}, {"set": "C6b", "state": "open"}, {"set": "C7", "state": "open"}, {"set": "C7b", "state": "open"}, {"set": "C8", "state": "open"}]}, {"beat": "B3", "type": "ASK", "spoken": "What have you done since yesterday, and what do you know?", "direction": "Read once, verbatim.", "capture": [{"set": "C1", "state": "update"}, {"set": "C1b", "state": "update"}, {"set": "C2", "state": "update"}, {"set": "C2b", "state": "update"}]}, {"beat": "B4", "type": "ASK", "spoken": "What are you doing about tomorrow''s install, and who are you going to?", "direction": "Read once, verbatim.", "capture": [{"set": "C3", "state": "update"}, {"set": "C3b", "state": "update"}, {"set": "C4", "state": "update"}, {"set": "C4b", "state": "update"}]}, {"beat": "B5", "type": "ASK", "spoken": "What still gets met, what carries on and from when, and what goes on the record?", "direction": "Read once, verbatim.", "capture": [{"set": "C5", "state": "update"}, {"set": "C5b", "state": "update"}, {"set": "C6", "state": "update"}, {"set": "C6b", "state": "update"}, {"set": "C7", "state": "update"}, {"set": "C7b", "state": "update"}, {"set": "C8", "state": "update"}]}, {"beat": "B6", "type": "ASK", "spoken": "Just so I have it right — you said one of the rotating supervisors is a qualified electrician. Is that so?", "direction": "Read once, verbatim.", "capture": [{"set": "C9", "state": "open"}]}, {"beat": "B7", "type": "SAY", "spoken": "Thank you. That is the end of the session.", "direction": "End the session.", "capture": [{"set": "C1", "state": "final"}, {"set": "C2", "state": "final"}, {"set": "C3", "state": "final"}, {"set": "C4", "state": "final"}, {"set": "C5", "state": "final"}, {"set": "C6", "state": "final"}, {"set": "C7", "state": "final"}, {"set": "C8", "state": "final"}, {"set": "C9", "state": "final"}]}], "question_applicability": [{"question": "Q-D8-01", "state": "DIRECT", "basis": "The situation lists four containment actions"}, {"question": "Q-D8-01b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D8-02", "state": "DIRECT", "basis": "The situation designates four facts about the setback"}, {"question": "Q-D8-02b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D8-03", "state": "DIRECT", "basis": "The situation lists two actions on the condition behind the setback"}, {"question": "Q-D8-03b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D8-04", "state": "DIRECT", "basis": "The situation lists three supports"}, {"question": "Q-D8-04b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D8-05", "state": "DIRECT", "basis": "The situation lists three commitments in force"}, {"question": "Q-D8-05b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D8-06", "state": "DIRECT", "basis": "The situation lists two items of work under way"}, {"question": "Q-D8-06b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D8-07", "state": "DIRECT", "basis": "The situation lists three measures against the condition arising again"}, {"question": "Q-D8-07b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D8-08", "state": "DIRECT", "basis": "The situation names a place a record could be made"}, {"question": "Q-D8-09", "state": "DIRECT", "basis": "The account test puts an earlier statement back"}], "material_map": [{"Item": "CM1", "Item text": "tomorrow''s client date for the panel install", "Where the participant meets it": "The pre-brief", "Quoted text": "the install has a client date of tomorrow"}, {"Item": "CM2", "Item text": "the apprentice supervision requirement", "Where the participant meets it": "The pre-brief", "Quoted text": "require a qualified supervising electrician present for panel work"}, {"Item": "CM3", "Item text": "the six weeks of work under rotating supervisors", "Where the participant meets it": "The pre-brief", "Quoted text": "you will work with rotating supervisors from different trades"}], "source_sheet": {"d8_situation_class": "SC-D8-6", "workplace_demand": "Speaking with the site supervisor about a panel install due tomorrow after the journeyman mentor resigned.", "relevant_conduct": "Which containment action was stated; which facts about the setback were named; what action on the condition behind the setback was stated; which support was stated as one to go to; which commitments in force were named as still to be met; what work was named as continuing, and from when; what was stated about the condition arising again; whether a record was stated, and where; what was stated when an earlier statement was put back.", "irrelevant_conduct": "The journeyman''s resignation; the supervisor''s staffing decision.", "stated_standard": null, "stated_standard_source_quote_or_location": null, "cross_context_map": null, "serving_eligible": false, "recurrence_eligible": true, "replacement_required": false, "name_clearance_status": "CLEARED", "name_clearance_basis": "Controlled role and entity labels only; no real person or organization is named.", "sensitivity_flag": null, "permitted_administration_variance": "Pronunciation only; accommodations affecting turn order or response window are recorded and set timing_not_comparable.", "unsupported_inferences": "Anything about the departed mentor or the relationship; that an apprentice should press harder; any observation of the loss of a mentor as felt.", "compatibility_class": "S2-SEVEN-BEAT", "setback_established": "In the pre-brief: \"no dedicated journeyman is available for six weeks.\"", "containment_actions": [{"id": "CA1", "text": "confirm what the apprentice regulations require for tomorrow''s panel work"}, {"id": "CA2", "text": "request a licensed subcontractor from the call-off arrangement for the install"}, {"id": "CA3", "text": "set out which of the six weeks of work under rotating supervisors needs a qualified supervisor"}, {"id": "CA4", "text": "record that tomorrow''s install cannot proceed unsupervised"}], "corrective_actions": [{"id": "CR1", "text": "request a licensed subcontractor from the call-off arrangement for the install"}, {"id": "CR2", "text": "set out which of the six weeks of work under rotating supervisors needs a qualified supervisor"}], "designated_facts": [{"id": "DF1", "text": "what the apprentice regulations require for panel work"}, {"id": "DF2", "text": "which trades the two named rotating supervisors hold"}, {"id": "DF3", "text": "what the call-off arrangement with the two subcontractors provides"}, {"id": "DF4", "text": "what work falls in the six weeks and which parts need a qualified supervisor"}], "available_supports": [{"id": "SU1", "text": "the site supervisor, in this session"}, {"id": "SU2", "text": "the two licensed subcontractors under the call-off arrangement"}, {"id": "SU3", "text": "the contractor''s apprenticeship coordinator"}], "standing_commitments": [{"id": "CM1", "text": "tomorrow''s client date for the panel install"}, {"id": "CM2", "text": "the apprentice supervision requirement"}, {"id": "CM3", "text": "the six weeks of work under rotating supervisors"}], "work_in_progress": [{"id": "WP1", "text": "the panel install"}, {"id": "WP2", "text": "the six weeks'' scheduled electrical work"}], "recurrence_measures": [{"id": "RM1", "text": "a named alternate supervising electrician recorded against the apprenticeship"}, {"id": "RM2", "text": "the call-off arrangement triggered automatically on a supervision gap"}, {"id": "RM3", "text": "scheduled work screened for supervision requirement at booking"}], "recurring_condition": null, "formal_record_state": null, "record_place": "The site log and the apprenticeship record.", "who_knows": "The site supervisor.", "decision_origin": "The journeyman''s resignation, external to the participant.", "account_test_point": "B6", "account_test_record": "The situation records that the rotating supervisors are a millwright and a pipefitter, neither qualified to supervise electrical work.", "list_note": null, "source_note": null, "situation_class_label": "Work that must continue with its people, tools or resources reduced", "observation_mode_label": "structured_live_session", "min_seconds": 480, "max_seconds": 900}, "source_identifier": "SRC-D8-S2-004", "stage_code": "S2", "source_version_hash": "64ca9ed50b1d392e7365151b6e07574ee53aa4443ddbe4d1c328e10b81a42c06", "serving_eligible": false, "verbatim": ""}'::jsonb from public.t3a_content_object where identifier = 'SRC-D8-S2-004' and family = 'source'::public.t3a_content_family;
  insert into public.t3a_content_object(identifier, family, title, dimension_id, current_operational_state) values ('SRC-D8-S2-005', 'source'::public.t3a_content_family, 'THE ALT TEXT THAT RAN FOR AN HOUR', 'D8', 'not_loaded'::public.t3a_operational_state);
  insert into public.t3a_d1_content_version(content_object_id, version_no, approval_status, operational_state, body) select content_object_id, 'v2.1', 'drafting', 'not_loaded'::public.t3a_operational_state, '{"stage": 2, "title": "THE ALT TEXT THAT RAN FOR AN HOUR", "source_digest": "0bf8d4803f693d9a823cfd22c5a3c3a821e2fe9c8ef14e8151ab335104d86908", "mentor_brief": "The mentor reads the scripted lines of the manager. The mentor states nothing beyond the script and forms no view of how the participant is taking the internal circulation. The mentor reads the scripted lines verbatim, reacts to nothing, and does not press, repeat or escalate, whatever the participant says or does not say. Nothing observed about the person is recordable: only what the participant states about the work.", "participant_pre_brief": "You are a social media coordinator. Yesterday you queued posts through the company''s content scheduling tool, which auto-generates alt text from image analysis. This morning the tool misidentified a product photo and published inaccurate alt text on a professional network. It reached about 2,400 accounts before it was caught at 9:15 AM. Screenshots are circulating in internal channels. What the record shows: the tool''s auto-generated alt text has never been reviewed before publication under the current routine; the post is down and the alt text corrected; a manual review step exists in the tool and is switched off; the day''s remaining six posts are queued with auto-generated alt text; and your manager has asked to see you now.", "script": [{"beat": "B1", "type": "SAY", "spoken": "I have seen the post and the screenshots. I will let you start.", "direction": null, "capture": []}, {"beat": "B2", "type": "PAUSE", "spoken": null, "direction": "Say nothing for ten to fifteen seconds. Do not prompt or fill the silence.", "capture": [{"set": "C1", "state": "open"}, {"set": "C1b", "state": "open"}, {"set": "C2", "state": "open"}, {"set": "C2b", "state": "open"}, {"set": "C3", "state": "open"}, {"set": "C3b", "state": "open"}, {"set": "C4", "state": "open"}, {"set": "C4b", "state": "open"}, {"set": "C5", "state": "open"}, {"set": "C5b", "state": "open"}, {"set": "C6", "state": "open"}, {"set": "C6b", "state": "open"}, {"set": "C7", "state": "open"}, {"set": "C7b", "state": "open"}, {"set": "C8", "state": "open"}]}, {"beat": "B3", "type": "ASK", "spoken": "What have you done since 9:15, and what do you know?", "direction": "Read once, verbatim.", "capture": [{"set": "C1", "state": "update"}, {"set": "C1b", "state": "update"}, {"set": "C2", "state": "update"}, {"set": "C2b", "state": "update"}]}, {"beat": "B4", "type": "ASK", "spoken": "What are you doing about the tool itself, and who are you going to?", "direction": "Read once, verbatim.", "capture": [{"set": "C3", "state": "update"}, {"set": "C3b", "state": "update"}, {"set": "C4", "state": "update"}, {"set": "C4b", "state": "update"}]}, {"beat": "B5", "type": "ASK", "spoken": "What still goes out today, what resumes and when, and what goes on the record?", "direction": "Read once, verbatim.", "capture": [{"set": "C5", "state": "update"}, {"set": "C5b", "state": "update"}, {"set": "C6", "state": "update"}, {"set": "C6b", "state": "update"}, {"set": "C7", "state": "update"}, {"set": "C7b", "state": "update"}, {"set": "C8", "state": "update"}]}, {"beat": "B6", "type": "ASK", "spoken": "Just so I have it right — you said the alt text has always been reviewed before it goes out. Has it?", "direction": "Read once, verbatim.", "capture": [{"set": "C9", "state": "open"}]}, {"beat": "B7", "type": "SAY", "spoken": "Thank you. That is the end of the session.", "direction": "End the session.", "capture": [{"set": "C1", "state": "final"}, {"set": "C2", "state": "final"}, {"set": "C3", "state": "final"}, {"set": "C4", "state": "final"}, {"set": "C5", "state": "final"}, {"set": "C6", "state": "final"}, {"set": "C7", "state": "final"}, {"set": "C8", "state": "final"}, {"set": "C9", "state": "final"}]}], "question_applicability": [{"question": "Q-D8-01", "state": "DIRECT", "basis": "The situation lists three containment actions"}, {"question": "Q-D8-01b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D8-02", "state": "DIRECT", "basis": "The situation designates four facts about the setback"}, {"question": "Q-D8-02b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D8-03", "state": "DIRECT", "basis": "The situation lists two actions on the condition behind the setback"}, {"question": "Q-D8-03b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D8-04", "state": "DIRECT", "basis": "The situation lists three supports"}, {"question": "Q-D8-04b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D8-05", "state": "DIRECT", "basis": "The situation lists two commitments in force"}, {"question": "Q-D8-05b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D8-06", "state": "DIRECT", "basis": "The situation lists two items of work under way"}, {"question": "Q-D8-06b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D8-07", "state": "DIRECT", "basis": "The situation lists three measures against the condition arising again"}, {"question": "Q-D8-07b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D8-08", "state": "DIRECT", "basis": "The situation names a place a record could be made"}, {"question": "Q-D8-09", "state": "DIRECT", "basis": "The account test puts an earlier statement back"}], "material_map": [{"Item": "CM1", "Item text": "the day''s six queued posts", "Where the participant meets it": "The pre-brief", "Quoted text": "the day''s remaining six posts are queued"}, {"Item": "CM2", "Item text": "the meeting the manager has asked for now", "Where the participant meets it": "The pre-brief", "Quoted text": "your manager has asked to see you now"}], "source_sheet": {"d8_situation_class": "SC-D8-1", "workplace_demand": "Speaking with a manager after a scheduling tool published inaccurate alt text the participant had queued.", "relevant_conduct": "Which containment action was stated; which facts about the setback were named; what action on the condition behind the setback was stated; which support was stated as one to go to; which commitments in force were named as still to be met; what work was named as continuing, and from when; what was stated about the condition arising again; whether a record was stated, and where; what was stated when an earlier statement was put back.", "irrelevant_conduct": "Whoever posted the screenshots; the tool vendor; the manager''s tone.", "stated_standard": null, "stated_standard_source_quote_or_location": null, "cross_context_map": null, "serving_eligible": false, "recurrence_eligible": true, "replacement_required": false, "name_clearance_status": "CLEARED", "name_clearance_basis": "Controlled role and entity labels only; no real person or organization is named.", "sensitivity_flag": null, "permitted_administration_variance": "Pronunciation only; accommodations affecting turn order or response window are recorded and set timing_not_comparable.", "unsupported_inferences": "That the participant was careless; any observation of embarrassment or its absence; anything about the internal circulation or how it landed.", "compatibility_class": "S2-SEVEN-BEAT", "setback_established": "In the pre-brief: \"the tool misidentified a product photo and published inaccurate alt text.\"", "containment_actions": [{"id": "CA1", "text": "hold the day''s six queued posts pending an alt-text check"}, {"id": "CA2", "text": "switch on the tool''s manual review step"}, {"id": "CA3", "text": "check the alt text already published on earlier posts from the same batch"}], "corrective_actions": [{"id": "CR1", "text": "switch on the tool''s manual review step"}, {"id": "CR2", "text": "set a review step into the publishing routine"}], "designated_facts": [{"id": "DF1", "text": "what the alt text said and what the image actually showed"}, {"id": "DF2", "text": "how far it reached and when it was taken down"}, {"id": "DF3", "text": "whether any other published post carries auto-generated alt text unchecked"}, {"id": "DF4", "text": "what the tool''s manual review step does and why it is off"}], "available_supports": [{"id": "SU1", "text": "the manager, in this session"}, {"id": "SU2", "text": "the tool administrator who controls the review setting"}, {"id": "SU3", "text": "the accessibility lead who owns alt-text standards"}], "standing_commitments": [{"id": "CM1", "text": "the day''s six queued posts"}, {"id": "CM2", "text": "the meeting the manager has asked for now"}], "work_in_progress": [{"id": "WP1", "text": "the day''s content queue"}, {"id": "WP2", "text": "the published back catalog carrying auto-generated alt text"}], "recurrence_measures": [{"id": "RM1", "text": "the manual review step switched on and left on"}, {"id": "RM2", "text": "auto-generated alt text reviewed before any publication"}, {"id": "RM3", "text": "a back-catalog audit of auto-generated alt text"}], "recurring_condition": "Auto-generated alt text has never been reviewed before publication under the current routine.", "formal_record_state": null, "record_place": "The content incident log.", "who_knows": "The manager and whoever is in the internal channel.", "decision_origin": null, "account_test_point": "B6", "account_test_record": "The situation records that the auto-generated alt text has never been reviewed before publication under the current routine.", "list_note": null, "source_note": null, "situation_class_label": "An error by the participant that has become known beyond them", "observation_mode_label": "structured_live_session", "min_seconds": 480, "max_seconds": 900}, "source_identifier": "SRC-D8-S2-005", "stage_code": "S2", "source_version_hash": "0bf8d4803f693d9a823cfd22c5a3c3a821e2fe9c8ef14e8151ab335104d86908", "serving_eligible": false, "verbatim": ""}'::jsonb from public.t3a_content_object where identifier = 'SRC-D8-S2-005' and family = 'source'::public.t3a_content_family;
  insert into public.t3a_content_object(identifier, family, title, dimension_id, current_operational_state) values ('SRC-D8-S2-006', 'source'::public.t3a_content_family, 'THE ROLE THAT WENT TO ANOTHER CANDIDATE', 'D8', 'not_loaded'::public.t3a_operational_state);
  insert into public.t3a_d1_content_version(content_object_id, version_no, approval_status, operational_state, body) select content_object_id, 'v2.1', 'drafting', 'not_loaded'::public.t3a_operational_state, '{"stage": 2, "title": "THE ROLE THAT WENT TO ANOTHER CANDIDATE", "source_digest": "4749dffb80ddecc9472976225557cbd816b41c7ad9271b966bb5251de459f0ef", "mentor_brief": "The mentor reads the scripted lines of the hiring director. The mentor forms no view of the participant''s response to the outcome and records nothing about it, including that they seemed untroubled. The mentor reads the scripted lines verbatim, reacts to nothing, and does not press, repeat or escalate, whatever the participant says or does not say. Nothing observed about the person is recordable: only what the participant states about the work.", "participant_pre_brief": "You are a senior financial analyst, five years with the firm, and you led due diligence on a $40 million acquisition last quarter. You applied for a new vice-president role overseeing analytics. The role went to a colleague who joined eighteen months ago and built the screening model the firm adopted. What the record shows: the role posting lists five requirements, of which model development is one and the participant''s record does not evidence it; the participant''s record evidences the other four; the firm funds one technical qualification per analyst per year and the participant''s is unclaimed; the quarterly reporting cycle the participant leads begins in four days; and the hiring director has offered a conversation this week.", "script": [{"beat": "B1", "type": "SAY", "spoken": "You applied for the analytics role and it has gone elsewhere. I said I would make time. I will let you start.", "direction": null, "capture": []}, {"beat": "B2", "type": "PAUSE", "spoken": null, "direction": "Say nothing for ten to fifteen seconds. Do not prompt or fill the silence.", "capture": [{"set": "C1", "state": "open"}, {"set": "C1b", "state": "open"}, {"set": "C2", "state": "open"}, {"set": "C2b", "state": "open"}, {"set": "C3", "state": "open"}, {"set": "C3b", "state": "open"}, {"set": "C4", "state": "open"}, {"set": "C4b", "state": "open"}, {"set": "C5", "state": "open"}, {"set": "C5b", "state": "open"}, {"set": "C6", "state": "open"}, {"set": "C6b", "state": "open"}, {"set": "C7", "state": "open"}, {"set": "C7b", "state": "open"}, {"set": "C8", "state": "open"}]}, {"beat": "B3", "type": "ASK", "spoken": "What have you done since the announcement, and what do you know?", "direction": "Read once, verbatim.", "capture": [{"set": "C1", "state": "update"}, {"set": "C1b", "state": "update"}, {"set": "C2", "state": "update"}, {"set": "C2b", "state": "update"}]}, {"beat": "B4", "type": "ASK", "spoken": "What are you doing about the gap the posting names, and who are you going to?", "direction": "Read once, verbatim.", "capture": [{"set": "C3", "state": "update"}, {"set": "C3b", "state": "update"}, {"set": "C4", "state": "update"}, {"set": "C4b", "state": "update"}]}, {"beat": "B5", "type": "ASK", "spoken": "What still gets met, what carries on and from when, and what goes on the record?", "direction": "Read once, verbatim.", "capture": [{"set": "C5", "state": "update"}, {"set": "C5b", "state": "update"}, {"set": "C6", "state": "update"}, {"set": "C6b", "state": "update"}, {"set": "C7", "state": "update"}, {"set": "C7b", "state": "update"}, {"set": "C8", "state": "update"}]}, {"beat": "B6", "type": "ASK", "spoken": "Just so I have it right — you said your record covers all five requirements. Does it?", "direction": "Read once, verbatim.", "capture": [{"set": "C9", "state": "open"}]}, {"beat": "B7", "type": "SAY", "spoken": "Thank you. That is the end of the session.", "direction": "End the session.", "capture": [{"set": "C1", "state": "final"}, {"set": "C2", "state": "final"}, {"set": "C3", "state": "final"}, {"set": "C4", "state": "final"}, {"set": "C5", "state": "final"}, {"set": "C6", "state": "final"}, 