{"id": "CA2", "text": "ask for model development work to be routed through you next cycle"}, {"id": "CA3", "text": "confirm what the quarterly cycle needs from you in four days"}], "corrective_actions": [{"id": "CR1", "text": "claim the funded technical qualification against the model development requirement"}, {"id": "CR2", "text": "ask for model development work to be routed through you next cycle"}], "designated_facts": [{"id": "DF1", "text": "what the five requirements are, in the posting''s terms"}, {"id": "DF2", "text": "which one the participant''s record does not evidence"}, {"id": "DF3", "text": "what the funded qualification covers and when it must be claimed"}, {"id": "DF4", "text": "what the quarterly reporting cycle requires and when it begins"}], "available_supports": [{"id": "SU1", "text": "the hiring director, in this session"}, {"id": "SU2", "text": "the funded technical qualification, unclaimed"}, {"id": "SU3", "text": "the analytics function, whose work the new role oversees"}], "standing_commitments": [{"id": "CM1", "text": "the quarterly reporting cycle beginning in four days"}, {"id": "CM2", "text": "the conversation the hiring director has offered this week"}], "work_in_progress": [{"id": "WP1", "text": "the quarterly reporting cycle"}, {"id": "WP2", "text": "the participant''s current workload"}], "recurrence_measures": [{"id": "RM1", "text": "the funded qualification claimed against a named requirement each year"}, {"id": "RM2", "text": "model development work sought and recorded before the next posting"}, {"id": "RM3", "text": "a standing record of requirements evidenced against the internal framework"}], "recurring_condition": null, "formal_record_state": "The role posting and the appointment announcement.", "record_place": "The participant''s development record.", "who_knows": "The hiring director and the open-plan office.", "decision_origin": "The hiring decision, above the participant.", "account_test_point": "B6", "account_test_record"