  insert into public.t3a_content_object(identifier, family, title, dimension_id, current_operational_state) values ('SRC-D8-S2-007', 'source'::public.t3a_content_family, 'THREE FAILURES IN FORTY-FIVE MINUTES', 'D8', 'not_loaded'::public.t3a_operational_state);
  insert into public.t3a_d1_content_version(content_object_id, version_no, approval_status, operational_state, body) select content_object_id, 'v2.1', 'drafting', 'not_loaded'::public.t3a_operational_state, '{"stage": 2, "title": "THREE FAILURES IN FORTY-FIVE MINUTES", "source_digest": "758d33e9a10b43ba3f49d54abf400e5d6f9216210714cbb076d7f49f5448cdf2", "mentor_brief": "The mentor reads the scripted lines of the plant manager. The mentor asks the scripted questions once each and forms no view of how the participant is handling three failures in succession. The mentor reads the scripted lines verbatim, reacts to nothing, and does not press, repeat or escalate, whatever the participant says or does not say. Nothing observed about the person is recordable: only what the participant states about the work.", "participant_pre_brief": "You are a production supervisor on a packaging line committed to 12,000 units this shift against a just-in-time delivery carrying a $25,000 shortfall penalty. At 10:30 the primary conveyor motor failed, a three-hour repair. The backup line runs at sixty percent. At 11:15 the backup labeling machine jammed. While it was being cleared, the automated quality inspection system began flagging every unit as defective; visual inspection shows the units are sound. What the record shows: the inspection system has flagged false positives twice in the past month, both after a line changeover; a manual inspection route is documented and runs at about forty percent of automated throughput; the motor repair is under way with a three-hour estimate; the delivery window closes at end of shift; and the plant manager is reachable.", "script": [{"beat": "B1", "type": "SAY", "spoken": "Three things have gone down this morning and the delivery window closes at end of shift. I will let you start.", "direction": null, "capture": []}, {"beat": "B2", "type": "PAUSE", "spoken": null, "direction": "Say nothing for ten to fifteen seconds. Do not prompt or fill the silenc