  insert into public.t3a_d1_content_version(content_object_id, version_no, approval_status, operational_state, body) select content_object_id, 'v2.1', 'drafting', 'not_loaded'::public.t3a_operational_state, '{"stage": 2, "title": "THE THREE VIOLATIONS AT THE BUSIEST LOCATION", "source_digest": "571093ef8efb1c458d71aa42aa841449240f5793e2260947b979772694f51920", "mentor_brief": "The mentor reads the scripted lines of the director. The mentor asks the scripted questions once each and forms no view of the participant''s response. The mentor reads the scripted lines verbatim, reacts to nothing, and does not press, repeat or escalate, whatever the participant says or does not say. Nothing observed about the person is recordable: only what the participant states about the work.", "participant_pre_brief": "You are regional operations manager for fourteen quick-service restaurants. A provincial health inspection at the busiest location found three violations: a cooler above safe temperature for six hours, expired product on the line, and incomplete cleaning logs. What the record shows: the automated temperature monitoring system flagged the deviation five hours before the inspection and the store manager dismissed the alert; the same alert type has been dismissed at four locations in the past two months; the inspection requires a written corrective response within fourteen days; the expired product was withdrawn during the inspection; the cleaning logs are complete at eleven of fourteen locations; and your director has asked for a position before the regional call on Friday.", "script": [{"beat": "B1", "type": "SAY", "spoken": "I have the inspection report. The regional call is Friday. I will let you start.", "direction": null, "capture": []}, {"beat": "B2", "type": "PAUSE", "spoken": null, "direction": "Say nothing for ten to fifteen seconds. Do not prompt or fill the silence.", "capture": [{"set": "C1", "state": "open"}, {"set": "C1b", "state": "open"}, {"set": "C2", "state": "open"}, {"set": "C2b", "state": "open"}, {"set": "C3", "state": "open"}, {"set": "C3b", "state": "open"}, {"set": "C4", "state": "open"}, {"set": "C4b", "state": "open"}, {"set": "C5", "state": "open"}, {"set": "C5b", "state": "open"}, {"set": "C6", "state": "open"}, {"set": "C6b", "state": "open"}, {"set": "C7", "state": "open"}, {"set": "C7b", "state": "open"}, {"set": "C8", "state": "open"}]}, {"beat": "B3", "type": "ASK", "spoken": "What have you done since the report, and what do you know?", "direction": "Read once, verbatim.", "capture": [{"set": "C1", "state": "update"}, {"set": "C1b", "state": "update"}, {"set": "C2", "state": "update"}, {"set": "C2b", "state": "update"}]}, {"beat": "B4", "type": "ASK", "spoken": "What are you doing about the alerts being dismissed, and who are you going to?", "direction": "Read once, verbatim.", "capture": [{"set": "C3", "state": "update"}, {"set": "C3b", "state": "update"}, {"set": "C4", "state": "update"}, {"set": "C4b", "state": "update"}]}, {"beat": "B5", "type": "ASK", "spoken": "What still gets met, what continues and from when, and what goes on the record?", "direction": "Read once, verbatim.", "capture": [{"set": "C5", "state": "update"}, {"set": "C5b", "state": "update"}, {"set": "C6", "state": "update"}, {"set": "C6b", "state": "update"}, {"set": "C7", "state": "update"}, {"set": "C7b", "state": "update"}, {"set": "C8", "state": "update"}]}, {"beat": "B6", "type": "ASK", "spoken": "Just so I have it right — you said the alert was dismissed at this one location. Was it?", "direction": "Read once, verbatim.", "capture": [{"set": "C9", "state": "open"}]}, {"beat": "B7", "type": "SAY", "spoken": "Thank you. That is the end of the session.", "direction": "End the session.", "capture": [{"set": "C1", "state": "final"}, {"set": "C2", "state": "final"}, {"set": "C3", "state": "final"}, {"set": "C4", "state": "final"}, {"set": "C5", "state": "final"}, {"set": "C6", "state": "final"}, {"set": "C7", "state": "final"}, {