  insert into public.t3a_content_object(identifier, family, title, dimension_id, current_operational_state) values ('SRC-D8-S3-001', 'source'::public.t3a_content_family, 'THREE HUNDRED AND FORTY FILES OVERNIGHT', 'D8', 'not_loaded'::public.t3a_operational_state);
  insert into public.t3a_d1_content_version(content_object_id, version_no, approval_status, operational_state, body) select content_object_id, 'v2.1', 'drafting', 'not_loaded'::public.t3a_operational_state, '{"stage": 3, "title": "THREE HUNDRED AND FORTY FILES OVERNIGHT", "source_digest": "22d3d0eb8d8254c37e2d09b422e3da1444df741b26879ecfdc7c554dd0982291", "brief_summary": "The participant reads the brief in the pack and submits the work the submission instructions name.", "participant_pack": [{"document": "D1", "title": "The brief", "text": "You are an operations manager at an asset management firm. At 06:45 Tuesday the security team reports that a service account with elevated privileges accessed 340 client agreement files between 01:15 and 03:40, matching no scheduled process. The account is disabled and logs are under review. The document system is the firm''s only store for client agreements, compliance filings and audit reports, and is now read-only pending review, so no filings can be made. What the record shows: two regulatory filings are due Thursday; the firm''s incident procedure requires assessment and report to the chief operating officer within four hours of detection; the service account''s privileges were widened in a change six weeks ago and three other service accounts carry the same widened profile; no client has been notified; and restoration has no stated time."}], "submission_instructions": "Produce what you would do first and what you would establish; what you would do about the condition and whose help you would seek; what still gets met, what resumes and from when; and what you would do about a recurrence and what would be recorded where. The work is submitted within 3 days.", "question_applicability": [{"question": "Q-D8-01", "state": "DIRECT", "basis": "The situation lists three containment actions"}, {"question": "Q-D8-01b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D8-02", "state": "DIRECT", "basis": "The situation designates four facts about the setback"}, {"question": "Q-D8-02b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D8-03", "state": "DIRECT", "basis": "The situation lists two actions on the condition behind the setback"}, {"question": "Q-D8-03b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D8-04", "state": "DIRECT", "basis": "The situation lists three supports"}, {"question": "Q-D8-04b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D8-05", "state": "DIRECT", "basis": "The situation lists three commitments in force"}, {"question": "Q-D8-05b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D8-06", "state": "DIRECT", "basis": "The situation lists two items of work under way"}, {"question": "Q-D8-06b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D8-07", "state": "DIRECT", "basis": "The situation lists three measures against the condition arising again"}, {"question": "Q-D8-07b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D8-08", "state": "DIRECT", "basis": "The situation names a place a record could be made"}, {"question": "Q-D8-09", "state": "NOT SERVED", "basis": "The asynchronous form puts no earlier statement back to the participant"}], "material_map": [{"Item": "CM1", "Item text": "the four-hour assessment to the chief operating officer", "Where the participant meets it": "Pack document D1", "Quoted text": "assessment and report to the chief operating officer within four hours"}, {"Item": "CM2", "Item text": "the two regulatory filings due Thursday", "Where the participant meets it": "Pack document D1", "Quoted text": "regulatory filings are due Thursday"}, {"Item": "CM3", "Item text": "the client agreements the document system holds", "Where the participant meets it": "Pack document D1", "Quoted text": "the firm''s only store for client agreements"}], "source_sheet": {"d8_situation_class": "SC-D8-3", "workplace_demand": "Preparing the position after a privileged service account reached client files overnight and the document system went read-only.", "relevant_conduct": "Which containment action was stated; which facts about the setback were named; what action on the condition behind the setback was stated; which support was stated as one to go to; which commitments in force were named as still to be met; what work was named as continuing, and from when; what was stated about the condition arising again; whether a record was stated, and where.", "irrelevant_conduct": "The security team''s handling; the attacker.", "stated_standard": null, "stated_standard_source_quote_or_location": null, "cross_context_map": null, "serving_eligible": false, "recurrence_eligible": true, "replacement_required": false, "name_clearance_status": "CLEARED", "name_clearance_basis": "Controlled role and entity labels only; no real person or organization is named.", "sensitivity_flag": null, "permitted_administration_variance": "Accommodations are recorded with the submission; the window may be extended as an accommodation and the extension is recorded.", "unsupported_inferences": "That the access was malicious; who made the privilege change, which is a D2 matter; any observation of how the breach was taken.", "compatibility_class": "S3-ASYNC-SUBMISSION", "setback_established": "In the brief: \"a service account with elevated privileges accessed 340 client agreement files.\"", "containment_actions": [{"id": "CA1", "text": "confirm the disabled account and the scope of what was reached"}, {"id": "CA2", "text": "review the three other service accounts carrying the widened profile"}, {"id": "CA3", "text": "route the two Thursday filings through a verified source outside the system"}], "corrective_actions": [{"id": "CR1", "text": "review the three other service accounts carrying the widened profile"}, {"id": "CR2", "text": "reverse the six-week-old privilege change"}], "designated_facts": [{"id": "DF1", "text": "what was accessed, when, and by which account"}, {"id": "DF2", "text": "what the privilege change six weeks ago altered"}, {"id": "DF3", "text": "which other accounts carry the same widened profile"}, {"id": "DF4", "text": "what the incident procedure requires and by when"}], "available_supports": [{"id": "SU1", "text": "the security team holding the logs"}, {"id": "SU2", "text": "the chief operating officer, the four-hour recipient"}, {"id": "SU3", "text": "the change record holding the six-week-old privilege change"}], "standing_commitments": [{"id": "CM1", "text": "the four-hour assessment to the chief operating officer"}, {"id": "CM2", "text": "the two regulatory filings due Thursday"}, {"id": "CM3", "text": "the client agreements the document system holds"}], "work_in_progress": [{"id": "WP1", "text": "the two Thursday filings"}, {"id": "WP2", "text": "the firm''s ordinary document operations"}], "recurrence_measures": [{"id": "RM1", "text": "the widened privilege profile reversed across all four accounts"}, {"id": "RM2", "text": "service account privilege changes reviewed before they take effect"}, {"id": "RM3", "text": "out-of-hours access on service accounts alerted in real time"}], "recurring_condition": "Three other service accounts carry the same widened profile from the same change.", "formal_record_state": "The security team''s report.", "record_place": "The firm''s incident register.", "who_knows": "The security team.", "decision_origin": null, "list_note": null, "source_note": "Shared Stage 3 submission with SRC-D3-S3-004; one served instance, a separate observation record in each dimension.", "situation_class_label": "A failure or violation formally recorded against work the participant holds", "observation_mode_label": "work_sample", "ai_use": "AI_USE_DECLARATION_REQUIRED", "submission_window_days": 3}, "source_identifier": "SRC-D8-S3-001", "stage_code": "S3", "source_version_hash": "22d3d0eb8d8254c37e2d09b422e3da1444df741b26879ecfdc7c554dd0982291", "serving_eligible": false, "verbatim": ""}'::jsonb from public.t3a_content_object where identifier = 'SRC-D8-S3-001' and family = 'source'::public.t3a_content_family;
  insert into public.t3a_content_object(identifier, family, title, dimension_id, current_operational_state) values ('SRC-D8-S3-002', 'source'::public.t3a_content_family, 'THE WEEKEND OUTAGE AND THE CONFLICTING ACCOUNTS', 'D8', 'not_loaded'::public.t3a_operational_state);
  insert into public.t3a_d1_content_version(content_object_id, version_no, approval_status, operational_state, body) select content_object_id, 'v2.1', 'drafting', 'not_loaded'::public.t3a_operational_state, '{"stage": 3, "title": "THE WEEKEND OUTAGE AND THE CONFLICTING ACCOUNTS", "source_digest": "4e066d55d55307cb0324b21fd514d29fec8db548e057c40b1513567ad767ca5d", "brief_summary": "The participant reads the brief in the pack and submits the work the submission instructions name.", "participant_pack": [{"document": "D1", "title": "The brief", "text": "You hold the client relationship. Over the weekend the client organization experienced a system outage during their peak dispatch window; assignments failed to populate for about ninety minutes. Their operations director emailed your vice-president late Sunday, copying you. Your vice-president forwarded it with one line: own this, and show me the plan before anything goes to the client. What the record shows: the engineering thread holds conflicting accounts — a third-party rate limit and warning signs seen two weeks earlier, neither confirmed; no postmortem has started; the client''s deadline is Wednesday at 5:00 PM; the same third-party rate limit was implicated in a shorter outage six weeks ago and that incident has no closed postmortem either; and your account team has two further deliverables due to the same client this week."}], "submission_instructions": "Produce what you would do first and what you would establish; what you would do about the condition and whose help you would seek; what still gets met, what resumes and from when; and what you would do about a recurrence and what would be recorded where. The work is submitted within 3 days.", "question_applicability": [{"question": "Q-D8-01", "state": "DIRECT", "basis": "The situation lists three containment actions"}, {"question": "Q-D8-01b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D8-02", "state": "DIRECT", "basis": "The situation designates four facts about the setback"}, {"question": "Q-D8-02b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D8-03", "state": "DIRECT", "basis": "The situation lists two actions on the condition behind the setback"}, {"question": "Q-D8-03b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D8-04", "state": "DIRECT", "basis": "The situation lists three supports"}, {"question": "Q-D8-04b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D8-05", "state": "DIRECT", "basis": "The situation lists three commitments in force"}, {"question": "Q-D8-05b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D8-06", "state": "DIRECT", "basis": "The situation lists two items of work under way"}, {"question": "Q-D8-06b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D8-07", "state": "DIRECT", "basis": "The situation lists three measures against the condition arising again"}, {"question": "Q-D8-07b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D8-08", "state": "DIRECT", "basis": "The situation names a place a record could be made"}, {"question": "Q-D8-09", "state": "NOT SERVED", "basis": "The asynchronous form puts no earlier statement back to the participant"}], "material_map": [{"Item": "CM1", "Item text": "the client''s Wednesday 5:00 PM deadline", "Where the participant meets it": "Pack document D1", "Quoted text": "the client''s deadline is Wednesday at 5:00 PM"}, {"Item": "CM2", "Item text": "the two further deliverables due this week", "Where the participant meets it": "Pack document D1", "Quoted text": "your account team has two further deliverables due to the same client this week"}, {"Item": "CM3", "Item text": "the plan the vice-president asked to see before anything goes to the client", "Where the participant meets it": "Pack document D1", "Quoted text": "show me the plan before anything goes to the client"}], "source_sheet": {"d8_situation_class": "SC-D8-1", "workplace_demand": "Preparing the response after a client outage drew conflicting engineering accounts.", "relevant_conduct": "Which containment action was stated; which facts about the setback were named; what action on the condition behind the setback was stated; which support was stated as one to go to; which commitments in force were named as still to be met; what work was named as continuing, and from when; what was stated about the condition arising again; whether a record was stated, and where.", "irrelevant_conduct": "The engineers'' conduct; the client''s tone; the vice-president''s instruction.", "stated_standard": null, "stated_standard_source_quote_or_location": null, "cross_context_map": null, "serving_eligible": false, "recurrence_eligible": true, "replacement_required": false, "name_clearance_status": "CLEARED", "name_clearance_basis": "Controlled role and entity labels only; no real person or organization is named.", "sensitivity_flag": null, "permitted_administration_variance": "Accommodations are recorded with the submission; the window may be extended as an accommodation and the extension is recorded.", "unsupported_inferences": "That either engineering account is true; who is answerable, which is a D2 matter; what the client was told, which is a D4 matter.", "compatibility_class": "S3-ASYNC-SUBMISSION", "setback_established": "In the brief: \"assignments failed to populate for about ninety minutes.\"", "containment_actions": [{"id": "CA1", "text": "open the postmortem and set its scope"}, {"id": "CA2", "text": "establish which of the two engineering accounts the logs support"}, {"id": "CA3", "text": "confirm the two further deliverables this week can be met"}], "corrective_actions": [{"id": "CR1", "text": "open the postmortem and set its scope"}, {"id": "CR2", "text": "link this outage to the six-week-old incident and its open postmortem"}], "designated_facts": [{"id": "DF1", "text": "the outage window and what failed within it"}, {"id": "DF2", "text": "what each of the two engineering accounts asserts, and that neither is confirmed"}, {"id": "DF3", "text": "what the six-week-old incident involved and whether its postmortem closed"}, {"id": "DF4", "text": "what the client''s Wednesday deadline requires"}], "available_supports": [{"id": "SU1", "text": "the vice-president, who has asked to see the plan"}, {"id": "SU2", "text": "the engineering lead and the junior engineer holding the two accounts"}, {"id": "SU3", "text": "the six-week-old incident record"}], "standing_commitments": [{"id": "CM1", "text": "the client''s Wednesday 5:00 PM deadline"}, {"id": "CM2", "text": "the two further deliverables due this week"}, {"id": "CM3", "text": "the plan the vice-president asked to see before anything goes to the client"}], "work_in_progress": [{"id": "WP1", "text": "the two further client deliverables"}, {"id": "WP2", "text": "the postmortem"}], "recurrence_measures": [{"id": "RM1", "text": "both incidents taken into one postmortem with a closure date"}, {"id": "RM2", "text": "the third-party rate limit monitored with an alert threshold"}, {"id": "RM3", "text": "a postmortem closure requirement before a client incident is considered ended"}], "recurring_condition": "The same third-party rate limit implicated six weeks earlier with no closed postmortem.", "formal_record_state": "The client''s email and the six-week-old incident record.", "record_place": "The incident and postmortem register.", "who_knows": "The vice-president, the client''s operations director, the engineering thread.", "decision_origin": null, "list_note": null, "source_note": "Shared Stage 3 submission with SRC-D2-S3-001, SRC-D4-S3-001; one served instance, a separate observation record in each dimension.", "situation_class_label": "An error by the participant that has become known beyond them", "observation_mode_label": "work_sample", "ai_use": "AI_USE_DECLARATION_REQUIRED", "submission_window_days": 3}, "source_identifier": "SRC-D8-S3-002", "stage_code": "S3", "source_version_hash": "4e066d55d55307cb0324b21fd514d29fec8db548e057c40b1513567ad767ca5d", "serving_eligible": false, "verbatim": ""}'::jsonb from public.t3a_content_object where identifier = 'SRC-D8-S3-002' and family = 'source'::public.t3a_content_family;
  insert into public.t3a_content_object(identifier, family, title, dimension_id, current_operational_state) values ('SRC-D8-S3-003', 'source'::public.t3a_content_family, 'TWELVE HUNDRED UNITS WITH THE WRONG DOSAGE LABEL', 'D8', 'not_loaded'::public.t3a_operational_state);
  insert into public.t3a_d1_content_version(content_object_id, version_no, approval_status, operational_state, body) select content_object_id, 'v2.1', 'drafting', 'not_loaded'::public.t3a_operational_state, '{"stage": 3, "title": "TWELVE HUNDRED UNITS WITH THE WRONG DOSAGE LABEL", "source_digest": "b8e8fdb10f28703afccbce126452d287ee80b614e52309565994314ff591d8af", "brief_summary": "The participant reads the brief in the pack and submits the work the submission instructions name.", "participant_pack": [{"document": "D1", "title": "The brief", "text": "You are quality assurance lead at a manufacturer of over-the-counter health products supplying pharmacy chains across three provinces, processing about 2,000 batches a month under good manufacturing practice. A production line operator has flagged that a batch of 1,200 units of an electrolyte supplement was packaged with labels reading \"Take 2 tablets daily\" instead of \"Take 1\". What the record shows: 300 units of the batch have already shipped to two pharmacy chains; the label artwork was approved four weeks ago and the approval record shows a single reviewer where the procedure requires two; the same single-reviewer pattern appears on nine of the last forty artwork approvals; a deviation investigation must be opened within 24 hours of identification; the batch release decision is yours; and the regulator requires notification of any distributed labeling error within three business days."}], "submission_instructions": "Produce what you would do first and what you would establish; what you would do about the condition and whose help you would seek; what still gets met, what resumes and from when; and what you would do about a recurrence and what would be recorded where. The work is submitted within 3 days.", "question_applicability": [{"question": "Q-D8-01", "state": "DIRECT", "basis": "The situation lists four containment actions"}, {"question": "Q-D8-01b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D8-02", "state": "DIRECT", "basis": "The situation designates four facts about the setback"}, {"question": "Q-D8-02b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D8-03", "state": "DIRECT", "basis": "The situation lists two actions on the condition behind the setback"}, {"question": "Q-D8-03b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D8-04", "state": "DIRECT", "basis": "The situation lists three supports"}, {"question": "Q-D8-04b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D8-05", "state": "DIRECT", "basis": "The situation lists three commitments in force"}, {"question": "Q-D8-05b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D8-06", "state": "DIRECT", "basis": "The situation lists two items of work under way"}, {"question": "Q-D8-06b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D8-07", "state": "DIRECT", "basis": "The situation lists three measures against the condition arising again"}, {"question": "Q-D8-07b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D8-08", "state": "DIRECT", "basis": "The situation names a place a record could be made"}, {"question": "Q-D8-09", "state": "NOT SERVED", "basis": "The asynchronous form puts no earlier statement back to the participant"}], "material_map": [{"Item": "CM1", "Item text": "the deviation investigation within 24 hours", "Where the participant meets it": "Pack document D1", "Quoted text": "a deviation investigation must be opened within 24 hours"}, {"Item": "CM2", "Item text": "the regulator notification within three business days", "Where the participant meets it": "Pack document D1", "Quoted text": "notification of any distributed labeling error within three business days"}, {"Item": "CM3", "Item text": "the monthly batch throughput the plant carries", "Where the participant meets it": "Pack document D1", "Quoted text": "processing about 2,000 batches a month"}], "source_sheet": {"d8_situation_class": "SC-D8-3", "workplace_demand": "Preparing the response after a batch was packaged with the wrong dosage label.", "relevant_conduct": "Which containment action was stated; which facts about the setback were named; what action on the condition behind the setback was stated; which support was stated as one to go to; which commitments in force were named as still to be met; what work was named as continuing, and from when; what was stated about the condition arising again; whether a record was stated, and where.", "irrelevant_conduct": "The single reviewer; the operator; patient risk framing.", "stated_standard": null, "stated_standard_source_quote_or_location": null, "cross_context_map": null, "serving_eligible": false, "recurrence_eligible": true, "replacement_required": false, "name_clearance_status": "CLEARED", "name_clearance_basis": "Controlled role and entity labels only; no real person or organization is named.", "sensitivity_flag": null, "permitted_administration_variance": "Accommodations are recorded with the submission; the window may be extended as an accommodation and the extension is recorded.", "unsupported_inferences": "Who approved the artwork, which is a D2 matter; that a dosage error indicates anything about the participant; any observation of how the flag was taken.", "compatibility_class": "S3-ASYNC-SUBMISSION", "setback_established": "In the brief: \"a batch of 1,200 units... was packaged with labels showing the wrong dosage instructions.\"", "containment_actions": [{"id": "CA1", "text": "place the remaining 900 units on hold"}, {"id": "CA2", "text": "trace and recover the 300 shipped units through the two chains"}, {"id": "CA3", "text": "suspend artwork approvals carrying a single reviewer pending correction"}, {"id": "CA4", "text": "open the deviation investigation within the 24 hours"}], "corrective_actions": [{"id": "CR1", "text": "suspend artwork approvals carrying a single reviewer pending correction"}, {"id": "CR2", "text": "open the deviation investigation within the 24 hours"}], "designated_facts": [{"id": "DF1", "text": "what the label says against what it should say"}, {"id": "DF2", "text": "how many units shipped and to whom"}, {"id": "DF3", "text": "what the artwork approval record shows against what the procedure requires"}, {"id": "DF4", "text": "how many of the last forty approvals carry the same single-reviewer pattern"}], "available_supports": [{"id": "SU1", "text": "the director of quality and regulatory affairs"}, {"id": "SU2", "text": "the two pharmacy chains'' recall contacts"}, {"id": "SU3", "text": "the production floor team who flagged it"}], "standing_commitments": [{"id": "CM1", "text": "the deviation investigation within 24 hours"}, {"id": "CM2", "text": "the regulator notification within three business days"}, {"id": "CM3", "text": "the monthly batch throughput the plant carries"}], "work_in_progress": [{"id": "WP1", "text": "the remaining 900 units"}, {"id": "WP2", "text": "the month''s other batches awaiting release"}], "recurrence_measures": [{"id": "RM1", "text": "the two-reviewer requirement enforced in the approval system"}, {"id": "RM2", "text": "the nine single-reviewer approvals re-reviewed"}, {"id": "RM3", "text": "a label verification step at first packaging run"}], "recurring_condition": "The single-reviewer pattern on nine of the last forty approvals.", "formal_record_state": "The operator''s flag; no deviation record yet opened.", "record_place": "The deviation investigation record and the artwork approval log.", "who_knows": "The production floor team.", "decision_origin": null, "list_note": null, "source_note": "Shared Stage 3 submission with SRC-D2-S3-005; one served instance, a separate observation record in each dimension.", "situation_class_label": "A failure or violation formally recorded against work the participant holds", "observation_mode_label": "work_sample", "ai_use": "AI_USE_DECLARATION_REQUIRED", "submission_window_days": 3}, "source_identifier": "SRC-D8-S3-003", "stage_code": "S3", "source_version_hash": "b8e8fdb10f28703afccbce126452d287ee80b614e52309565994314ff591d8af", "serving_eligible": false, "verbatim": ""}'::jsonb from public.t3a_content_object where identifier = 'SRC-D8-S3-003' and family = 'source'::public.t3a_content_family;
  insert into public.t3a_content_object(identifier, family, title, dimension_id, current_operational_state) values ('SRC-D8-S3-004', 'source'::public.t3a_content_family, 'THE RENEWAL THAT BECAME A TENDER', 'D8', 'not_loaded'::public.t3a_operational_state);
  insert into public.t3a_d1_content_version(content_object_id, version_no, approval_status, operational_state, body) select content_object_id, 'v2.1', 'drafting', 'not_loaded'::public.t3a_operational_state, '{"stage": 3, "title": "THE RENEWAL THAT BECAME A TENDER", "source_digest": "0bb1a2ae7eeab56cb5b30236041452943eafe9ef2250389de233beb24cef3932", "brief_summary": "The participant reads the brief in the pack and submits the work the submission instructions name.", "participant_pack": [{"document": "D1", "title": "The brief", "text": "You manage an account portfolio. Your largest account by contract value, a regional healthcare group and a client of three years, has told you this morning that their board wants to benchmark costs and will issue a tender rather than renew directly. The current two-year agreement expires in six weeks. What the record shows: you submitted a renewal proposal three weeks ago with a five percent increase reflecting expanded scope; your vice-president approved it and has told the leadership team the renewal is closed; the tender timetable has not been issued; the agreement''s notice provisions have not been reviewed against a tender process; two other accounts in your portfolio renew within the same quarter and neither has a tender-readiness position; and your portfolio review is in nine days."}], "submission_instructions": "Produce what you would do first and what you would establish; what you would do about the condition and whose help you would seek; what still gets met, what resumes and from when; and what you would do about a recurrence and what would be recorded where. The work is submitted within 3 days.", "question_applicability": [{"question": "Q-D8-01", "state": "DIRECT", "basis": "The situation lists three containment actions"}, {"question": "Q-D8-01b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D8-02", "state": "DIRECT", "basis": "The situation designates four facts about the setback"}, {"question": "Q-D8-02b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D8-03", "state": "DIRECT", "basis": "The situation lists two actions on the condition behind the setback"}, {"question": "Q-D8-03b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D8-04", "state": "DIRECT", "basis": "The situation lists three supports"}, {"question": "Q-D8-04b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D8-05", "state": "DIRECT", "basis": "The situation lists three commitments in force"}, {"question": "Q-D8-05b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D8-06", "state": "DIRECT", "basis": "The situation lists two items of work under way"}, {"question": "Q-D8-06b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D8-07", "state": "DIRECT", "basis": "The situation lists three measures against the condition arising again"}, {"question": "Q-D8-07b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D8-08", "state": "DIRECT", "basis": "The situation names a place a record could be made"}, {"question": "Q-D8-09", "state": "NOT SERVED", "basis": "The asynchronous form puts no earlier statement back to the participant"}], "material_map": [{"Item": "CM1", "Item text": "the agreement expiring in six weeks", "Where the participant meets it": "Pack document D1", "Quoted text": "agreement expires in six weeks"}, {"Item": "CM2", "Item text": "the portfolio review in nine days", "Where the participant meets it": "Pack document D1", "Quoted text": "your portfolio review is in nine days"}, {"Item": "CM3", "Item text": "the two other accounts renewing this quarter", "Where the participant meets it": "Pack document D1", "Quoted text": "other accounts in your portfolio renew within the same quarter"}], "source_sheet": {"d8_situation_class": "SC-D8-2", "workplace_demand": "Preparing the approach after the largest account moved from direct renewal to a tender.", "relevant_conduct": "Which containment action was stated; which facts about the setback were named; what action on the condition behind the setback was stated; which support was stated as one to go to; which commitments in force were named as still to be met; what work was named as continuing, and from when; what was stated about the condition arising again; whether a record was stated, and where.", "irrelevant_conduct": "The client''s board; the tender''s likely outcome; what the leadership team was told, which is a D4 matter.", "stated_standard": null, "stated_standard_source_quote_or_location": null, "cross_context_map": null, "serving_eligible": false, "recurrence_eligible": true, "replacement_required": false, "name_clearance_status": "CLEARED", "name_clearance_basis": "Controlled role and entity labels only; no real person or organization is named.", "sensitivity_flag": null, "permitted_administration_variance": "Accommodations are recorded with the submission; the window may be extended as an accommodation and the extension is recorded.", "unsupported_inferences": "That the five percent increase caused the tender; that the vice-president was wrong to close it; any observation of how the news was taken.", "compatibility_class": "S3-ASYNC-SUBMISSION", "setback_established": "In the brief: \"they will issue a tender rather than renew directly.\"", "containment_actions": [{"id": "CA1", "text": "read the agreement''s notice provisions against a tender process"}, {"id": "CA2", "text": "correct the leadership team''s position that the renewal is closed"}, {"id": "CA3", "text": "establish what the tender will require and when"}], "corrective_actions": [{"id": "CR1", "text": "build a tender-readiness position for the two other renewing accounts"}, {"id": "CR2", "text": "establish what the tender will require and when"}], "designated_facts": [{"id": "DF1", "text": "what the client has stated about the tender, in its own terms"}, {"id": "DF2", "text": "what the agreement''s notice provisions provide"}, {"id": "DF3", "text": "what the leadership team has been told"}, {"id": "DF4", "text": "which other accounts renew in the same quarter"}], "available_supports": [{"id": "SU1", "text": "the vice-president who approved the renewal proposal"}, {"id": "SU2", "text": "the contracts function holding the agreement"}, {"id": "SU3", "text": "the bid team who would build a tender response"}], "standing_commitments": [{"id": "CM1", "text": "the agreement expiring in six weeks"}, {"id": "CM2", "text": "the portfolio review in nine days"}, {"id": "CM3", "text": "the two other accounts renewing this quarter"}], "work_in_progress": [{"id": "WP1", "text": "the renewal, now a tender"}, {"id": "WP2", "text": "the two other renewing accounts"}], "recurrence_measures": [{"id": "RM1", "text": "a tender-readiness position held on every account above a stated value"}, {"id": "RM2", "text": "renewal status communicated only after written client confirmation"}, {"id": "RM3", "text": "notice provisions reviewed at each renewal cycle opening"}], "recurring_condition": null, "formal_record_state": "The submitted renewal proposal and its internal approval.", "record_place": "The account record and the portfolio review papers.", "who_knows": "The vice-president and the leadership team.", "decision_origin": "The client''s board decision, external.", "list_note": null, "source_note": "Shared Stage 3 submission with SRC-D4-S3-007; one served instance, a separate observation record in each dimension.", "situation_class_label": "Sustained work ended or withdrawn by a decision outside the participant''s control", "observation_mode_label": "work_sample", "ai_use": "AI_USE_DECLARATION_REQUIRED", "submission_window_days": 3}, "source_identifier": "SRC-D8-S3-004", "stag