  insert into public.t3a_content_object(identifier, family, title, dimension_id, current_operational_state) values ('SRC-D8-S3-005', 'source'::public.t3a_content_family, 'FORTY PERCENT LESS, TWO PROGRAMS RUNNING', 'D8', 'not_loaded'::public.t3a_operational_state);
  insert into public.t3a_d1_content_version(content_object_id, version_no, approval_status, operational_state, body) select content_object_id, 'v2.1', 'drafting', 'not_loaded'::public.t3a_operational_state, '{"stage": 3, "title": "FORTY PERCENT LESS, TWO PROGRAMS RUNNING", "source_digest": "71c1dc97a63cf183b8ae76b556c16618d5528a2065d98c201b610c59dedf0199", "brief_summary": "The participant reads the brief in the pack and submits the work the submission instructions name.", "participant_pack": [{"document": "D1", "title": "The brief", "text": "You hold program responsibility at a community organization. A provincial grant funding thirty percent of the employment pathways program and fifteen percent of the youth integration program has been cut by forty percent from next quarter. The reduction is confirmed and cannot be reversed. What the record shows: the employment pathways manager needs a decision by Friday between canceling the spring workshop series serving sixty clients or reducing staff from four to two and a half full-time equivalents; the afterschool mentoring program loses its paid supervisor and volunteers cannot operate without one; the reserve fund holds about forty thousand dollars, board-earmarked and requiring written justification; the workshop series has a seventy-eight percent completion rate and is a reporting metric under a municipal funding agreement; and the same provincial grant was reduced by fifteen percent two years ago with no change made to the funding mix since."}], "submission_instructions": "Produce what you would do first and what you would establish; what you would do about the condition and whose help you would seek; what still gets met, what continues and from when; and what you would do about a recurrence and what would be recorded where. The work is submitted within 3 days.", "question_applicability": [{"question": "Q-D8-01", "state": "DIRECT", "basis": "The situation lists three containment actions"}, {"question": "Q-D8-01b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D8-02", "state": "DIRECT", "basis": "The situation designates four facts about the setback"}, {"question": "Q-D8-02b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D8-03", "state": "DIRECT", "basis": "The situation lists two actions on the condition behind the setback"}, {"question": "Q-D8-03b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D8-04", "state": "DIRECT", "basis": "The situation lists three supports"}, {"question": "Q-D8-04b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D8-05", "state": "DIRECT", "basis": "The situation lists three commitments in force"}, {"question": "Q-D8-05b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D8-06", "state": "DIRECT", "basis": "The situation lists two items of work under way"}, {"question": "Q-D8-06b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D8-07", "state": "DIRECT", "basis": "The situation lists three measures against the condition arising again"}, {"question": "Q-D8-07b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D8-08", "state": "DIRECT", "basis": "The situation names a place a record could be made"}, {"question": "Q-D8-09", "state": "NOT SERVED", "basis": "The asynchronous form puts no earlier statement back to the participant"}], "material_map": [{"Item": "CM1", "Item text": "the Friday decision to the employment pathways manager", "Where the participant meets it": "Pack document D1", "Quoted text": "employment pathways manager needs a decision by Friday"}, {"Item": "CM2", "Item text": "the municipal reporting metric on the workshop series", "Where the participant meets it": "Pack document D1", "Quoted text": "is a reporting metric under a municipal funding agreement"}, {"Item": "CM3", "Item text": "the afterschool mentoring program''s operation", "Where the participant meets it": "Pack document D1", "Quoted text": "the afterschool mentoring program loses its paid supervisor"}], "source_sheet": {"d8_situation_class": "SC-D8-6", "workplace_demand": "Preparing how two programs continue after a confirmed forty percent cut to the grant that funds them.", "relevant_conduct": "Which containment action was stated; which facts about the setback were named; what action on the condition behind the setback was stated; which support was stated as one to go to; which commitments in force were named as still to be met; what work was named as continuing, and from when; what was stated about the condition arising again; whether a record was stated, and where.", "irrelevant_conduct": "The funder''s decision; what is communicated to affected groups, which is a D4 matter; how the allocation is sequenced, which is a D3 matter.", "stated_standard": null, "stated_standard_source_quote_or_location": null, "cross_context_map": null, "serving_eligible": false, "recurrence_eligible": true, "replacement_required": false, "name_clearance_status": "CLEARED", "name_clearance_basis": "Controlled role and entity labels only; no real person or organization is named.", "sensitivity_flag": null, "permitted_administration_variance": "Accommodations are recorded with the submission; the window may be extended as an accommodation and the extension is recorded.", "unsupported_inferences": "That either program should be preferred; that the participant should have diversified sooner; any observation of how the cut was taken; nothing about the clients or young people served is observed or recorded.", "compatibility_class": "S3-ASYNC-SUBMISSION", "setback_established": "In the brief: \"has been cut by forty percent from next quarter.\"", "containment_actions": [{"id": "CA1", "text": "set the two programs'' committed obligations against the reduced funding"}, {"id": "CA2", "text": "prepare the written justification for a reserve draw"}, {"id": "CA3", "text": "give the employment pathways manager the Friday decision"}], "corrective_actions": [{"id": "CR1", "text": "prepare the written justification for a reserve draw"}, {"id": "CR2", "text": "rebuild the funding mix so no single grant carries this share"}], "designated_facts": [{"id": "DF1", "text": "what the reduction removes from each program"}, {"id": "DF2", "text": "what the municipal funding agreement requires of the workshop series"}, {"id": "DF3", "text": "what the reserve fund permits and what justification it requires"}, {"id": "DF4", "text": "that the same grant was reduced two years ago and the funding mix was not changed"}], "available_supports": [{"id": "SU1", "text": "the board, who hold the reserve fund"}, {"id": "SU2", "text": "the two program managers"}, {"id": "SU3", "text": "the municipal funder under the reporting agreement"}], "standing_commitments": [{"id": "CM1", "text": "the Friday decision to the employment pathways manager"}, {"id": "CM2", "text": "the municipal reporting metric on the workshop series"}, {"id": "CM3", "text": "the afterschool mentoring program''s operation"}], "work_in_progress": [{"id": "WP1", "text": "the spring workshop series"}, {"id": "WP2", "text": "the afterschool mentoring program"}], "recurrence_measures": [{"id": "RM1", "text": "a ceiling on any single grant''s share of operating budget"}, {"id": "RM2", "text": "a standing reserve-draw justification kept current"}, {"id": "RM3", "text": "funding mix reviewed at each grant renewal rather than at reduction"}], "recurring_condition": "The same grant reduced two years ago with no change to the funding mix since.", "formal_record_state": "The grant reduction notice.", "record_place": "The board papers and the funding register.", "who_knows": "The board and the two program managers.", "decision_origin": "The provincial funder, external.", "list_note": null, "source_note": "Shared Stage 3 submission with SRC-D2-S3-008, SRC-D3-S3-007; one served instance, a separate observation record in each dimension.", "situation_class_label": "Work that must continue with its people, tools or resources reduced", "observation_mode_label": "work_sample", "ai_use": "AI_USE_DECLARATION_REQUIRED", "submission_window_days": 3}, "source_identifier": "SRC-D8-S3-005", "stage_code": "S3", "source_version_hash": "71c1dc97a63cf183b8ae76b556c16618d5528a2065d98c201b610c59dedf0199", "serving_eligible": false, "verbatim": ""}'::jsonb from public.t3a_content_object where identifier = 'SRC-D8-S3-005' and family = 'source'::public.t3a_content_family;
  insert into public.t3a_content_object(identifier, family, title, dimension_id, current_operational_state) values ('SRC-D8-S3-006', 'source'::public.t3a_content_family, 'THE COLLISION AT TWO FIFTEEN', 'D8', 'not_loaded'::public.t3a_operational_state);
  insert into public.t3a_d1_content_version(content_object_id, version_no, approval_status, operational_state, body) select content_object_id, 'v2.1', 'drafting', 'not_loaded'::public.t3a_operational_state, '{"stage": 3, "title": "THE COLLISION AT TWO FIFTEEN", "source_digest": "c52485eae49e66b348a34dc96c5c12b9d851a92f3fe13d94fa7ce3616679d8a7", "brief_summary": "The participant reads the brief in the pack and submits the work the submission instructions name.", "participant_pack": [{"document": "D1", "title": "The brief", "text": "You are night shift supervisor at a distribution center processing outbound orders for eighteen retail clients, supervising twenty-two staff on the 10:00 PM to 6:00 AM shift, which handles about forty percent of daily volume. At 02:15 a forklift clipped a racking unit while reversing with a loaded pallet. The lower rack beam is damaged and the aisle is out of service. What the record shows: the operator holds two years'' experience and a clean record; the damaged beam requires engineering sign-off before the aisle reopens and the day-shift engineer arrives at 7:00 AM; the aisle holds stock for four of the eighteen clients and two have morning dispatch windows; three near-miss reports involving reversing with loaded pallets have been filed in the past quarter and none has a completed action; the shift''s accuracy rate is 99.2 percent against a 98.5 percent target; and the warehouse operations manager works days and is reachable from 7:00 AM."}], "submission_instructions": "Produce what you would do first and what you would establish; what you would do about the condition and whose help you would seek; what still gets met, what resumes and from when; and what you would do about a recurrence and what would be recorded where. The work is submitted within 3 days.", "question_applicability": [{"question": "Q-D8-01", "state": "DIRECT", "basis": "The situation lists three containment actions"}, {"question": "Q-D8-01b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D8-02", "state": "DIRECT", "basis": "The situation designates four facts about the setback"}, {"question": "Q-D8-02b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D8-03", "state": "DIRECT", "basis": "The situation lists two actions on the condition behind the setback"}, {"question": "Q-D8-03b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D8-04", "state": "DIRECT", "basis": "The situation lists three supports"}, {"question": "Q-D8-04b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D8-05", "state": "DIRECT", "basis": "The situation lists three commitments in force"}, {"question": "Q-D8-05b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D8-06", "state": "DIRECT", "basis": "The situation lists two items of work under way"}, {"question": "Q-D8-06b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D8-07", "state": "DIRECT", "basis": "The situation lists three measures against the condition arising again"}, {"question": "Q-D8-07b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D8-08", "state": "DIRECT", "basis": "The situation names a place a record could be made"}, {"question": "Q-D8-09", "state": "NOT SERVED", "basis": "The asynchronous form puts no earlier statement back to the participant"}], "material_map": [{"Item": "CM1", "Item text": "the two morning dispatch windows", "Where the participant meets it": "Pack document D1", "Quoted text": "two have morning dispatch windows"}, {"Item": "CM2", "Item text": "the shift''s forty percent of daily volume", "Where the participant meets it": "Pack document D1", "Quoted text": "handles about forty percent of daily volume"}, {"Item": "CM3", "Item text": "the accuracy rate against the company target", "Where the participant meets it": "Pack document D1", "Quoted text": "accuracy rate is 99.2 percent against a 98.5 percent target"}], "source_sheet": {"d8_situation_class": "SC-D8-6", "workplace_demand": "Preparing how the night shift continues after a forklift collision damaged a racking unit.", "relevant_conduct": "Which containment action was stated; which facts about the setback were named; what action on the condition behind the setback was stated; which support was stated as one to go to; which commitments in force were named as still to be met; what work was named as continuing, and from when; what was stated about the condition arising again; whether a record was stated, and where.", "irrelevant_conduct": "The operator''s conduct; who is answerable, which is a D2 matter.", "stated_standard": null, "stated_standard_source_quote_or_location": null, "cross_context_map": null, "serving_eligible": false, "recurrence_eligible": true, "replacement_required": false, "name_clearance_status": "CLEARED", "name_clearance_basis": "Controlled role and entity labels only; no real person or organization is named.", "sensitivity_flag": null, "permitted_administration_variance": "Accommodations are recorded with the submission; the window may be extended as an accommodation and the extension is recorded.", "unsupported_inferences": "That the participant should have actioned the near-misses sooner; any observation of how the collision was taken; anything about the forklift operator, whose record is clean and who is not a subject of this observation.", "compatibility_class": "S3-ASYNC-SUBMISSION", "setback_established": "In the brief: \"a forklift clipped a racking unit... The lower rack beam is damaged and the aisle is out of service.\"", "containment_actions": [{"id": "CA1", "text": "close and mark the aisle and confirm nothing else is load-bearing on the beam"}, {"id": "CA2", "text": "move the two morning-window clients'' stock from the closed aisle"}, {"id": "CA3", "text": "suspend reversing with loaded pallets pending an action on the near-misses"}], "corrective_actions": [{"id": "CR1", "text": "attach the three open near-miss reports to tonight''s incident"}, {"id": "CR2", "text": "suspend reversing with loaded pallets pending an action on the near-misses"}], "designated_facts": [{"id": "DF1", "text": "what the beam damage is and what sign-off reopening requires"}, {"id": "DF2", "text": "which clients'' stock sits in the closed aisle and which have morning windows"}, {"id": "DF3", "text": "how many near-miss reports involve the same manoeuvre and whether any action closed"}, {"id": "DF4", "text": "when engineering and the operations manager become reachable"}], "available_supports": [{"id": "SU1", "text": "the day-shift engineer from 7:00 AM"}, {"id": "SU2", "text": "the warehouse operations manager from 7:00 AM"}, {"id": "SU3", "text": "the twenty-two staff on shift"}], "standing_commitments": [{"id": "CM1", "text": "the two morning dispatch windows"}, {"id": "CM2", "text": "the shift''s forty percent of daily volume"}, {"id": "CM3", "text": "the accuracy rate against the company target"}], "work_in_progress": [{"id": "WP1", "text": "the night shift''s outbound orders"}, {"id": "WP2", "text": "the four clients'' stock in the closed aisle"}], "recurrence_measures": [{"id": "RM1", "text": "a completed action on the three open near-miss reports"}, {"id": "RM2", "text": "reversing with loaded pallets restricted or spotter-assisted"}, {"id": "RM3", "text": "near-miss reports carrying a closure requirement before the next quarter"}], "recurring_condition": "Three near-miss reports on the same manoeuvre in a quarter, none actioned.", "formal_record_state": "Three open near-miss reports; tonight''s incident not yet recorded.", "record_place": "The shift incident log and the safety action register.", "who_knows": "The shift.", "decision_origin": null, "list_note": null, "source_note": "Shared Stage 3 submission with SRC-D5-S3-006; one served instance, a separate observation record in each dimension.", "situation_class_label": "Work that must continue with its people, tools or resources reduced", "observation_mode_label": "work_sample", "ai_use": "AI_USE_DECLARATION_REQUIRED", "submission_window_days": 3}, "source_identifier": "SRC-D8-S3-006", "stage_code": "S3", "source_version_hash": "c52485eae49e66b348a34dc96c5c12b9d851a92f3fe13d94fa7ce3616679d8a7", "serving_eligible": false, "verbatim": ""}'::jsonb from public.t3a_content_object where identifier = 'SRC-D8-S3-006' and family = 'source'::public.t3a_content_family;
  insert into public.t3a_content_object(identifier, family, title, dimension_id, current_operational_state) values ('SRC-D8-S3-007', 'source'::public.t3a_content_family, 'THE VENUE CLOSED FOR FOUR WEEKS', 'D8', 'not_loaded'::public.t3a_operational_state);
  insert into public.t3a_d1_content_version(content_object_id, version_no, approval_status, operational_state, body) select content_object_id, 'v2.1', 'drafting', 'not_loaded'::public.t3a_operational_state, '{"stage": 3, "title": "THE VENUE CLOSED FOR FOUR WEEKS", "source_digest": "670524a42f4c545e763d5ffdc9593bb846e49f935f3520640d59b552670d06e9", "brief_summary": "The participant reads the brief in the pack and submits the work the submission instructions name.", "participant_pack": [{"document": "D1", "title": "The brief", "text": "You are an event coordinator. A half-day summit for eighty executives of a financial services client is three weeks away. On Monday the venue reported a water main break: the main hall is damaged and the venue closes for at least four weeks. They waive the cancellation fee and offer help finding an alternative but have no comparable space. What the record shows: the date is fixed to the client''s board calendar; the format sold was four elements for eighty attendees; a venue failure caused a relocation on a different event eleven months ago and no alternate-venue list was built afterwards; the firm''s contracts with speakers and caterers carry fourteen-day cancellation terms; and eighty attendees hold confirmed registrations."}], "submission_instructions": "Produce what you would do first and what you would establish; what you would do about the condition and whose help you would seek; what still gets met, what continues and from when; and what you would do about a recurrence and what would be recorded where. The work is submitted within 3 days.", "question_applicability": [{"question": "Q-D8-01", "state": "DIRECT", "basis": "The situation lists three containment actions"}, {"question": "Q-D8-01b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D8-02", "state": "DIRECT", "basis": "The situation designates four facts about the setback"}, {"question": "Q-D8-02b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D8-03", "state": "DIRECT", "basis": "The situation lists two actions on the condition behind the setback"}, {"question": "Q-D8-03b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D8-04", "state": "DIRECT", "basis": "The situation lists three supports"}, {"question": "Q-D8-04b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D8-05", "state": "DIRECT", "basis": "The situation lists three commitments in force"}, {"question": "Q-D8-05b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D8-06", "state": "DIRECT", "basis": "The situation lists two items of work under way"}, {"question": "Q-D8-06b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D8-07", "state": "DIRECT", "basis": "The situation lists three measures against the condition arising again"}, {"question": "Q-D8-07b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D8-08", "state": "DIRECT", "basis": "The situation names a place a record could be made"}, {"question": "Q-D8-09", "state": "NOT SERVED", "basis": "The asynchronous form puts no earlier statement back to the participant"}], "material_map": [{"Item": "CM1", "Item text": "the fixed date on the client''s board calendar", "Where the participant meets it": "Pack document D1", "Quoted text": "date is fixed to the client''s board calendar"}, {"Item": "CM2", "Item text": "the four-element format for eighty attendees", "Where the participant meets it": "Pack document D1", "Quoted text": "format sold was four elements for eighty attendees"}, {"Item": "CM3", "Item text": "the speaker and caterer contracts'' fourteen-day terms", "Where the participant meets it": "Pack document D1", "Quoted text": "speakers and caterers carry fourteen-day cancellation terms"}], "source_sheet": {"d8_situation_class": "SC-D8-4", "workplace_demand": "Preparing how a client summit goes ahead after the venue closed for four weeks.", "relevant_conduct": "Which containment action was stated; which facts about the setback were named; what action on the condition behind the setback was stated; which support was stated as one to go to; which commitments in force were named as still to be met; what work was named as continuing, and from when; what was stated about the condition arising again; whether a record was stated, and where.", "irrelevant_conduct": "The venue''s failure; what each element becomes, which is a D3 matter; what each party is told, which is a D4 matter.", "stated_standard": null, "stated_standard_source_quote_or_location": null, "cross_context_map": null, "serving_eligible": false, "recurrence_eligible": true, "replacement_required": false, "name_clearance_status": "CLEARED", "name_clearance_basis": "Controlled role and entity labels only; no real person or organization is named.", "sensitivity_flag": null, "permitted_administration_variance": "Accommodations are recorded with the submission; the window may be extended as an accommodation and the extension is recorded.", "unsupported_inferences": "That the summit should be postponed; that the participant should have held a list; any observation of how the closure was taken.", "compatibility_class": "S3-ASYNC-SUBMISSION", "setback_established": "In the brief: \"the venue closes for at least four weeks.\"", "containment_actions": [{"id": "CA1", "text": "establish which contracts can be held and which must be released inside fourteen days"}, {"id": "CA2", "text": "take the venue''s offered help to reach spaces not publicly listed"}, {"id": "CA3", "text": "confirm what the four elements require of any alternative space"}], "corrective_actions": [{"id": "CR1", "text": "build the alternate-venue list that was not built eleven months ago"}, {"id": "CR2", "text": "confirm what the four elements require of any alternative space"}], "designated_facts": [{"id": "DF1", "text": "what the venue closure covers and for how long"}, {"id": "DF2", "text": "what the speaker and caterer contracts require inside fourteen days"}, {"id": "DF3", "text": "that a venue failure caused a relocation eleven months ago and no list followed"}, {"id": "DF4", "text": "what the four sold elements require of a space"}], "available_supports": [{"id": "SU1", "text": "the venue''s offered assistance"}, {"id": "SU2", "text": "the firm''s contracts administrator"}, {"id": "SU3", "text": "the client''s event sponsor"}], "standing_commitments": [{"id": "CM1", "text": "the fixed date on the client''s board calendar"}, {"id": "CM2", "text": "the four-element format for eighty attendees"}, {"id": "CM3", "text": "the speaker and caterer contracts'' fourteen-day terms"}], "work_in_progress": [{"id": "WP1", "text": "the summit itself"}, {"id": "WP2", "text": "the speaker and supplier engagements"}], "recurrence_measures": [{"id": "RM1", "text": "a standing alternate-venue list held against every booked event"}, {"id": "RM2", "text": "supplier contracts written with venue-failure release terms"}, {"id": "RM3", "text": "a venue contingency confirmed at booking rather than at failure"}], "recurring_condition": "A venue failure eleven months ago with no alternate-venue list built afterwards.", "formal_record_state": "The venue''s closure notice and fee waiver.", "record_place": "The event file and the supplier contract register.", "who_knows": "The venue and the firm.", "decision_origin": null, "list_note": null, "source_note": "Shared Stage 3 submission with SRC-D3-S3-010, SRC-D4-S3-010; one served instance, a separate observation record in each dimension.", "situation_class_label": "A condition that has disrupted the work before, producing the same disruption again", "observation_mode_label": "work_sample", "ai_use": "AI_USE_DECLARATION_REQUIRED", "submission_window_days": 3}, "source_identifier": "SRC-D8-S3-007", "stage_code": "S3", "source_version_hash": "670524a42f4c545e763d5ffdc9593bb846e49f935f3520640d59b552670d06e9", "serving_eligible": false, "verbatim": ""}'::jsonb from public.t3a_content_object where identifier = 'SRC-D8-S3-007' and family = 'source'::public.t3a_content_family;
  insert into public.t3a_content_object(identifier, family, title, dimension_id, current_operational_state) values ('SRC-D8-S3-008', 'source'::public.t3a_content_family, 'FOURTEEN OF TWENTY-FOUR FINISHED', 'D8', 'not_loaded'::public.t3a_operational_state);
  insert into public.t3a_d1_content_version(content_object_id, version_no, approval_status, operational_state, body) select content_object_id, 'v2.1', 'drafting', 'not_loaded'::public.t3a_operational_state, '{"stage": 3, "title": "FOURTEEN OF TWENTY-FOUR FINISHED", "source_digest": "08a30b3b47518af01b55caa4bbb6456d351e3cf0bef96cdc91d2b5f7f16fb5f1", "brief_summary": "The participant reads the brief in the pack and submits the work the submission instructions name.", "participant_pack": [{"document": "D1", "title": "The brief", "text": "You are training coordinator at a non-profit delivering professional development to early-career educators across four centers, serving about 500 participants annually. A twelve-week leadership program launched four months ago has just completed its first cohort. What the record shows: fourteen of twenty-four participants completed, a forty-two percent dropout; participant satisfaction averaged below the organization''s threshold; the program was the director''s flagship initiative, presented to the board with dedicated funding and a personally recruited first cohort; the second cohort opens recruitment in five weeks with twenty-eight places advertised; the organization''s three other programs have run at eight to twelve percent dropout for two years; exit responses were collected from six of the ten who left; and the board reviews program outcomes in seven weeks."}], "submission_instructions": "Produce what you would do first and what you would establish; what you would do about the condition and whose help you would seek; what still gets met, what continues and from when; and what you would do about a recurrence and what would be recorded where. The work is submitted within 3 days.", "question_applicability": [{"question": "Q-D8-01", "state": "DIRECT", "basis": "The situation lists four containment actions"}, {"question": "Q-D8-01b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D8-02", "state": "DIRECT", "basis": "The situation designates four facts about the setback"}, {"question": "Q-D8-02b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D8-03", "state": "DIRECT", "basis": "The situation lists two actions on the condition behind the setback"}, {"question": "Q-D8-03b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D8-04", "state": "DIRECT", "basis": "The situation lists three supports"}, {"question": "Q-D8-04b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D8-05", "state": "DIRECT", "basis": "The situation lists three commitments in force"}, {"question": "Q-D8-05b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D8-06", "state": "DIRECT", "basis": "The situation lists two items of work under way"}, {"question": "Q-D8-06b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D8-07", "state": "DIRECT", "basis": "The situation lists three measures against the condition arising again"}, {"question": "Q-D8-07b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D8-08", "state": "DIRECT", "basis": "The situation names a place a record could be made"}, {"question": "Q-D8-09", "state": "NOT SERVED", "basis": "The asynchronous form puts no earlier statement back to the participant"}], "material_map": [{"Item": "CM1", "Item text": "the second cohort''s advertised twenty-eight places", "Where the participant meets it": "Pack document D1", "Quoted text": "the second cohort opens recruitment in five weeks with twenty-eight places advertised"}, {"Item": "CM2", "Item text": "the board outcome review in seven weeks", "Where the participant meets it": "Pack document D1", "Quoted text": "the board reviews program outcomes in seven weeks"}, {"Item": "CM3", "Item text": "the organization''s work with about 500 participants a year", "Where the participant meets it": "Pack document D1", "Quoted text": "serving about 500 participants annually"}], "source_sheet": {"d8_situation_class": "SC-D8-4", "workplace_demand": "Preparing the position after a new program''s first cohort finished with fourteen of twenty-four participants.", "relevant_conduct": "Which containment action was stated; which facts about the setback were named; what action on the condition behind the setback was stated; which support was stated as one to go to; which commitments in force were named as still to be met; what work was named as continuing, and from when; what was stated about the condition arising again; whether a record was stated, and where.", "irrelevant_conduct": "The participants who left; the director''s investment in the program; whether the program is good.", "stated_standard": null, "stated_standard_source_quote_or_location": null, "cross_context_map": null, "serving_eligible": false, "recurrence_eligible": true, "replacement_required": false, "name_clearance_status": "CLEARED", "name_clearance_basis": "Controlled role and entity labels only; no real person or organization is named.", "sensitivity_flag": null, "permitted_administration_variance": "Accommodations are recorded with the submission; the window may be extended as an accommodation and the extension is recorded.", "unsupported_inferences": "That the director''s ownership should shape the response; any observation of how the result was taken; anything about the ten participants who left, their reasons or their circumstances.", "compatibility_class": "S3-ASYNC-SUBMISSION", "setback_established": "In the brief: \"only fourteen of twenty-four participants completed.\"", "containment_actions": [{"id": "CA1", "text": "set the dropout and satisfaction figures against the other three programs"}, {"id": "CA2", "text": "reach the four who left and gave no exit response"}, {"id": "CA3", "text": "hold the second cohort''s recruitment until the first cohort''s figures are understood"}, {"id": "CA4", "text": "prepare the outcome position for the board in seven weeks"}], "corrective_actions": [{"id": "CR1", "text": "reach the four who left and gave no exit response"}, {"id": "CR2", "text": "hold the second cohort''s recruitment until the first cohort''s figures are understood"}], "designated_facts": [{"id": "DF1", "text": "the completion and satisfaction figures for this cohort"}, {"id": "DF2", "text": "the same figures for the organization''s three other programs over two years"}, {"id": "DF3", "text": "what the six exit responses say and which four are missing"}, {"id": "DF4", "text": "what the second cohort''s recruitment opens and when"}], "available_supports": [{"id": "SU1", "text": "the director of programs, whose initiative it is"}, {"id": "SU2", "text": "the four centers'' coordinators"}, {"id": "SU3", "text": "the six exit responses already collected"}], "standing_commitments": [{"id": "CM1", "text": "the second cohort''s advertised twenty-eight places"}, {"id": "CM2", "text": "the board outcome review in seven weeks"}, {"id": "CM3", "text": "the organization''s work with about 500 participants a year"}], "work_in_progress": [{"id": "WP1", "text": "the second cohort''s recruitment"}, {"id": "WP2", "text": "the organization''s other three programs"}], "recurrence_measures": [{"id": "RM1", "text": "a mid-program completion checkpoint on every cohort"}, {"id": "RM2", "text": "exit responses sought from every participant who leaves"}, {"id": "RM3", "text": "a dropout threshold that pauses the next cohort''s recruitment"}], "recurring_condition": "The other three programs run at eight to twelve percent for two years; this one at forty-two.", "formal_record_state": "The cohort completion and satisfaction data.", "record_place": "The program outcome record and the board papers.", "who_knows": "The director and the board.", "decision_origin": null, "list_note": null, "source_note": null, "situation_class_label": "A condition that has disrupted the work before, producing the same disruption again", "observation_mode_label": "work_sample", "ai_use": "AI_USE_DECLARATION_REQUIRED", "submission_window_days": 3}, "source_identifier": "SRC-D8-S3-008", "stage_code": "S3", "source_version_hash": "08a30b3b47518af01b55caa4bbb6456d351e3cf0bef96cdc91d2b5f7f16fb5f1", "serving_eligible": false, "verbatim": ""}'::jsonb from public.t3a_content_object where identifier = 'SRC-D8-S3-008' and family = 'source'::public.t3a_content_family;
  insert into public.t3a_content_object(identifier, family, title, dimension_id, current_operational_state) values ('SRC-D8-S4-001', 'source'::public.t3a_content_family, 'SIXTY THOUSAND RECORDS, CONFIRMED', 'D8', 'not_loaded'::public.t3a_operational_state);
  insert into public.t3a_d1_content_version(content_object_id, version_no, approval_status, operational_state, body) select content_object_id, 'v2.1', 'drafting', 'not_loaded'::public.t3a_operational_state, '{"stage": 4, "title": "SIXTY THOUSAND RECORDS, CONFIRMED", "source_digest": "f0a25b6fca7b6bfb16ee3c8727a5c2a8fb7ae9f74f0d4b19cfb0ecafa017418a", "mentor_brief": "The facilitator facilitates the session and observes the observed participant only. At B1 the facilitator states the speaking order aloud: the three co-participants, then the observed participant. During the B2 round the facilitator does not look at, gesture towards or address the observed participant. The facilitator reads the scripted text verbatim, reacts to nothing, and does not press, repeat or escalate, whatever the observed participant says or does not say. The facilitator records only what was said about the work: nothing about any person in the room is recordable, including the absence of a reaction. The co-participants are role players; nothing they say is recorded, and nothing they say designates an action, a fact, a support, a commitment, an item of work or a measure.", "participant_pre_brief": "You are on the operations team of a healthcare technology company managing electronic health records for fourteen regional hospitals. At 07:42 the security team confirmed an unauthorized third party accessed a database holding records for about 60,000 individuals. The breach is confirmed, not suspected. What the record shows: regulatory notification is required within 72 hours of confirmation; the access route was an unpatched interface component flagged in an internal scan nine weeks ago with the remediation ticket still open; two other interface components carry the same unpatched version; the fourteen hospitals'' service continues unaffected; and the chief executive has asked for a position by noon.", "script": [{"beat": "B1", "type": "SAY", "spoken": "The breach is confirmed. I will go round in this order — security, legal, client services, then operations. Two minutes each.", "direction": null, "capture": []}, {"beat": "B2", "type": "ROUND", "spoken": "Over to you, in the order I gave.", "direction": "Invite the three co-participants in the stated order. Do not address the observed participant.", "capture": [{"set": "C1", "state": "open"}, {"set": "C1b", "state": "open"}, {"set": "C2", "state": "open"}, {"set": "C2b", "state": "open"}, {"set": "C3", "state": "open"}, {"set": "C3b", "state": "open"}, {"set": "C4", "state": "open"}, {"set": "C4b", "state": "open"}, {"set": "C5", "state": "open"}, {"set": "C5b", "state": "open"}, {"set": "C6", "state": "open"}, {"set": "C6b", "state": "open"}, {"set": "C7", "state": "open"}, {"set": "C7b", "state": "open"}, {"set": "C8", "state": "open"}]}, {"beat": "B3", "type": "ASK", "spoken": "What has been done since 07:42, and what do we know?", "direction": "Read once, verbatim.", "capture": [{"set": "C1", "state": "update"}, {"set": "C1b", "state": "update"}, {"set": "C2", "state": "update"}, {"set": "C2b", "state": "update"}]}, {"beat": "B4", "type": "ASK", "spoken": "What are we doing about the route in, and who are we going to?", "direction": "Read once, verbatim.", "capture": [{"set": "C3", "state": "update"}, {"set": "C3b", "state": "update"}, {"set": "C4", "state": "update"}, {"set": "C4b", "state": "update"}]}, {"beat": "B5", "type": "ASK", "spoken": "What still gets met, what continues and from when, what stops this recurring, and what goes on the record?", "direction": "Read once, verbatim.", "capture": [{"set": "C5", "state": "update"}, {"set": "C5b", "state": "update"}, {"set": "C6", "state": "update"}, {"set": "C6b", "state": "update"}, {"set": "C7", "state": "update"}, {"set": "C7b", "state": "update"}, {"set": "C8", "state": "update"}]}, {"beat": "B6", "type": "ASK", "spoken": "Just so the position is right — you said the scan finding was closed. Was it?", "direction": "Read once, verbatim.", "capture": [{"set": "C9", "state": "open"}]}, {"beat": "B7", "type": "SAY", "spoken": "Thank you all.", "direction": "End the session.", "capture": [{"set": "C1", "state": "final"}, {"set": "C2", "state": "final"}, {"set": "C3", "state": "final"}, {"set": "C4", "state": "final"}, {"set": "C5", "state": "final"}, {"set": "C6", "state": "final"}, {"set": "C7", "state": "final"}, {"set": "C8", "state": "final"}, {"set": "C9", "state": "final"}]}], "co_participant_positions": [{"Co-participant": "CP-1", "Position stated at the round": "As security, state the confirmation time and that the access route is identified."}, {"Co-participant": "CP-2", "Position stated at the round": "As legal, state the 72-hour notification requirement."}, {"Co-participant": "CP-3", "Position stated at the round": "As client services, state that the fourteen hospitals'' service is unaffected."}], "impact_assessment": [{"Part": "1. Shared material", "Finding": "Only the scripted situation is placed before the group, and it names no real organization", "Controls": "IA-01 shown in one shared window holding only the shared material"}, {"Part": "2. Identity", "Finding": "The observed participant is the authenticated participant; the three co-participants are role players", "Controls": "IA-02 platform account authentication; role players are never observed"}, {"Part": "3. Recording", "Finding": "Nothing is recorded", "Controls": "IA-03 no media persists"}, {"Part": "4. Correction", "Finding": "A correction reaches only the observed participant''s record", "Controls": "IA-04 a correction reaches only the observed participant''s record"}, {"Part": "5. Withdrawal", "Finding": "Withdrawal removes the participant''s determinations from composition only", "Controls": "IA-05 withdrawal excludes from composition; history retained"}, {"Part": "6. Group composition", "Finding": "One observed participant, three role players and one facilitator", "Controls": "IA-06 composition record and confidentiality undertaking from each role player"}, {"Part": "7. Accommodation", "Finding": "An accommodation is settled before composition and never changes the observation during the session", "Controls": "IA-07 settled before composition"}], "impact_result": "Completed", "question_applicability": [{"question": "Q-D8-01", "state": "DIRECT", "basis": "The situation lists four containment actions"}, {"question": "Q-D8-01b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D8-02", "state": "DIRECT", "basis": "The situation designates four facts about the setback"}, {"question": "Q-D8-02b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D8-03", "state": "DIRECT", "basis": "The situation lists two actions on the condition behind the setback"}, {"question": "Q-D8-03b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D8-04", "state": "DIRECT", "basis": "The situation lists three supports"}, {"question": "Q-D8-04b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D8-05", "state": "DIRECT", "basis": "The situation lists three commitments in force"}, {"question": "Q-D8-05b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D8-06", "state": "DIRECT", "basis": "The situation lists two items of work under way"}, {"question": "Q-D8-06b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D8-07", "state": "DIRECT", "basis": "The situation lists three measures against the condition arising again"}, {"question": "Q-D8-07b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D8-08", "state": "DIRECT", "basis": "The situation names a place a record could be made"}, {"question": "Q-D8-09", "state": "DIRECT", "basis": "The account test puts an earlier statement back"}], "material_map": [{"Item": "CM1", "Item text": "the 72-hour regulatory notification", "Where the participant meets it": "The pre-brief", "Quoted text": "regulatory notification is required within 72 hours"}, {"Item": "CM2", "Item text": "the fourteen hospitals'' continuing service", "Where the participant meets it": "The pre-brief", "Quoted text": "fourteen hospitals'' service continues"}, {"Item": "CM3", "Item text": "the position to the chief executive by noon", "Where the participant meets it": "The pre-brief", "Quoted text": "chief executive has asked for a position by noon"}], "source_sheet": {"d8_situation_class": "SC-D8-3", "workplace_demand": "Giving the operations position in a group round after a confirmed breach of a health records database.", "relevant_conduct": "Which containment action was stated; which facts about the setback were named; what action on the condition behind the setback was stated; which support was stated as one to go to; which commitments in force were named as still to be met; what work was named as continuing, and from when; what was stated about the condition arising again; whether a record was stated, and where; what was stated when an earlier statement was put back.", "irrelevant_conduct": "The co-participants'' statements; the attacker; the 60,000 individuals.", "stated_standard": null, "stated_standard_source_quote_or_location": null, "cross_context_map": null, "serving_eligible": false, "recurrence_eligible": true, "replacement_required": false, "name_clearance_status": "CLEARED", "name_clearance_basis": "Controlled role and entity labels only; no real person or organization is named.", "sensitivity_flag": null, "permitted_administration_variance": "Pronunciation only; accommodations affecting turn order or response window are recorded and set timing_not_comparable.", "unsupported_inferences": "Who left the ticket open, which is a D2 matter; any observation of the room''s state; any comparison of what the observed participant said at B3 with B6 to infer whether they held up.", "compatibility_class": "S4-GROUP-ROUND", "setback_established": "In the pre-brief: \"an unauthorized third party accessed a database holding records for about 60,000 individuals.\"", "containment_actions": [{"id": "CA1", "text": "close the access route on the affected component"}, {"id": "CA2", "text": "patch the two other components carrying the same version"}, {"id": "CA3", "text": "start the 72-hour regulatory notification clock and its content"}, {"id": "CA4", "text": "establish the scope of records reached"}], "corrective_actions": [{"id": "CR1", "text": "close the access route on the affected component"}, {"id": "CR2", "text": "patch the two other components carrying the same version"}], "designated_facts": [{"id": "DF1", "text": "what was accessed and when, and that confirmation was at 07:42"}, {"id": "DF2", "text": "what the nine-week-old scan flagged and that its ticket is open"}, {"id": "DF3", "text": "which other components carry the same unpatched version"}, {"id": "DF4", "text": "what the 72-hour notification requires"}], "available_supports": [{"id": "SU1", "text": "the security team holding the confirmation"}, {"id": "SU2", "text": "legal, holding the notification requirement"}, {"id": "SU3", "text": "the chief executive, expecting a position by noon"}], "standing_commitments": [{"id": "CM1", "text": "the 72-hour regulatory notification"}, {"id": "CM2", "text": "the fourteen hospitals'' continuing service"}, {"id": "CM3", "text": "the position to the chief executive by noon"}], "work_in_progress": [{"id": "WP1", "text": "the fourteen hospitals'' record service"}, {"id": "WP2", "text": "the open remediation ticket from the scan"}], "recurrence_measures": [{"id": "RM1", "text": "the three components patched to a current version"}, {"id": "RM2", "text": "scan findings carrying a closure deadline"}, {"id": "RM3", "text": "open remediation tickets escalated past a stated age"}], "recurring_condition": "A scan finding nine weeks old with the ticket still open and two further components on the same version.", "formal_record_state": "The security confirmation and the open scan ticket.", "record_place": "The incident register and the remediation tracker.", "who_knows": "Security, legal, client services and the chief executive.", "decision_origin": null, "account_test_point": "B6", "account_test_record": "The situation records that the remediation ticket from the scan is still open.", "list_note": null, "source_note": null, "situation_class_label": "A failure or violation formally recorded against work the participant holds", "observation_mode_label": "group_session", "min_seconds": 900, "max_seconds": 1500}, "source_identifier": "SRC-D8-S4-001", "stage_code": "S4", "source_version_hash": "f0a25b6fca7b6bfb16ee3c8727a5c2a8fb7ae9f74f0d4b19cfb0ecafa017418a", "serving_eligible": false, "verbatim": ""}'::jsonb from public.t3a_content_object where identifier = 'SRC-D8-S4-001' and family = 'source'::public.t3a_content_family;
  insert into public.t3a_content_object(identifier, family, title, dimension_id, current_operational_state) values ('SRC-D8-S4-002', 'source'::public.t3a_content_family, 'SEVEN OF TWELVE, EFFECTIVE IN TWO WEEKS', 'D8', 'not_loaded'::public.t3a_operational_state);
  insert into public.t3a_d1_content_version(content_object_id, version_no, approval_status, operational_state, body) select content_object_id, 'v2.1', 'drafting', 'not_loaded'::public.t3a_operational_state, '{"stage": 4, "title": "SEVEN OF TWELVE, EFFECTIVE IN TWO WEEKS", "source_digest": "7e5d97f0b870d66719c042a058f9f5004cf41a7fefc32fe512bce5fe9945dd10", "mentor_brief": "The facilitator facilitates the session and observes the observed participant only. At B1 the facilitator states the speaking order aloud: the three co-participants, then the observed participant. During the B2 round the facilitator does not look at, gesture towards or address the observed participant. The facilitator reads the scripted text verbatim, reacts to nothing, and does not press, repeat or escalate, whatever the observed participant says or does not say. The facilitator records only what was said about the work: nothing about any person in the room is recordable, including the absence of a reaction. The co-participants are role players; nothing they say is recorded, and nothing they say designates an action, a fact, a support, a commitment, an item of work or a measure.", "participant_pre_brief": "You are on the management team of a 280-room hotel. Yesterday evening seven of your twelve front-desk and guest services staff submitted resignations effective in two weeks. What the record shows: the resignations cite chronic understaffing and scheduling promises not kept; a scheduling improvement was agreed at a management meeting seven months ago and no change was implemented; occupancy over the next three weeks is above ninety percent; agency cover is available at about 2.2 times standard cost with a five-day lead time; the remaining five staff hold the same shift pattern the resignations cite; and the general manager has asked for a staffing position by tomorrow.", "script": [{"beat": "B1", "type": "SAY", "spoken": "Seven resignations, two weeks'' notice, ninety percent occupancy. I will go round in this order — front office, finance, the general manager''s office, then you. Two minutes each.", "direction": null, "capture": []}, {"beat": "B2", "type": "ROUND", "spoken": "Over to you, in the order I gave.", "direction": "Invite the three co-participants in the stated order. Do not address the observed participant.", "capture": [{"set": "C1", "state": "open"}, {"set": "C1b", "state": "open"}, {"set": "C2", "state": "open"}, {"set": "C2b", "state": "open"}, {"set": "C3", "state": "open"}, {"set": "C3b", "state": "open"}, {"set": "C4", "state": "open"}, {"set": "C4b", "state": "open"}, {"set": "C5", "state": "open"}, {"set": "C5b", "state": "open"}, {"set": "C6", "state": "open"}, {"set": "C6b", "state": "open"}, {"set": "C7", "state": "open"}, {"set": "C7b", "state": "open"}, {"set": "C8", "state": "open"}]}, {"beat": "B3", "type": "ASK", "spoken": "What has been done since yesterday evening, and what do we know?", "direction": "Read once, verbatim.", "capture": [{"set": "C1", "state": "update"}, {"set": "C1b", "state": "update"}, {"set": "C2", "state": "update"}, {"set": "C2b", "state": "update"}]}, {"beat": "B4", "type": "ASK", "spoken": "What are we doing about the pattern itself, and who are we going to?", "direction": "Read once, verbatim.", "capture": [{"set": "C3", "state": "update"}, {"set": "C3b", "state": "update"}, {"set": "C4", "state": "update"}, {"set": "C4b", "state": "update"}]}, {"beat": "B5", "type": "ASK", "spoken": "What still gets met, what continues and from when, what stops this recurring, and what goes on the record?", "direction": "Read once, verbatim.", "capture": [{"set": "C5", "state": "update"}, {"set": "C5b", "state": "update"}, {"set": "C6", "state": "update"}, {"set": "C6b", "state": "update"}, {"set": "C7", "state": "update"}, {"set": "C7b", "state": "update"}, {"set": "C8", "state": "update"}]}, {"beat": "B6", "type": "ASK", "spoken": "Just so the position is right — you said the scheduling change was implemented. Was it?", "direction": "Read once, verbatim.", "capture": [{"set": "C9", "state": "open"}]}, {"beat": "B7", "type": "SAY", "spoken": "That is the session. Thank you all.", "direction": "End the session.", "capture": [{"set": "C1", "state": "final"}, {"set": "C2", "state": "final"}, {"set": "C3", "state": "final"}, {"set": "C4", "state": "final"}, {"set": "C5", "state": "final"}, {"set": "C6", "state": "final"}, {"set": "C7", "state": "final"}, {"set": "C8", "state": "final"}, {"set": "C9", "state": "final"}]}], "co_participant_positions": [{"Co-participant": "CP-1", "Position stated at the round": "As front office, state the shift pattern the remaining five hold."}, {"Co-participant": "CP-2", "Position stated at the round": "As finance, state the agency cost multiple and lead time."}, {"Co-participant": "CP-3", "Position stated at the round": "As the general manager''s office, state the occupancy figure and the tomorrow deadline."}], "impact_assessment": [{"Part": "1. Shared material", "Finding": "Only the scripted situation is placed before the group, and it names no real organization", "Controls": "IA-01 shown in one shared window holding only the shared material"}, {"Part": "2. Identity", "Finding": "The observed participant is the authenticated participant; the three co-participants are role players", "Controls": "IA-02 platform account authentication; role players are never observed"}, {"Part": "3. Recording", "Finding": "Nothing is recorded", "Controls": "IA-03 no media persists"}, {"Part": "4. Correction", "Finding": "A correction reaches only the observed participant''s record", "Controls": "IA-04 a correction reaches only the observed participant''s record"}, {"Part": "5. Withdrawal", "Finding": "Withdrawal removes the participant''s determinations from composition only", "Controls": "IA-05 withdrawal excludes from composition; history retained"}, {"Part": "6. Group composition", "Finding": "One observed participant, three role players and one facilitator", "Controls": "IA-06 composition record and confidentiality undertaking from each role player"}, {"Part": "7. Accommodation", "Finding": "An accommodation is settled before composition and never changes the observation during the session", "Controls": "IA-07 settled before composition"}], "impact_result": "Completed", "question_applicability": [{"question": "Q-D8-01", "state": "DIRECT", "basis": "The situation lists four containment actions"}, {"question": "Q-D8-01b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D8-02", "state": "DIRECT", "basis": "The situation designates four facts about the setback"}, {"question": "Q-D8-02b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D8-03", "state": "DIRECT", "basis": "The situation lists two actions on the condition behind the setback"}, {"question": "Q-D8-03b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D8-04", "state": "DIRECT", "basis": "The situation lists three supports"}, {"question": "Q-D8-04b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D8-05", "state": "DIRECT", "basis": "The situation lists three commitments in force"}, {"question": "Q-D8-05b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D8-06", "state": "DIRECT", "basis": "The situation lists two items of work under way"}, {"question": "Q-D8-06b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D8-07", "state": "DIRECT", "basis": "The situation lists three measures against the condition arising again"}, {"question": "Q-D8-07b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D8-08", "state": "DIRECT", "basis": "The situation names a place a record could be made"}, {"question": "Q-D8-09", "state": "DIRECT", "basis": "The account test puts an earlier statement back"}], "material_map": [{"Item": "CM1", "Item text": "front-desk cover at above ninety percent occupancy for three weeks", "Where the participant meets it": "The pre-brief", "Quoted text": "occupancy over the next three weeks is above ninety percent"}, {"Item": "CM2", "Item text": "the staffing position by tomorrow", "Where the participant meets it": "The pre-brief", "Quoted text": "asked for a staffing position by tomorrow"}, {"Item": "CM3", "Item text": "the two weeks'' notice the seven are working", "Where the participant meets it": "Beat B1", "Quoted text": "Seven resignations, two weeks'' notice"}], "source_sheet": {"d8_situation_class": "SC-D8-6", "workplace_demand": "Giving the management position in a group round after seven of twelve front-desk staff resigned.", "relevant_conduct": "Which containment action was stated; which facts about the setback were named; what action on the condition behind the setback was stated; which support was stated as one to go to; which commitments in force were named as still to be met; what work was named as continuing, and from when; what was stated about the condition arising again; whether a record was stated, and where; what was stated when an earlier statement was put back.", "irrelevant_conduct": "The former supervisor named in the resignations; the co-participants'' statements.", "stated_standard": null, "stated_standard_source_quote_or_location": null, "cross_context_map": null, "serving_eligible": false, "recurrence_eligible": true, "replacement_required": false, "name_clearance_status": "CLEARED", "name_clearance_basis": "Controlled role and entity labels only; no real person or organization is named.", "sensitivity_flag": null, "permitted_administration_variance": "Pronunciation only; accommodations affecting turn order or response window are recorded and set timing_not_comparable.", "unsupported_inferences": "Who failed to implement the change, which is a D2 matter; any observation of the room''s state; anything about the seven who resigned, their reasons or their treatment.", "compatibility_class": "S4-GROUP-ROUND", "setback_established": "In the pre-brief: \"seven of your twelve front-desk and guest services staff submitted resignations.\"", "containment_actions": [{"id": "CA1", "text": "book agency cover against the five-day lead time"}, {"id": "CA2", "text": "implement the scheduling change agreed seven months ago"}, {"id": "CA3", "text": "set the remaining five''s shift pattern against what the resignations cite"}, {"id": "CA4", "text": "establish which shifts across three weeks are uncovered"}], "corrective_actions": [{"id": "CR1", "text": "implement the scheduling change agreed seven months ago"}, {"id": "CR2", "text": "set the remaining five''s shift pattern against what the resignations cite"}], "designated_facts": [{"id": "DF1", "text": "what the resignations cite, in their own terms"}, {"id": "DF2", "text": "what the seven-month-old scheduling agreement provided and that nothing was implemented"}, {"id": "DF3", "text": "what the remaining five''s shift pattern is"}, {"id": "DF4", "text": "what agency cover costs and how long it takes to arrive"}], "available_supports": [{"id": "SU1", "text": "the general manager, expecting a position tomorrow"}, {"id": "SU2", "text": "the agency, at the stated cost and lead time"}, {"id": "SU3", "text": "the remaining five staff"}], "standing_commitments": [{"id": "CM1", "text": "front-desk cover at above ninety percent occupancy for three weeks"}, {"id": "CM2", "text": "the staffing position by tomorrow"}, {"id": "CM3", "text": "the two weeks'' notice the seven are working"}], "work_in_progress": [{"id": "WP1", "text": "the three weeks'' shift coverage"}, {"id": "WP2", "text": "the scheduling change never implemented"}], "recurrence_measures": [{"id": "RM1", "text": "the seven-month-old scheduling change implemented with a date"}, {"id": "RM2", "text": "management-meeting agreements carrying an implementation owner and deadline"}, {"id": "RM3", "text": "shift pattern reviewed against retention each quarter"}], "recurring_condition": "A scheduling change agreed seven months ago and never implemented, cited in the resignations.", "formal_record_state": "The seven resignation letters and the seven-month-old meeting record.", "record_place": "The staffing record and the management meeting actions log.", "who_knows": "The management team and the remaining five.", "decision_origin": "The seven staff''s decision.", "account_test_point": "B6", "account_test_record": "The situation records that no change was implemented after the scheduling improvement was agreed.", "list_note": null, "source_note": null, "situation_class_label": "Work that must continue with its people, tools or resources reduced", "observation_mode_label": "group_session", "min_seconds": 900, "max_seconds": 1500}, "source_identifier": "SRC-D8-S4-002", "stage_code": "S4", "source_version_hash": "7e5d97f0b870d66719c042a058f9f5004cf41a7fefc32fe512bce5fe9945dd10", "serving_eligible": false, "verbatim": ""}'::jsonb from public.t3a_content_object where identifier = 'SRC-D8-S4-002' and family = 'source'::public.t3a_content_family;
  insert into public.t3a_content_object(identifier, family, title, dimension_id, current_operational_state) values ('SRC-D8-S4-003', 'source'::public.t3a_content_family, 'THE BATCH THAT HAS TO COME BACK', 'D8', 'not_loaded'::public.t3a_operational_state);
  insert into public.t3a_d1_content_version(content_object_id, version_no, approval_status, operational_state, body) select content_object_id, 'v2.1', 'drafting', 'not_loaded'::public.t3a_operational_state, '{"stage": 4, "title": "THE BATCH THAT HAS TO COME BACK", "source_digest": "4b060dc72a95f80caf211c52a97b395436802be080f8cbbb35442f055d2e07f7", "mentor_brief": "The facilitator facilitates the session and observes the observed participant only. At B1 the facilitator states the speaking order aloud: the three co-participants, then the observed participant. During the B2 round the facilitator does not look at, gesture towards or address the observed participant. The facilitator reads the scripted text verbatim, reacts to nothing, and does not press, repeat or escalate, whatever the observed participant says or does not say. The facilitator records only what was said about the work: nothing about any person in the room is recordable, including the absence of a reaction. The co-participants are role players; nothing they say is recorded, and nothing they say designates an action, a fact, a support, a commitment, an item of work or a measure.", "participant_pre_brief": "You are on the product operations team of a consumer electronics manufacturer. Quality assurance has confirmed that a batch of a wireless charging pad manufactured over a six-week window carries a component fault. About 185,000 units have sold across two countries over eight months. What the record shows: the fault is in a supplied component and the supplier''s incoming inspection was waived for that window under a schedule pressure exception; three customer complaints over the past month pointed at the same symptom and were closed as isolated; regulatory reporting obligations differ between the two countries; retail partners hold about 12,000 units in stock; and the executive sponsor has asked for a recall position by end of day.", "script": [{"beat": "B1", "type": "SAY", "spoken": "The fault is confirmed and about 185,000 units are out. I will go round in this order — quality, sales, regulatory, then product operations. Two minutes each.", "direction": null, "capture": []}, {"beat": "B2", "type": "ROUND", "spoken": "Over to you, in the order I gave.", "direction": "Invite the three co-participants in the stated order. Do not address the observed participant.", "capture": [{"set": "C1", "state": "open"}, {"set": "C1b", "state": "open"}, {"set": "C2", "state": "open"}, {"set": "C2b", "state": "open"}, {"set": "C3", "state": "open"}, {"set": "C3b", "state": "open"}, {"set": "C4", "state": "open"}, {"set": "C4b", "state": "open"}, {"set": "C5", "state": "open"}, {"set": "C5b", "state": "open"}, {"set": "C6", "state": "open"}, {"set": "C6b", "state": "open"}, {"set": "C7", "state": "open"}, {"set": "C7b", "state": "open"}, {"set": "C8", "state": "open"}]}, {"beat": "B3", "type": "ASK", "spoken": "What has been done since confirmation, and what do we know?", "direction": "Read once, verbatim.", "capture": [{"set": "C1", "state": "update"}, {"set": "C1b", "state": "update"}, {"set": "C2", "state": "update"}, {"set": "C2b", "state": "update"}]}, {"beat": "B4", "type": "ASK", "spoken": "What are we doing about the inspection waiver, and who are we going to?", "direction": "Read once, verbatim.", "capture": [{"set": "C3", "state": "update"}, {"set": "C3b", "state": "update"}, {"set": "C4", "state": "update"}, {"set": "C4b", "state": "update"}]}, {"beat": "B5", "type": "ASK", "spoken": "What still gets met, what continues and from when, what stops this recurring, and what goes on the record?", "direction": "Read once, verbatim.", "capture": [{"set": "C5", "state": "update"}, {"set": "C5b", "state": "update"}, {"set": "C6", "state": "update"}, {"set": "C6b", "state": "update"}, {"set": "C7", "state": "update"}, {"set": "C7b", "state": "update"}, {"set": "C8", "state": "update"}]}, {"beat": "B6", "type": "ASK", "spoken": "Just so the position is right — you said the three complaints were investigated. Were they?", "direction": "Read once, verbatim.", "capture": [{"set": "C9", "state": "open"}]}, {"beat": "B7", "type": "SAY", "spoken": "That is the session. Thank you all.", "direction": "End the session.", "capture": [{"set": "C1", "state": "final"}, {"set": "C2", "state": "final"}, {"set": "C3", "state": "final"}, {"set": "C4", "state": "final"}, {"set": "C5", "state": "final"}, {"set": "C6", "state": "final"}, {"set": "C7", "state": "final"}, {"set": "C8", "state": "final"}, {"set": "C9", "state": "final"}]}], "co_participant_positions": [{"Co-participant": "CP-1", "Position stated at the round": "As quality assurance, state the confirmed fault and the manufacture window."}, {"Co-participant": "CP-2", "Position stated at the round": "As sales, state the retail stock figure."}, {"Co-participant": "CP-3", "Position stated at the round": "As regulatory, state that obligations differ between the two countries."}], "impact_assessment": [{"Part": "1. Shared material", "Finding": "Only the scripted situation is placed before the group, and it names no real organization", "Controls": "IA-01 shown in one shared window holding only the shared material"}, {"Part": "2. Identity", "Finding": "The observed participant is the authenticated participant; the three co-participants are role players", "Controls": "IA-02 platform account authentication; role players are never observed"}, {"Part": "3. Recording", "Finding": "Nothing is recorded", "Controls": "IA-03 no media persists"}, {"Part": "4. Correction", "Finding": "A correction reaches only the observed participant''s record", "Controls": "IA-04 a correction reaches only the observed participant''s record"}, {"Part": "5. Withdrawal", "Finding": "Withdrawal removes the participant''s determinations from composition only", "Controls": "IA-05 withdrawal excludes from composition; history retained"}, {"Part": "6. Group composition", "Finding": "One observed participant, three role players and one facilitator", "Controls": "IA-06 composition record and confidentiality undertaking from each role player"}, {"Part": "7. Accommodation", "Finding": "An accommodation is settled before composition and never changes the observation during the session", "Controls": "IA-07 settled before composition"}], "impact_result": "Completed", "question_applicability": [{"question": "Q-D8-01", "state": "DIRECT", "basis": "The situation lists four containment actions"}, {"question": "Q-D8-01b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D8-02", "state": "DIRECT", "basis": "The situation designates four facts about the setback"}, {"question": "Q-D8-02b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D8-03", "state": "DIRECT", "basis": "The situation lists two actions on the condition behind the setback"}, {"question": "Q-D8-03b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D8-04", "state": "DIRECT", "basis": "The situation lists three supports"}, {"question": "Q-D8-04b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D8-05", "state": "DIRECT", "basis": "The situation lists three commitments in force"}, {"question": "Q-D8-05b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D8-06", "state": "DIRECT", "basis": "The situation lists two items of work under way"}, {"question": "Q-D8-06b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D8-07", "state": "DIRECT", "basis": "The situation lists three measures against the condition arising again"}, {"question": "Q-D8-07b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D8-08", "state": "DIRECT", "basis": "The situation names a place a record could be made"}, {"questio