  insert into public.t3a_d1_content_version(content_object_id, version_no, approval_status, operational_state, body) select content_object_id, 'v2.1', 'drafting', 'not_loaded'::public.t3a_operational_state, '{"stage": 4, "title": "THE SOLE SUPPLIER THAT FILED THIS MORNING", "source_digest": "ebf2fd6194ed0e119974259c52808b4c66a1668e469d41775f6acac1fe740ffa", "mentor_brief": "The facilitator facilitates the session and observes the observed participant only. At B1 the facilitator states the speaking order aloud: the three co-participants, then the observed participant. During the B2 round the facilitator does not look at, gesture towards or address the observed participant. The facilitator reads the scripted text verbatim, reacts to nothing, and does not press, repeat or escalate, whatever the observed participant says or does not say. The facilitator records only what was said about the work: nothing about any person in the room is recordable, including the absence of a reaction. The co-participants are role players; nothing they say is recorded, and nothing they say designates an action, a fact, a support, a commitment, an item of work or a measure.", "participant_pre_brief": "You are on the procurement and operations team of a parts manufacturer supplying brake components to three larger suppliers who serve assembly plants. At 06:30 you were notified that your sole supplier of precision-machined steel housings has filed for bankruptcy protection, effective immediately. What the record shows: housings on hand cover eleven production days; two alternative suppliers were qualified in a sourcing review two years ago and neither has been kept current; requalification takes about six weeks; your three customers hold contractual line-stoppage penalties; a single-source risk was raised in the same sourcing review and no second source was established; and your operations director has asked for a position by end of day.", "script": [{"beat": "B1", "type": "SAY", "spoken": "Our sole housing supplier filed this morning. We have what is on hand. I will go round in this order — production, sales, quality, then procurement. Two minutes each.", "direction": null, "capture": []}, {"beat": "B2", "type": "ROUND", "spoken": "Over to you, in the order I gave.", "direction": "Invite the three co-participants in the stated order. Do not address the observed participant.", "capture": [{"set": "C1", "state": "open"}, {"set": "C1b", "state": "open"}, {"set": "C2", "state": "open"}, {"set": "C2b", "state": "open"}, {"set": "C3", "state": "open"}, {"set": "C3b", "state": "open"}, {"set": "C4", "state": "open"}, {"set": "C4b", "state": "open"}, {"set": "C5", "state": "open"}, {"set": "C5b", "state": "open"}, {"set": "C6", "state": "open"}, {"set": "C6b", "state": "open"}, {"set": "C7", "state": "open"}, {"set": "C7b", "state": "open"}, {"set": "C8", "state": "open"}]}, {"beat": "B3", "type": "ASK", "spoken": "What has been done since 06:30, and what do we know?", "direction": "Read once, verbatim.", "capture": [{"set": "C1", "state": "update"}, {"set": "C1b", "state": "update"}, {"set": "C2", "state": "update"}, {"set": "C2b", "state": "update"}]}, {"beat": "B4", "type": "ASK", "spoken": "What are we doing about the single-source position, and who are we going to?", "direction": "Read once, verbatim.", "capture": [{"set": "C3", "state": "update"}, {"set": "C3b", "state": "update"}, {"set": "C4", "state": "update"}, {"set": "C4b", "state": "update"}]}, {"beat": "B5", "type": "ASK", "spoken": "What still gets met, what continues and from when, what stops this recurring, and what goes on the record?", "direction": "Read once, verbatim.", "capture": [{"set": "C5", "state": "update"}, {"set": "C5b", "state": "update"}, {"set": "C6", "state": "update"}, {"set": "C6b", "state": "update"}, {"set": "C7", "state": "update"}, {"set": "C7b", "state": "update"}, {"set": "C8", "state": "update"}]}, {"beat": "B6", "type": "ASK", "spoken": "Just so the position is right — you said the alternative suppliers are current. Are they?", "direction": "Read once, verbatim.", "capture": [{"set": "C9", "state": "open"}]}, {"beat": "B7", "type": "SAY", "spoken": "That is the session. Thank you all.", "direction": "End the session.", "capture": [{"set": "C1", "state": "final"}, {"set": "C2", "state": "final"}, {"set": "C3", "state": "final"}, {"set": "C4", "state": "final"}, {"set": "C5", "state": "final"}, {"set": "C6", "state": "final"}, {"set": "C7", "state": "final"}, {"set": "C8", "state": "final"}, {"set": "C9", "state": "final"}]}], "co_participant_positions": [{"Co-participant": "CP-1", "Position stated at the round": "As production, state the eleven days of housings on hand."}, {"Co-participant": "CP-2", "Position stated at the round": "As sales, state the line-stoppage penalties."}, {"Co-participant": "CP-3", "Position stated at the round": "As quality, state that requalification takes about six weeks."}], "impact_assessment": [{"Part": "1. Shared material", "Finding": "Only the scripted situation is placed before the group, and it names no real organization", "Controls": "IA-01 shown in one shared window holding only the shared material"}, {"Part": "2. Identity", "Finding": "The observed participant is the authenticated participant; the three co-participants are role players", "Controls": "IA-02 platform account authentication; role players are never observed"}, {"Part": "3. Recording", "Finding": "Nothing is recorded", "Controls": "IA-03 no media persists"}, {"Part": "4. Correction", "Finding": "A correction reaches only the observed participant''s record", "Controls": "IA-04 a correction reaches only the observed participant''s record"}, {"Part": "5. Withdrawal", "Finding": "Withdrawal removes the participant''s determinations from composition only", "Controls": "IA-05 withdrawal excludes from composition; history retained"}, {"Part": "6. Group composition", "Finding": "One observed participant, three role players and one facilitator", "Controls": "IA-06 composition record and confidentiality undertaking from each role player"}, {"Part": "7. Accommodation", "Finding": "An accommodation is settled before composition and never changes the observation during the session", "Controls": "IA-07 settled before composition"}], "impact_result": "Completed", "question_applicability": [{"question": "Q-D8-01", "state": "DIRECT", "basis": "The situation lists three containment actions"}, {"question": "Q-D8-01b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D8-02", "state": "DIRECT", "basis": "The situation designates four facts about the setback"}, {"question": "Q-D8-02b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D8-03", "state": "DIRECT", "basis": "The situation lists two actions on the condition behind the setback"}, {"question": "Q-D8-03b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D8-04", "state": "DIRECT", "basis": "The situation lists three supports"}, {"question": "Q-D8-04b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D8-05", "state": "DIRECT", "basis": "The situation lists three commitments in force"}, {"question": "Q-D8-05b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D8-06", "state": "DIRECT", "basis": "The situation lists two items of work under way"}, {"question": "Q-D8-06b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D8-07", "state": "DIRECT", "basis": "The situation lists three measures against the condition arising again"}, {"question": "Q-D8-07b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D8-08", "state": "DIRECT", "basis": "The situation names a place a record could be made"}, {"question": "Q-D8-09", "state": "DIRECT", "basis": "The account test puts an earlier statement back"}], "material_map": [{"Item": "CM1", "Item text": "the housings on hand for eleven production days", "Where the participant meets it": "The pre-brief", "Quoted text": "housings on hand cover eleven production days"}, {"Item": "CM2", "Item text": "the position to the operations director by end of day", "Where the participant meets it": "The pre-brief", "Quoted text": "your operations director has asked for a position by end of day"}, {"Item": "CM3", "Item text": "the contractual penalties the customers hold", "Where the participant meets it": "The pre-brief", "Quoted text": "customers hold contractual line-stoppage penalties"}], "source_sheet": {"d8_situation_class": "SC-D8-4", "workplace_demand": "Giving the procurement position in a group round after the sole supplier of a component filed for bankruptcy protection.", "relevant_conduct": "Which containment action was stated; which facts about the setback were named; what action on the condition behind the setback was stated; which support was stated as one to go to; which commitments in force were named as still to be met; what work was named as continuing, and from when; what was stated about the condition arising again; whether a record was stated, and where; what was stated when an earlier statement was put back.", "irrelevant_conduct": "The supplier; the customers'' penalties as leverage; the co-participants'' statements.", "stated_standard": null, "stated_standard_source_quote_or_location": null, "cross_context_map": null, "serving_eligible": false, "recurrence_eligible": true, "replacement_required": false, "name_clearance_status": "CLEARED", "name_clearance_basis": "Controlled role and entity labels only; no real person or organization is named.", "sensitivity_flag": null, "permitted_administration_variance": "Pronunciation only; accommodations affecting turn order or response window are recorded and set timing_not_comparable.", "unsupported_inferences": "Who failed to act on the sourcing review, which is a D2 matter; any observation of the room''s state; any inference from early versus late framing.", "compatibility_class": "S4-GROUP-ROUND", "setback_established": "In the pre-brief: \"your sole supplier... has filed for bankruptcy protection, effective immediately.\"", "containment_actions": [{"id": "CA1", "text": "confirm the housings on hand and the production days they cover"}, {"id": "CA2", "text": "open requalification on the two suppliers from the sourcing review"}, {"id": "CA3", "text": "establish what the bankruptcy protection permits of existing orders"}], "corrective_actions": [{"id": "CR1", "text": "open requalification on the two suppliers from the sourcing review"}, {"id": "CR2", "text": "establish a second source requirement for every single-sourced component"}], "designated_facts": [{"id": "DF1", "text": "how many production days the housings on hand cover"}, {"id": "DF2", "text": "which alternative suppliers were qualified and that neither is current"}, {"id": "DF3", "text": "how long requalification takes"}, {"id": "DF4", "text": "that single-source risk was raised in the same review and no second source followed"}], "available_supports": [{"id": "SU1", "text": "the operations director, expecting a position by end of day"}, {"id": "SU2", "text": "quality, who run requalification"}, {"id": "SU3", "text": "the two-year-old sourcing review naming the alternatives"}], "standing_commitments": [{"id": "CM1", "text": "the housings on hand for eleven production days"}, {"id": "CM2", "text": "the position to the operations director by end of day"}, {"id": "CM3", "text": "the contractual penalties the customers hold"}], "work_in_progress": [{"id": "WP1", "text": "production over the eleven covered days"}, {"id": "WP2", "text": "requalification of the two alternatives"}], "recurrence_measures": [{"id": "RM1", "text": "a second qualified source on every critical component"}, {"id": "RM2", "text": "qualified alternatives requalified on a stated cycle"}, {"id": "RM3", "text": "sourcing review findings carrying an implementation owner and date"}], "recurring_condition": "Single-source risk raised two years ago in the same review, with no second source established since.", "formal_record_state": "The bankruptcy notification and the two-year-old sourcing review.", "record_place": "The supplier risk register.", "who_knows": "Production, sales, quality and the operations director.", "decision_origin": "The supplier''s filing, external.", "account_test_point": "B6", "account_test_record": "The situation records that neither alternative supplier has been kept current.", "list_note": null, "source_note": null, "situation_class_label": "A condition that has disrupted the work before, producing the same disruption again", "observation_mode_label": "group_session", "min_seconds": 900, "max_seconds": 1500}, "source_identifier": "SRC-D8-S4-009", "stage_code": "S4", "source_version_hash": "ebf2fd6194ed0e119974259c52808b4c66a1668e469d41775f6acac1fe740ffa", "serving_eligible": false, "verbatim": ""}'::jsonb from public.t3a_content_object where identifier = 'SRC-D8-S4-009' and family = 'source'::public.t3a_content_family;
  insert into public.t3a_content_object(identifier, family, title, dimension_id, current_operational_state) values ('SRC-D8-S4-010', 'source'::public.t3a_content_family, 'SIXTY PEOPLE OUTSIDE THE BUILDING', 'D8', 'not_loaded'::public.t3a_operational_state);
  insert into public.t3a_d1_content_version(content_object_id, version_no, approval_status, operational_state, body) select content_object_id, 'v2.1', 'drafting', 'not_loaded'::public.t3a_operational_state, '{"stage": 4, "title": "SIXTY PEOPLE OUTSIDE THE BUILDING", "source_digest": "31d7a1ca7e8f9396f7623a88c98f15473a42434e7569005aa39e2d8a569d7945", "mentor_brief": "The facilitator facilitates the session and observes the observed participant only. At B1 the facilitator states the speaking order aloud: the three co-participants, then the observed participant. During the B2 round the facilitator does not look at, gesture towards or address the observed participant. The facilitator reads the scripted text verbatim, reacts to nothing, and does not press, repeat or escalate, whatever the observed participant says or does not say. The facilitator records only what was said about the work: nothing about any person in the room is recordable, including the absence of a reaction. The co-participants are role players; nothing they say is recorded, and nothing they say designates an action, a fact, a support, a commitment, an item of work or a measure.", "participant_pre_brief": "You are on the community relations team of a mining company operating three active sites and in the environmental assessment phase for a proposed fourth near a community of about 2,200. This morning about sixty people have gathered outside headquarters opposing the proposed site. What the record shows: the assessment''s public comment window closed eleven days ago with fourteen submissions received; a community liaison committee was established for the proposed site two years ago and has not met in fourteen months; the regulator requires a record of community engagement as part of the assessment; the three active sites'' operations are unaffected; a scheduled assessment submission is due to the regulator in three weeks; and the chief executive has asked for a position by 2:00 PM.", "script": [{"beat": "B1", "type": "SAY", "spoken": "There are about sixty people outside and the assessment submission is due in three weeks. I will go round in this order — legal, operations, the chief executive''s office, then community relations. Two minutes each.", "direction": null, "capture": []}, {"beat": "B2", "type": "ROUND", "spoken": "Over to you, in the order I gave.", "direction": "Invite the three co-participants in the stated order. Do not address the observed participant.", "capture": [{"set": "C1", "state": "open"}, {"set": "C1b", "state": "open"}, {"set": "C2", "state": "open"}, {"set": "C2b", "state": "open"}, {"set": "C3", "state": "open"}, {"set": "C3b", "state": "open"}, {"set": "C4", "state": "open"}, {"set": "C4b", "state": "open"}, {"set": "C5", "state": "open"}, {"set": "C5b", "state": "open"}, {"set": "C6", "state": "open"}, {"set": "C6b", "state": "open"}, {"set": "C7", "state": "open"}, {"set": "C7b", "state": "open"}, {"set": "C8", "state": "open"}]}, {"beat": "B3", "type": "ASK", "spoken": "What has been done this morning, and what do we know?", "direction": "Read once, verbatim.", "capture": [{"set": "C1", "state": "update"}, {"set": "C1b", "state": "update"}, {"set": "C2", "state": "update"}, {"set": "C2b", "state": "update"}]}, {"beat": "B4", "type": "ASK", "spoken": "What are we doing about the engagement record, and who are we going to?", "direction": "Read once, verbatim.", "capture": [{"set": "C3", "state": "update"}, {"set": "C3b", "state": "update"}, {"set": "C4", "state": "update"}, {"set": "C4b", "state": "update"}]}, {"beat": "B5", "type": "ASK", "spoken": "What still gets met, what continues and from when, what stops this recurring, and what goes on the record?", "direction": "Read once, verbatim.", "capture": [{"set": "C5", "state": "update"}, {"set": "C5b", "state": "update"}, {"set": "C6", "state": "update"}, {"set": "C6b", "state": "update"}, {"set": "C7", "state": "update"}, {"set": "C7b", "state": "update"}, {"set": "C8", "state": "update"}]}, {"beat": "B6", "type": "ASK", "spoken": "Just so the position is right — you said the liaison committee has been meeting. Has it?", "direction": "Read once, verbatim.", "capture": [{"set": "C9", "state": "open"}]}, {"beat": "B7", "type": "SAY", "spoken": "That is the session. Thank you all.", "direction": "End the session.", "capture": [{"set": "C1", "state": "final"}, {"set": "C2", "state": "final"}, {"set": "C3", "state": "final"}, {"set": "C4", "state": "final"}, {"set": "C5", "state": "final"}, {"set": "C6", "state": "final"}, {"set": "C7", "state": "final"}, {"set": "C8", "state": "final"}, {"set": "C9", "state": "final"}]}], "co_participant_positions": [{"Co-participant": "CP-1", "Position stated at the round": "As legal, state that the comment window closed eleven days ago."}, {"Co-participant": "CP-2", "Position stated at the round": "As operations, state that the three active sites are unaffected."}, {"Co-participant": "CP-3", "Position stated at the round": "As the chief executive''s office, state the 2:00 PM deadline and the three-week submission."}], "impact_assessment": [{"Part": "1. Shared material", "Finding": "Only the scripted situation is placed before the group, and it names no real organization", "Controls": "IA-01 shown in one shared window holding only the shared material"}, {"Part": "2. Identity", "Finding": "The observed participant is the authenticated participant; the three co-participants are role players", "Controls": "IA-02 platform account authentication; role players are never observed"}, {"Part": "3. Recording", "Finding": "Nothing is recorded", "Controls": "IA-03 no media persists"}, {"Part": "4. Correction", "Finding": "A correction reaches only the observed participant''s record", "Controls": "IA-04 a correction reaches only the observed participant''s record"}, {"Part": "5. Withdrawal", "Finding": "Withdrawal removes the participant''s determinations from composition only", "Controls": "IA-05 withdrawal excludes from composition; history retained"}, {"Part": "6. Group composition", "Finding": "One observed participant, three role players and one facilitator", "Controls": "IA-06 composition record and confidentiality undertaking from each role player"}, {"Part": "7. Accommodation", "Finding": "An accommodation is settled before composition and never changes the observation during the session", "Controls": "IA-07 settled before composition"}], "impact_result": "Completed", "question_applicability": [{"question": "Q-D8-01", "state": "DIRECT", "basis": "The situation lists three containment actions"}, {"question": "Q-D8-01b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D8-02", "state": "DIRECT", "basis": "The situation designates four facts about the setback"}, {"question": "Q-D8-02b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D8-03", "state": "DIRECT", "basis": "The situation lists two actions on the condition behind the setback"}, {"question": "Q-D8-03b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D8-04", "state": "DIRECT", "basis": "The situation lists three supports"}, {"question": "Q-D8-04b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D8-05", "state": "DIRECT", "basis": "The situation lists three commitments in force"}, {"question": "Q-D8-05b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D8-06", "state": "DIRECT", "basis": "The situation lists two items of work under way"}, {"question": "Q-D8-06b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D8-07", "state": "DIRECT", "basis": "The situation lists three measures against the condition arising again"}, {"question": "Q-D8-07b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D8-08", "state": "DIRECT", "basis": "The situation names a place a record could be made"}, {"question": "Q-D8-09", "state": "DIRECT", "basis": "The account test puts an earlier statement back"}], "material_map": [{"Item": "CM1", "Item text": "the assessment submission in three weeks", "Where the participant meets it": "Beat B1", "Quoted text": "assessment submission is due in three weeks"}, {"Item": "CM2", "Item text": "the regulator''s engagement record requirement", "Where the participant meets it": "The pre-brief", "Quoted text": "the regulator requires a record of community engagement"}, {"Item": "CM3", "Item text": "the position to the chief executive by 2:00 PM", "Where the participant meets it": "The pre-brief", "Quoted text": "the chief executive has asked for a position by 2:00 PM"}], "source_sheet": {"d8_situation_class": "SC-D8-2", "workplace_demand": "Giving the community relations position in a group round after people gathered outside headquarters opposing a proposed site.", "relevant_conduct": "Which containment action was stated; which facts about the setback were named; what action on the condition behind the setback was stated; which support was stated as one to go to; which commitments in force were named as still to be met; what work was named as continuing, and from when; what was stated about the condition arising again; whether a record was stated, and where; what was stated when an earlier statement was put back.", "irrelevant_conduct": "The protestors; the merits of the proposed site; the co-participants'' statements.", "stated_standard": null, "stated_standard_source_quote_or_location": null, "cross_context_map": null, "serving_eligible": false, "recurrence_eligible": true, "replacement_required": false, "name_clearance_status": "CLEARED", "name_clearance_basis": "Controlled role and entity labels only; no real person or organization is named.", "sensitivity_flag": null, "permitted_administration_variance": "Pronunciation only; accommodations affecting turn order or response window are recorded and set timing_not_comparable.", "unsupported_inferences": "Who allowed the committee to lapse, which is a D2 matter; what is said publicly, which is a D4 matter; any view of the people outside, their position or their entitlement to it.", "compatibility_class": "S4-GROUP-ROUND", "setback_established": "In the pre-brief: \"about sixty people have gathered outside headquarters opposing the proposed site.\"", "containment_actions": [{"id": "CA1", "text": "establish what the fourteen submissions raised"}, {"id": "CA2", "text": "reconvene the community liaison committee"}, {"id": "CA3", "text": "confirm what the three-week submission must contain on engagement"}], "corrective_actions": [{"id": "CR1", "text": "reconvene the community liaison committee"}, {"id": "CR2", "text": "bring the engagement record to what the regulator requires"}], "designated_facts": [{"id": "DF1", "text": "when the comment window closed and how many submissions were received"}, {"id": "DF2", "text": "that the liaison committee has not met in fourteen months"}, {"id": "DF3", "text": "what the regulator requires of an engagement record"}, {"id": "DF4", "text": "what the three-week submission is due to contain"}], "available_supports": [{"id": "SU1", "text": "legal, holding the assessment process position"}, {"id": "SU2", "text": "the community liaison committee, dormant but constituted"}, {"id": "SU3", "text": "the chief executive, expecting a position by 2:00 PM"}], "standing_commitments": [{"id": "CM1", "text": "the assessment submission in three weeks"}, {"id": "CM2", "text": "the regulator''s engagement record requirement"}, {"id": "CM3", "text": "the position to the chief executive by 2:00 PM"}], "work_in_progress": [{"id": "WP1", "text": "the environmental assessment for the proposed site"}, {"id": "WP2", "text": "the three active sites'' operations"}], "recurrence_measures": [{"id": "RM1", "text": "the liaison committee meeting on a stated cycle with a recorded attendance"}, {"id": "RM2", "text": "the engagement record reviewed against the regulator''s requirement each quarter"}, {"id": "RM3", "text": "a dormancy trigger on any constituted committee past a stated interval"}], "recurring_condition": "A committee constituted two years ago that has not met in fourteen months.", "formal_record_state": "The fourteen submissions and the committee''s constitution.", "record_place": "The assessment engagement record.", "who_knows": "Legal, operations and the chief executive.", "decision_origin": null, "account_test_point": "B6", "account_test_record": "The situation records that the liaison committee has not met in fourteen months.", "list_note": null, "source_note": null, "situation_class_label": "Sustained work ended or withdrawn by a decision outside the participant''s control", "observation_mode_label": "group_session", "min_seconds": 900, "max_seconds": 1500}, "source_identifier": "SRC-D8-S4-010", "stage_code": "S4", "source_version_hash": "31d7a1ca7e8f9396f7623a88c98f15473a42434e7569005aa39e2d8a569d7945", "serving_eligible": false, "verbatim": ""}'::jsonb from public.t3a_content_object where identifier = 'SRC-D8-S4-010' and family = 'source'::public.t3a_content_family;
  insert into public.t3a_d1_content_load_event(env_state, content_object_id, content_version_id, governed_status, notes) select 'design_only', o.content_object_id, v.content_version_id, 'DISABLED_PENDING_DECISION', 'T3A-D8-EXEC-001 v2.1 loaded not servable' from public.t3a_content_object o join public.t3a_d1_content_version v on v.content_object_id = o.content_object_id where o.dimension_id = 'D8' and o.identifier like 'T3A-D8-EXEC-001%' or (o.dimension_id = 'D8' and o.identifier like 'SRC-D8-%');
